import SwiftUI
import FoundationModels

/// Defaults and corpus assembly for the AI Insights view. Runs entirely
/// on-device (Apple Intelligence); no text leaves the Mac.
nonisolated enum AIInsights {

    /// The default prompt — editable in Settings → AI. It teaches the model
    /// to read Relations lines and any Visual-Meta/BibTeX remnants as
    /// metadata, never as content; to head each section with ## so the
    /// report unfurls section by section; and to cite documents by address
    /// so its references become live links.
    static let defaultPrompt = """
    You are reading a community of thinkers' documents so they can see their own work more clearly. Your job is augmentation — raising the group's collective capability — not summary for its own sake.

    How to read the material: each document begins with a == line giving its title, author, date, and address. A following Relations: line is metadata — typed links between documents (cites, responds-to, extends, supports, questions, disagrees-with, revises) — treat it as structure, never as prose. Anything resembling Visual-Meta or BibTeX (@{...} markers, key = {value} fields) is metadata about a document, not content; disregard it as text even if fragments appear.

    Report in plain, concise prose in five sections, beginning each with a heading line of ## and the section name, exactly these:

    ## The live questions
    What this community is actually working out right now.

    ## Agreement and dispute
    Where documents support or contradict one another; name the documents.

    ## The unargued
    Assumptions several documents share but none examines.

    ## Missing connections
    Documents that bear on each other without linking; say why the pairing matters.

    ## The next document
    The one piece this community most needs someone to write.

    When you mention a document, include its address in brackets — e.g. [f.hegla.093252x] — so your reference becomes a live link. Do not flatter. Brevity honors the reader.
    """

    /// Assembles the library's text for the model: newest documents first
    /// within a character budget the on-device model can hold, Visual-Meta
    /// appendices excluded, relations passed as marked metadata.
    static func corpus(from entries: [IndexEntry],
                       characterBudget: Int = 14_000) -> (text: String, includedCount: Int, omittedCount: Int) {
        var blocks: [String] = []
        var total = 0
        var included = 0
        let ordered = entries.sorted { $0.doc.listedDate > $1.doc.listedDate }
        for entry in ordered {
            guard let body = entry.doc.body else { continue }
            let appendixIDs = entry.doc.visualMetaParagraphIDs
            let text = body
                .filter { !appendixIDs.contains($0.id) }
                .map(\.displayText)
                .joined(separator: "\n")
            var header = "== \"\(entry.doc.title)\" by \(entry.doc.displayAuthor) (\(entry.doc.listedDateText), address \(entry.id))"
            if !entry.doc.links.isEmpty {
                let relations = entry.doc.links.map { link in
                    "\(link.rel ?? "links-to") [\(link.to)\(link.fragment.map { "#\($0)" } ?? "")]"
                }.joined(separator: " · ")
                header += "\nRelations: \(relations)"
            }
            let block = header + "\n" + text
            guard total + block.count <= characterBudget else { break }
            blocks.append(block)
            total += block.count
            included += 1
        }
        let textDocumentCount = entries.filter { $0.doc.body != nil }.count
        return (blocks.joined(separator: "\n\n"),
                included,
                max(0, textDocumentCount - included))
    }
}

/// A view of what the community is thinking, written by the on-device
/// model reading every document's text (never its metadata). The report
/// arrives furled: headings show, and the reader unfurls what they want.
struct AIInsightsView: View {
    @Environment(AppModel.self) private var model
    @AppStorage(AppSettings.aiInsightsPromptKey) private var prompt = AIInsights.defaultPrompt
    @State private var output = ""
    @State private var isRunning = false
    @State private var errorText: String?
    @State private var unfurledSections: Set<Int> = []

    var body: some View {
        Group {
            switch SystemLanguageModel.default.availability {
            case .available:
                content
            case .unavailable(let reason):
                ContentUnavailableView {
                    Label("Apple Intelligence Unavailable", systemImage: "sparkles")
                } description: {
                    Text("AI Insights uses the on-device model, so no text leaves this Mac. \(describe(reason))")
                }
            }
        }
        // The model cites documents by address; clicking one leaves this
        // view for the reader, exactly as a human-written link would.
        .environment(\.openURL, OpenURLAction { url in
            if url.scheme?.lowercased() == "origamitext" {
                let before = model.current?.doc.id
                model.handleURL(url)
                if model.current?.doc.id != before {
                    model.sidebarSelection = .allDocuments
                }
                return .handled
            }
            return .systemAction
        })
    }

    private var content: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 12) {
                HStack(spacing: 10) {
                    Button {
                        run()
                    } label: {
                        Label(isRunning ? "Reading…" : "Generate Insights", systemImage: "sparkles")
                    }
                    .disabled(isRunning)
                    if isRunning {
                        ProgressView()
                            .controlSize(.small)
                    }
                    Spacer()
                }
                if let errorText {
                    Text(errorText)
                        .font(.callout)
                        .foregroundStyle(.red)
                }
                if output.isEmpty, !isRunning {
                    Text("Reads the text of every document in the library — Visual-Meta appendices and link metadata are treated as metadata, not content — and reports what the community is working out. The prompt is yours: Settings → AI.")
                        .font(.callout)
                        .foregroundStyle(.secondary)
                } else {
                    report
                }
            }
            .frame(maxWidth: 620, alignment: .leading)
            .frame(maxWidth: .infinity)
            .padding(20)
        }
    }

    // MARK: - The furled report

    private struct InsightSection: Identifiable {
        let id: Int
        let heading: LiquidDoc.Paragraph?
        let paragraphs: [LiquidDoc.Paragraph]
    }

    /// Groups the model's output at its headings. Text before the first
    /// heading is a preamble, always shown.
    private var sections: [InsightSection] {
        let body = LiquidDoc.parseBody(from: output)
        var result: [InsightSection] = []
        var heading: LiquidDoc.Paragraph?
        var current: [LiquidDoc.Paragraph] = []
        func flush() {
            if heading != nil || !current.isEmpty {
                result.append(InsightSection(id: result.count, heading: heading, paragraphs: current))
            }
            current = []
        }
        for paragraph in body {
            if paragraph.effectiveHeading != nil {
                flush()
                heading = paragraph
            } else {
                current.append(paragraph)
            }
        }
        flush()
        return result
    }

    @ViewBuilder private var report: some View {
        // Rendered through the same paragraph pipeline as any document, so
        // the addresses the model cites are live links.
        ForEach(sections) { section in
            if let heading = section.heading {
                Button {
                    withAnimation(.snappy) {
                        if unfurledSections.contains(section.id) {
                            unfurledSections.remove(section.id)
                        } else {
                            unfurledSections.insert(section.id)
                        }
                    }
                } label: {
                    HStack(spacing: 7) {
                        Image(systemName: unfurledSections.contains(section.id)
                              ? "chevron.down" : "chevron.right")
                            .font(.caption)
                            .foregroundStyle(.secondary)
                        Text(heading.displayText)
                            .font(.system(size: 19, weight: .bold, design: .serif))
                    }
                    .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
                .padding(.top, 6)
                if unfurledSections.contains(section.id) {
                    ForEach(section.paragraphs) { paragraph in
                        ParagraphView(paragraph: paragraph, isHighlighted: false)
                    }
                    .padding(.leading, 18)
                }
            } else {
                ForEach(section.paragraphs) { paragraph in
                    ParagraphView(paragraph: paragraph, isHighlighted: false)
                }
            }
        }
    }

    // MARK: - Running the model

    private func describe(_ reason: SystemLanguageModel.Availability.UnavailableReason) -> String {
        switch reason {
        case .deviceNotEligible:
            return "This Mac does not support Apple Intelligence."
        case .modelNotReady:
            return "The model is still preparing; try again shortly."
        default:
            return "Enable Apple Intelligence in System Settings to use it."
        }
    }

    private func run() {
        isRunning = true
        errorText = nil
        output = ""
        unfurledSections = []
        let corpus = AIInsights.corpus(from: Array(model.index.byID.values))
        guard corpus.includedCount > 0 else {
            errorText = "No text documents in the library yet."
            isRunning = false
            return
        }
        var fullPrompt = prompt
        fullPrompt += "\n\nTHE DOCUMENTS (\(corpus.includedCount) included"
        if corpus.omittedCount > 0 {
            fullPrompt += ", \(corpus.omittedCount) older omitted for space"
        }
        fullPrompt += "):\n\n" + corpus.text
        let request = fullPrompt
        Task {
            do {
                let session = LanguageModelSession()
                let response = try await session.respond(to: request)
                output = response.content
            } catch {
                errorText = "The model could not respond: \(error.localizedDescription)"
            }
            isRunning = false
        }
    }
}

extension AIInsightsView {
    /// The AI Insights view as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "ai-insights",
        name: "AI Insights",
        systemImage: "sparkles",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(AIInsightsView()) },
        hidesDocumentList: true
    )
}

ask-library.source:
import SwiftUI
import FoundationModels

// Ask the Library: a question answered on this Mac, grounded in the
// community's documents. The on-device model is given two tools over
// the library index — search, and read a document — and instructions
// that answers must cite addresses. Addresses in the answer are then
// verified against the index: one that resolves becomes a live link,
// one that does not is stripped of its brackets — the model may
// misremember; the web of documents may not. Nothing leaves the Mac.

// MARK: - The library tools

/// Searches the library's words and titles; the model's way in.
private struct SearchLibraryTool: Tool {
    let name = "searchLibrary"
    let description = "Searches every document in the community library by words in the title, author, or body. Returns each match's address in [brackets], its title, author, and a snippet."

    let state: AppState

    @Generable
    struct Arguments {
        @Guide(description: "Words to search for")
        var query: String
        @Guide(description: "How many matches to return", .range(1...8))
        var limit: Int
    }

    func call(arguments: Arguments) async throws -> [String] {
        let query = arguments.query
        let limit = arguments.limit
        return await MainActor.run {
            let terms = query.lowercased()
                .split(whereSeparator: \.isWhitespace).map(String.init)
            guard !terms.isEmpty else { return ["Nothing to search for."] }
            var results: [String] = []
            for entry in state.index.byID.values {
                let doc = entry.doc
                let haystack = (doc.title + " " + doc.author + " "
                    + doc.bodyEditingText).lowercased()
                guard terms.allSatisfy({ haystack.contains($0) }) else { continue }
                let snippetSource = doc.bodyEditingText
                let snippet = String(snippetSource.prefix(160))
                    .replacingOccurrences(of: "\n", with: " ")
                results.append("[\(doc.id)] “\(doc.title)” by \(doc.displayAuthor), \(doc.listedDateText): \(snippet)")
                if results.count >= limit { break }
            }
            return results.isEmpty
                ? ["No documents match “\(query)”."]
                : results
        }
    }
}

/// Reads one document whole, by its address.
private struct ReadDocumentTool: Tool {
    let name = "readDocument"
    let description = "Reads a document by the address searchLibrary returned (without brackets). Returns its full words."

    let state: AppState

    @Generable
    struct Arguments {
        @Guide(description: "The document's address, e.g. f.hegla.093252x")
        var address: String
    }

    func call(arguments: Arguments) async throws -> String {
        let address = arguments.address
        return await MainActor.run {
            let id = LiquidAddress.canonical(address)
            guard let doc = state.index.byID[id]?.doc
                ?? state.index.allByID[id]?.doc else {
                return "No document answers to \(address)."
            }
            let appendix = doc.visualMetaParagraphIDs.union(doc.analysisParagraphIDs)
            let words = (doc.body ?? [])
                .filter { !appendix.contains($0.id) }
                .map(\.displayText)
                .joined(separator: "\n")
            return """
            “\(doc.title)” by \(doc.displayAuthor), \(doc.listedDateText) [\(doc.id)]:
            \(String(words.prefix(2500)))
            """
        }
    }
}

// MARK: - The view

/// Ask the Library: grounded question-answering over the community's
/// documents, on this Mac's own model, every citation verified.
struct AskLibraryView: View {
    @Environment(AppState.self) private var state

    @State private var question = ""
    @State private var answer: [LiquidDoc.Paragraph] = []
    @State private var isAsking = false
    @State private var errorText: String?

    private var modelAvailable: Bool {
        SystemLanguageModel.default.availability == .available
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            Text("Ask the Library")
                .font(.system(size: 26, weight: .bold, design: .serif))
            Text("A question answered from the community's documents, on this Mac — the model must search the library, and every address it cites is verified against the index before it stands. Nothing leaves the machine.")
                .font(.callout)
                .foregroundStyle(.secondary)
            HStack {
                TextField("What does the community say about…", text: $question)
                    .textFieldStyle(.roundedBorder)
                    .onSubmit { ask() }
                Button(isAsking ? "Asking…" : "Ask") { ask() }
                    .disabled(isAsking || !modelAvailable
                              || question.trimmingCharacters(in: .whitespaces).isEmpty)
            }
            if !modelAvailable {
                Text("The on-device model is not available on this Mac — Apple Intelligence is required.")
                    .font(.caption)
                    .foregroundStyle(.orange)
            }
            if let errorText {
                Text(errorText)
                    .font(.caption)
                    .foregroundStyle(.orange)
            }
            ScrollView {
                VStack(alignment: .leading, spacing: 10) {
                    ForEach(answer) { paragraph in
                        Text(paragraph.renderedText)
                            .font(.system(size: 15, design: .serif))
                            .lineSpacing(5)
                            .textSelection(.enabled)
                    }
                    if !answer.isEmpty {
                        Divider()
                        Text("Answered by the on-device model, grounded by library search; addresses verified against the index.")
                            .font(.caption)
                            .foregroundStyle(.tertiary)
                    }
                }
                .frame(maxWidth: 640, alignment: .leading)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        }
        .padding(24)
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        .background(AppGreys.page)
        .environment(\.colorScheme, .light)
    }

    private func ask() {
        let asked = question.trimmingCharacters(in: .whitespaces)
        guard !asked.isEmpty, !isAsking, modelAvailable else { return }
        isAsking = true
        errorText = nil
        answer = []
        let session = LanguageModelSession(
            tools: [SearchLibraryTool(state: state), ReadDocumentTool(state: state)],
            instructions: """
            You are the librarian of a small community's shared library of \
            documents. Answer questions only from what the library holds: \
            always search first, read documents when the snippets are not \
            enough, and keep answers short and grounded. Every claim must \
            cite the document it came from by putting its address in square \
            brackets, like [f.hegla.093252x], at the end of the sentence it \
            supports. If the library holds nothing on the question, say so \
            plainly.
            """)
        Task {
            do {
                let response = try await session.respond(to: asked)
                answer = Self.verifiedParagraphs(from: response.content,
                                                 index: state.index)
            } catch {
                errorText = "The model could not answer: \(error.localizedDescription)"
            }
            isAsking = false
        }
    }

    /// The answer as paragraphs, its citations verified: an address the
    /// index knows becomes a live link (via renderedText); one it does
    /// not loses its brackets and stands as plain words.
    @MainActor
    private static func verifiedParagraphs(from text: String,
                                           index: LibraryIndex) -> [LiquidDoc.Paragraph] {
        var verified = text
        // Walk matches back to front so ranges stay valid while editing.
        let nsText = verified as NSString
        for match in LiquidAddress.matches(in: verified).reversed() {
            guard index.allByID[match.id] == nil else { continue }
            let cited = nsText.substring(with: match.range)
                .trimmingCharacters(in: CharacterSet(charactersIn: "[]"))
            verified = (verified as NSString).replacingCharacters(
                in: match.range, with: cited)
        }
        return LiquidDoc.parseBody(from: verified)
    }
}

extension AskLibraryView {
    /// Ask the Library as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "ask-library",
        name: "Ask",
        systemImage: "questionmark.bubble",
        makeContent: { AnyView(AskLibraryView()) },
        makeDetail: { _ in AnyView(AskLibraryView()) },
        hidesDocumentList: true,
        showInAppetite: .text
    )
}

attentions.source:
import SwiftUI

/// Attentions: who addresses whom. Everyone who has written "for the
/// attention of" someone — or been named that way — sits still around a
/// ring, portrait when the contact record has one, initials otherwise.
/// Click a person and their attentions appear: lines in the label color
/// to the people they have addressed, gray lines from the people who have
/// addressed them. ⌘A selects everyone and shows the whole mesh. The more
/// documents behind a line, the thicker it runs; rest the pointer on a
/// line and a card lists the documents behind it — the card stays put so
/// any of them can be clicked open. Click empty space to dismiss it.
struct AttentionsView: View {
    @Environment(AppModel.self) private var model
    @State private var selectedPerson: String?
    @State private var allSelected = false
    /// The line whose documents are on display; set by hover, kept until
    /// another line takes over, the background is clicked, or the
    /// selection changes.
    @State private var activeEdgeID: String?
    /// Where the card sits: frozen at the point the line was first
    /// hovered, so it doesn't chase the pointer.
    @State private var panelPoint: CGPoint = .zero

    private struct PersonNode: Identifiable {
        let name: String
        let sent: Int
        let received: Int
        var id: String { name }
    }

    /// One directed line: documents by `from` addressed for the attention
    /// of `to` — the documents themselves ride along for the hover card.
    private struct Edge: Identifiable {
        let from: String
        let to: String
        let docs: [LiquidDoc]
        var id: String { "\(from)→\(to)" }
    }

    /// A drawn line, ready for stroking and for pointer hit-testing.
    private struct Segment {
        let edge: Edge
        let a: CGPoint
        let b: CGPoint
    }

    var body: some View {
        let people = people
        if people.count < 2 {
            ContentUnavailableView(
                "No Attentions",
                systemImage: "person.2",
                description: Text("Attentions appears once the library holds a letter addressed for someone's attention."))
        } else {
            circle(people: people)
        }
    }

    private func circle(people: [PersonNode]) -> some View {
        GeometryReader { geometry in
            let positions = positions(for: people, in: geometry.size)
            let segments = segments(in: positions)
            ZStack {
                Canvas { context, _ in
                    for segment in segments {
                        stroke(segment, in: &context)
                    }
                }
                .allowsHitTesting(false)

                ForEach(people) { person in
                    personButton(person)
                        .position(positions[person.name] ?? .zero)
                }

                if selectedPerson == nil && !allSelected {
                    Text("Click a person to see who they address and who addresses them — ⌘A for everyone.")
                        .font(.callout)
                        .foregroundStyle(.secondary)
                        .allowsHitTesting(false)
                }

                if let segment = segments.first(where: { $0.edge.id == activeEdgeID }) {
                    edgePanel(segment.edge, in: geometry.size)
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .contentShape(Rectangle())
            .onTapGesture { activeEdgeID = nil }
            .onContinuousHover { phase in
                guard case .active(let point) = phase else { return }
                if let hit = nearestSegment(to: point, in: segments),
                   hit.edge.id != activeEdgeID {
                    activeEdgeID = hit.edge.id
                    panelPoint = point
                }
                // Off every line the card stays: it must survive the
                // pointer's journey onto it.
            }
            // ⌘A, without needing focus: an unseen button carries the
            // standard Select All shortcut for this view.
            .background(
                Button("") { selectEveryone() }
                    .keyboardShortcut("a", modifiers: .command)
                    .opacity(0)
                    .frame(width: 0, height: 0)
            )
        }
        #if os(macOS)
        .background(Color(nsColor: .windowBackgroundColor))
        #else
        .background(.background)
        #endif
    }

    private func selectEveryone() {
        allSelected = true
        selectedPerson = nil
        activeEdgeID = nil
    }

    private func personButton(_ person: PersonNode) -> some View {
        let isSelected = person.name == selectedPerson || allSelected
        return Button {
            if selectedPerson == person.name {
                selectedPerson = nil
            } else {
                selectedPerson = person.name
            }
            allSelected = false
            activeEdgeID = nil
        } label: {
            VStack(spacing: 3) {
                PersonAvatarView(name: person.name, size: 44)
                    .overlay(
                        RoundedRectangle(cornerRadius: 44 * 0.18, style: .continuous)
                            .strokeBorder(isSelected ? Color.accentColor : .clear, lineWidth: 2.5)
                    )
                Text(person.name)
                    .font(.caption2)
                    .fontWeight(person.name == selectedPerson ? .bold : .regular)
                    .lineLimit(1)
                    .frame(maxWidth: 90)
            }
        }
        .buttonStyle(.plain)
        .help(helpText(for: person))
    }

    private func helpText(for person: PersonNode) -> String {
        let sent = "\(person.sent) \(person.sent == 1 ? "letter" : "letters") addressed to others"
        let received = "\(person.received) addressed to them"
        return "\(person.name) — \(sent), \(received)"
    }

    /// The card behind a line: who addressed whom, and every document that
    /// made it — each one clickable. It stays until another line is
    /// hovered, the background is clicked, or the selection changes.
    private func edgePanel(_ edge: Edge, in size: CGSize) -> some View {
        let limit = 10
        return VStack(alignment: .leading, spacing: 4) {
            HStack {
                Text("\(edge.from) → \(edge.to)")
                    .font(.caption.weight(.semibold))
                Spacer()
                Button {
                    activeEdgeID = nil
                } label: {
                    Image(systemName: "xmark.circle.fill")
                        .foregroundStyle(.secondary)
                }
                .buttonStyle(.plain)
                .help("Dismiss")
            }
            Text("For the attention of \(edge.to)")
                .font(.caption2)
                .foregroundStyle(.secondary)
            ForEach(edge.docs.prefix(limit), id: \.id) { doc in
                Button {
                    model.openInLibrary(doc)
                } label: {
                    Text(doc.title)
                        .font(.caption)
                        .lineLimit(1)
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
                .help("Open “\(doc.title)”")
            }
            if edge.docs.count > limit {
                Text("and \(edge.docs.count - limit) more")
                    .font(.caption2)
                    .foregroundStyle(.secondary)
            }
        }
        .padding(10)
        .frame(width: 280, alignment: .leading)
        .background(.regularMaterial, in: RoundedRectangle(cornerRadius: 8))
        .shadow(radius: 4)
        .position(x: min(max(panelPoint.x, 150), size.width - 150),
                  y: max(panelPoint.y - 60, 70))
    }

    // MARK: Data

    /// Everyone on either end of an attention line, busiest first.
    private var people: [PersonNode] {
        var sent: [String: Int] = [:]
        var received: [String: Int] = [:]
        for edge in allEdges {
            sent[edge.from, default: 0] += edge.docs.count
            received[edge.to, default: 0] += edge.docs.count
        }
        return Set(sent.keys).union(received.keys)
            .map { PersonNode(name: $0, sent: sent[$0] ?? 0, received: received[$0] ?? 0) }
            .sorted { ($0.sent + $0.received, $1.name) > ($1.sent + $1.received, $0.name) }
    }

    /// Every directed attention line in the visible library: the documents
    /// by `from` addressed for the attention of `to`, newest first. A
    /// document counts toward a line once, and addressing oneself doesn't
    /// count. Names keep the author's spelling when the two differ only
    /// by case.
    private var allEdges: [Edge] {
        let entries = model.filteredEntries
        // Attention names are strings; unify them case-insensitively so
        // "eric rangell" and "Eric Rangell" share one seat on the ring,
        // preferring the spelling on a byline.
        var spelling: [String: String] = [:]
        for entry in entries {
            spelling[entry.doc.creditedAuthor.lowercased()] = entry.doc.creditedAuthor
        }
        func canonical(_ name: String) -> String {
            spelling[name.lowercased()] ?? name
        }
        var docsByPair: [String: (from: String, to: String, docs: [LiquidDoc])] = [:]
        for entry in entries {
            let doc = entry.doc
            let from = doc.creditedAuthor
            let recipients = Set(doc.attention.map(canonical))
            for recipient in recipients {
                guard recipient.caseInsensitiveCompare(from) != .orderedSame else { continue }
                let key = "\(from)→\(recipient)"
                docsByPair[key, default: (from, recipient, [])].docs.append(doc)
            }
        }
        return docsByPair.values.map { pair in
            Edge(from: pair.from, to: pair.to,
                 docs: pair.docs.sorted { $0.listedDate > $1.listedDate })
        }
    }

    /// What is on display: everything when everyone is selected, else the
    /// selected person's attentions in both directions.
    private var visibleEdges: [Edge] {
        if allSelected { return allEdges }
        guard let selected = selectedPerson else { return [] }
        return allEdges.filter { $0.from == selected || $0.to == selected }
    }

    // MARK: Geometry

    private func positions(for people: [PersonNode], in size: CGSize) -> [String: CGPoint] {
        let radius = min(size.width, size.height) / 2 - 70
        let center = CGPoint(x: size.width / 2, y: size.height / 2)
        var positions: [String: CGPoint] = [:]
        for (index, person) in people.enumerated() {
            // Start at the top; no rotation — the circle holds still.
            let angle = -Double.pi / 2 + 2 * .pi * Double(index) / Double(people.count)
            positions[person.name] = CGPoint(x: center.x + radius * cos(angle),
                                             y: center.y + radius * sin(angle))
        }
        return positions
    }

    /// The lines to draw right now, pulled back from the portraits and
    /// nudged sideways so the two directions between the same pair stay
    /// distinguishable.
    private func segments(in positions: [String: CGPoint]) -> [Segment] {
        visibleEdges.compactMap { edge in
            guard let from = positions[edge.from], let to = positions[edge.to] else { return nil }
            let d = hypot(to.x - from.x, to.y - from.y)
            guard d > 1 else { return nil }
            let unit = CGPoint(x: (to.x - from.x) / d, y: (to.y - from.y) / d)
            let normal = CGPoint(x: -unit.y, y: unit.x)
            let side: CGFloat = edge.from < edge.to ? 3 : -3
            let margin: CGFloat = 30
            let a = CGPoint(x: from.x + unit.x * margin + normal.x * side,
                            y: from.y + unit.y * margin + normal.y * side)
            let b = CGPoint(x: to.x - unit.x * margin + normal.x * side,
                            y: to.y - unit.y * margin + normal.y * side)
            return Segment(edge: edge, a: a, b: b)
        }
    }

    private func nearestSegment(to point: CGPoint, in segments: [Segment]) -> Segment? {
        var best: (segment: Segment, distance: CGFloat)?
        for segment in segments {
            let d = distance(from: point, toSegment: segment.a, segment.b)
            if d < 7, d < (best?.distance ?? .infinity) {
                best = (segment, d)
            }
        }
        return best?.segment
    }

    private func distance(from p: CGPoint, toSegment a: CGPoint, _ b: CGPoint) -> CGFloat {
        let ab = CGPoint(x: b.x - a.x, y: b.y - a.y)
        let lengthSquared = ab.x * ab.x + ab.y * ab.y
        guard lengthSquared > 0 else { return hypot(p.x - a.x, p.y - a.y) }
        let t = max(0, min(1, ((p.x - a.x) * ab.x + (p.y - a.y) * ab.y) / lengthSquared))
        return hypot(p.x - (a.x + ab.x * t), p.y - (a.y + ab.y * t))
    }

    // MARK: Drawing

    private func stroke(_ segment: Segment, in context: inout GraphicsContext) {
        var path = Path()
        path.move(to: segment.a)
        path.addLine(to: segment.b)
        let isActive = segment.edge.id == activeEdgeID
        // Weight carries the count; the colors stay the system's. With one
        // person selected, who they address runs in the label color and
        // what comes toward them in gray; with everyone selected the mesh
        // is uniform.
        let width = 1 + min(CGFloat(segment.edge.docs.count), 7) + (isActive ? 1.5 : 0)
        let color: Color = if let selected = selectedPerson, segment.edge.from == selected {
            .primary.opacity(isActive ? 1 : 0.8)
        } else if selectedPerson != nil {
            .gray.opacity(isActive ? 0.95 : 0.55)
        } else {
            .primary.opacity(isActive ? 0.9 : 0.45)
        }
        context.stroke(path, with: .color(color), lineWidth: width)
    }
}

extension AttentionsView {
    /// Attentions as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "attentions",
        name: "Attentions",
        systemImage: "person.2.wave.2",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(AttentionsView()) },
        hidesDocumentList: true
    )
}

