import SwiftUI
import FoundationModels

/// Defaults for the Disagreements view. Runs entirely on-device (Apple
/// Intelligence); no text leaves the Mac. The prompt is editable in
/// Settings → AI.
nonisolated enum Disagreements {

    static let defaultPrompt = """
    You are reading a community of thinkers' documents to surface genuine disagreements: places where documents take positions that cannot both be right, or authors pull in different directions on the same matter. Real tension only — a difference of emphasis or subject is not disagreement.

    How to read the material: each document begins with a == line giving its title, author, date, and address. A following Relations: line is metadata — typed links between documents (a disagrees-with link is a strong signal, but the text itself can disagree without one) — treat it as structure, never as prose. Anything resembling Visual-Meta or BibTeX (@{...} markers, key = {value} fields) is metadata about a document, not content; disregard it as text even if fragments appear.

    Name up to six disagreements, sharpest first. Each needs: a topic of one to four words; one sentence stating exactly what is in dispute; and the two positions, each in one sentence with the addresses of the documents taking it, copied exactly from their == lines. A document belongs on only one side of a given disagreement. If the library holds no genuine disagreement, return none — an empty list is an honest answer. Never invent an address.
    """
}

/// One disagreement as the model returns it: the dispute and its two
/// sides. Addresses are verified against the index before display.
@Generable
nonisolated struct GeneratedDisagreement {
    @Guide(description: "The disputed topic: one to four words")
    var topic: String
    @Guide(description: "One sentence stating exactly what is in dispute")
    var dispute: String
    @Guide(description: "The first position, in one sentence")
    var firstPosition: String
    @Guide(description: "Addresses of the documents taking the first position, copied exactly from the == lines, e.g. f.hegla.093000k")
    var firstAddresses: [String]
    @Guide(description: "The second position, in one sentence")
    var secondPosition: String
    @Guide(description: "Addresses of the documents taking the second position, copied exactly from the == lines")
    var secondAddresses: [String]
}

@Generable
nonisolated struct GeneratedDisagreementList {
    @Guide(description: "The genuine disagreements across the documents, sharpest first; empty if there are none")
    var disagreements: [GeneratedDisagreement]
}

/// Where the community genuinely pulls apart: the on-device model reads
/// the library and names the disputes, each with its two sides and the
/// documents holding them. Dialog needs its disagreements visible.
struct DisagreementsView: View {
    @Environment(AppModel.self) private var model
    @AppStorage(AppSettings.aiDisagreementsPromptKey) private var prompt = Disagreements.defaultPrompt
    @State private var disagreements: [ResolvedDisagreement] = []
    @State private var hasRun = false
    @State private var isRunning = false
    @State private var errorText: String?
    @State private var unfurled: Set<String> = []

    /// A disagreement both of whose sides survived grounding.
    struct ResolvedDisagreement: Identifiable {
        struct Side {
            let position: String
            let entries: [IndexEntry]
        }
        let topic: String
        let dispute: String
        let first: Side
        let second: Side
        var id: String { topic }
    }

    var body: some View {
        Group {
            switch SystemLanguageModel.default.availability {
            case .available:
                content
            case .unavailable(let reason):
                ContentUnavailableView {
                    Label("Apple Intelligence Unavailable", systemImage: "bubble.left.and.bubble.right")
                } description: {
                    Text("Disagreements uses the on-device model, so no text leaves this Mac. \(describe(reason))")
                }
            }
        }
    }

    private var content: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 12) {
                HStack(spacing: 10) {
                    Button {
                        run()
                    } label: {
                        Label(isRunning ? "Reading…" : (hasRun ? "Find Disagreements Again" : "Find Disagreements"),
                              systemImage: "bubble.left.and.bubble.right")
                    }
                    .disabled(isRunning)
                    if isRunning {
                        ProgressView()
                            .controlSize(.small)
                    }
                    Spacer()
                }
                if let errorText {
                    Text(errorText)
                        .font(.callout)
                        .foregroundStyle(.red)
                }
                if !hasRun, !isRunning {
                    Text("The on-device model reads every document in the library and names where documents genuinely pull against each other — each dispute with its two sides and their documents. The prompt is yours: Settings → AI.")
                        .font(.callout)
                        .foregroundStyle(.secondary)
                } else if hasRun, disagreements.isEmpty, !isRunning {
                    Text("No genuine disagreement found between library documents — an empty list is an honest answer. Try again as the library grows.")
                        .font(.callout)
                        .foregroundStyle(.secondary)
                }
                ForEach(disagreements) { disagreement in
                    disagreementRow(disagreement)
                }
            }
            .frame(maxWidth: 620, alignment: .leading)
            .frame(maxWidth: .infinity)
            .padding(20)
        }
    }

    @ViewBuilder
    private func disagreementRow(_ disagreement: ResolvedDisagreement) -> some View {
        Button {
            withAnimation(.snappy) {
                if unfurled.contains(disagreement.id) {
                    unfurled.remove(disagreement.id)
                } else {
                    unfurled.insert(disagreement.id)
                }
            }
        } label: {
            HStack(alignment: .firstTextBaseline, spacing: 7) {
                Image(systemName: unfurled.contains(disagreement.id) ? "chevron.down" : "chevron.right")
                    .font(.caption)
                    .foregroundStyle(.secondary)
                Text(disagreement.topic)
                    .font(.system(size: 19, weight: .bold, design: .serif))
                Text("\(disagreement.first.entries.count) v \(disagreement.second.entries.count)")
                    .font(.caption.monospacedDigit())
                    .foregroundStyle(.secondary)
                    .padding(.horizontal, 6)
                    .padding(.vertical, 1)
                    .background(.quaternary, in: Capsule())
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .padding(.top, 6)
        Text(disagreement.dispute)
            .font(.callout)
            .foregroundStyle(.secondary)
            .padding(.leading, 18)
        if unfurled.contains(disagreement.id) {
            sideView(disagreement.first)
            sideView(disagreement.second)
        }
    }

    @ViewBuilder
    private func sideView(_ side: ResolvedDisagreement.Side) -> some View {
        Text(side.position)
            .font(.callout)
            .italic()
            .padding(.leading, 36)
            .padding(.top, 4)
        ForEach(side.entries) { entry in
            Button {
                model.openInLibrary(entry.doc)
            } label: {
                VStack(alignment: .leading, spacing: 1) {
                    Text(entry.doc.title)
                    Text("\(entry.doc.displayAuthor) · \(entry.doc.listedDateText)")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }
                .contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            .padding(.leading, 54)
            .padding(.vertical, 2)
        }
    }

    // MARK: - Running the model

    private func describe(_ reason: SystemLanguageModel.Availability.UnavailableReason) -> String {
        switch reason {
        case .deviceNotEligible:
            return "This Mac does not support Apple Intelligence."
        case .modelNotReady:
            return "The model is still preparing; try again shortly."
        default:
            return "Enable Apple Intelligence in System Settings to use it."
        }
    }

    private func run() {
        isRunning = true
        errorText = nil
        let corpus = AIInsights.corpus(from: Array(model.index.byID.values))
        guard corpus.includedCount > 0 else {
            errorText = "No text documents in the library yet."
            isRunning = false
            return
        }
        var fullPrompt = prompt
        fullPrompt += "\n\nTHE DOCUMENTS (\(corpus.includedCount) included"
        if corpus.omittedCount > 0 {
            fullPrompt += ", \(corpus.omittedCount) older omitted for space"
        }
        fullPrompt += "):\n\n" + corpus.text
        let request = fullPrompt
        Task {
            do {
                let session = LanguageModelSession()
                let response = try await session.respond(to: request, generating: GeneratedDisagreementList.self)
                disagreements = resolve(response.content.disagreements)
                unfurled = []
                hasRun = true
            } catch {
                errorText = "The model could not respond: \(error.localizedDescription)"
            }
            isRunning = false
        }
    }

    /// Grounding: unknown addresses are dropped, a document may hold only
    /// one side, and a disagreement must keep at least one real document
    /// on each side to survive.
    private func resolve(_ generated: [GeneratedDisagreement]) -> [ResolvedDisagreement] {
        let byID = model.index.byID
        return generated.compactMap { disagreement in
            var seen: Set<String> = []
            func entries(for addresses: [String]) -> [IndexEntry] {
                addresses
                    .map { LiquidAddress.canonical($0) }
                    .filter { seen.insert($0).inserted }
                    .compactMap { byID[$0] }
            }
            let first = entries(for: disagreement.firstAddresses)
            let second = entries(for: disagreement.secondAddresses)
            guard !first.isEmpty, !second.isEmpty else { return nil }
            return ResolvedDisagreement(
                topic: disagreement.topic,
                dispute: disagreement.dispute,
                first: .init(position: disagreement.firstPosition, entries: first),
                second: .init(position: disagreement.secondPosition, entries: second)
            )
        }
    }
}

extension DisagreementsView {
    /// The Disagreements view as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "disagreements",
        name: "Disagreements",
        systemImage: "bubble.left.and.bubble.right",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(DisagreementsView()) },
        hidesDocumentList: true
    )
}

geometries.source:
import SwiftUI

/// The Geometry of Thought, demonstrated: the same library rendered
/// through five representational geometries at once — a line, a
/// hierarchy, sets, a graph, and a canvas — after David Millard's essay
/// of that name (The Stranger's Notebook, 2026): knowledge interfaces
/// are not neutral, each geometry affords different thoughts. Click a
/// document anywhere and every pane lights it up along with the
/// neighbours *that geometry* gives it: the line offers before and
/// after, the hierarchy offers siblings, sets offer fellow members, the
/// graph offers what it actually touches, the canvas offers whatever
/// was placed nearby. Same document, five different neighbourhoods —
/// the geometry decides what can be seen, and so what can be thought.
struct GeometriesView: View {
    @Environment(AppModel.self) private var model
    @State private var selectedID: String?
    /// Where each document sits on the canvas pane — seeded from the
    /// document's address so the field is stable, then the reader's to
    /// rearrange: proximity without commitment.
    @State private var canvasPositions: [String: CGPoint] = [:]
    @State private var dragStart: [String: CGPoint] = [:]

    /// What all five geometries render: every text document, bots and
    /// trails excluded, oldest first — the one library, five ways.
    private var entries: [IndexEntry] {
        model.filteredEntries
            .filter { $0.doc.body != nil }
            .filter { $0.doc.documentType != BotDocument.documentType }
            .filter { $0.doc.documentType != TrailDocument.documentType }
            .sorted { $0.doc.listedDate < $1.doc.listedDate }
    }

    private var selectedEntry: IndexEntry? {
        entries.first { $0.id == selectedID }
    }

    var body: some View {
        VStack(spacing: 0) {
            header
            Divider()
            if entries.isEmpty {
                ContentUnavailableView(
                    "No Documents",
                    systemImage: "square.on.circle",
                    description: Text("Add documents to the community folder and the five geometries will render them."))
            } else {
                ScrollView {
                    LazyVGrid(columns: [GridItem(.flexible(), spacing: 12),
                                        GridItem(.flexible(), spacing: 12)],
                              spacing: 12) {
                        pane("The Line",
                             caption: "Sequence — a document has a before and an after, nothing else.",
                             related: lineNeighbours()) { linePane }
                        pane("The Hierarchy",
                             caption: "Belonging — exactly one parent each; the neighbours are the siblings.",
                             related: hierarchyNeighbours()) { hierarchyPane }
                        pane("The Sets",
                             caption: "Overlap — a document may belong to several sets at once.",
                             related: setNeighbours()) { setsPane }
                        pane("The Graph",
                             caption: "Relation — the neighbours are what a document actually touches.",
                             related: graphNeighbours()) { graphPane }
                        pane("The Canvas",
                             caption: "Proximity without commitment — near because someone put it there.",
                             related: canvasNeighbours()) { canvasPane }
                        explainerPane
                    }
                    .padding(12)
                }
            }
        }
        #if os(macOS)
        .background(Color(nsColor: .windowBackgroundColor))
        #else
        .background(.background)
        #endif
    }

    private var header: some View {
        HStack(spacing: 10) {
            VStack(alignment: .leading, spacing: 2) {
                Text("The same library, five geometries — each affords different thoughts.")
                    .font(.callout)
                Text("After David Millard's “The Geometry of Thought”. Click a document anywhere: every pane shows the neighbours its geometry gives it. Double-click to read.")
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }
            Spacer()
            if let entry = selectedEntry {
                VStack(alignment: .trailing, spacing: 1) {
                    Text(entry.doc.title)
                        .font(.callout.weight(.semibold))
                        .lineLimit(1)
                    Text(entry.doc.displayAuthor)
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }
                .frame(maxWidth: 260, alignment: .trailing)
            }
        }
        .padding(10)
    }

    // MARK: - The panes

    /// One geometry's pane: header, caption, and its rendering. The
    /// related set is computed by the pane's own geometry — the point of
    /// the whole view.
    private func pane<Content: View>(_ title: String, caption: String,
                                     related: Set<String>,
                                     @ViewBuilder content: () -> Content) -> some View {
        VStack(alignment: .leading, spacing: 6) {
            Text(title)
                .font(.system(size: 15, weight: .bold, design: .serif))
            Text(caption)
                .font(.caption)
                .foregroundStyle(.secondary)
                .lineLimit(2, reservesSpace: true)
            content()
                .frame(maxWidth: .infinity, minHeight: 200, maxHeight: 200)
                .background(.quaternary.opacity(0.3), in: RoundedRectangle(cornerRadius: 8))
                .environment(\.geometryRelatedIDs, related)
        }
        .padding(10)
        .background(.thickMaterial, in: RoundedRectangle(cornerRadius: 10))
    }

    /// The essay's argument, standing where a sixth pane would.
    private var explainerPane: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text("Why five?")
                .font(.system(size: 15, weight: .bold, design: .serif))
            Text("A hierarchy can say “this belongs here” but not “these two touch”. A line can say “this came after” and nothing more. The graph knows relations but not nearness; the canvas knows nearness but commits to nothing. None of them is the library — each is one geometry of it, and whichever one a tool offers becomes the shape of its readers' thinking. A chat window, Millard warns, is the poorest geometry of all: a line that forgets.")
                .font(.callout)
            Spacer(minLength: 0)
            Text("Millard, D. “The Geometry of Thought”, The Stranger's Notebook, May 2026 — building on Engelbart's H-LAM/T framework.")
                .font(.caption)
                .foregroundStyle(.tertiary)
        }
        .padding(10)
        .frame(maxWidth: .infinity, minHeight: 262, alignment: .topLeading)
        .background(.thickMaterial, in: RoundedRectangle(cornerRadius: 10))
    }

    // MARK: The line

    /// Creation order and nothing else: the chat geometry, made honest.
    private var linePane: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(alignment: .center, spacing: 0) {
                ForEach(Array(entries.enumerated()), id: \.element.id) { index, entry in
                    HStack(spacing: 0) {
                        if index > 0 {
                            Rectangle()
                                .fill(.secondary.opacity(0.3))
                                .frame(width: 22, height: 1)
                        }
                        VStack(spacing: 3) {
                            dot(for: entry)
                            Text(entry.doc.title)
                                .font(.system(size: 8))
                                .foregroundStyle(.secondary)
                                .lineLimit(2)
                                .multilineTextAlignment(.center)
                                .frame(width: 56)
                        }
                    }
                }
            }
            .padding(.horizontal, 12)
            .frame(minHeight: 200)
        }
    }

    private func lineNeighbours() -> Set<String> {
        guard let index = entries.firstIndex(where: { $0.id == selectedID }) else { return [] }
        var related: Set<String> = []
        if index > 0 { related.insert(entries[index - 1].id) }
        if index < entries.count - 1 { related.insert(entries[index + 1].id) }
        return related
    }

    // MARK: The hierarchy

    /// One parent each — here, the author. The folder geometry.
    private var hierarchyPane: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 3) {
                ForEach(authorGroups, id: \.author) { group in
                    Text(group.author)
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(.secondary)
                    ForEach(group.entries) { entry in
                        HStack(spacing: 5) {
                            dot(for: entry)
                            Text(entry.doc.title)
                                .font(.system(size: 10))
                                .lineLimit(1)
                        }
                        .padding(.leading, 14)
                    }
                }
            }
            .padding(10)
            .frame(maxWidth: .infinity, alignment: .leading)
        }
    }

    private var authorGroups: [(author: String, entries: [IndexEntry])] {
        Dictionary(grouping: entries) { $0.doc.displayAuthor }
            .map { (author: $0.key, entries: $0.value) }
            .sorted { $0.author < $1.author }
    }

    private func hierarchyNeighbours() -> Set<String> {
        guard let entry = selectedEntry else { return [] }
        return Set(entries
            .filter { $0.doc.displayAuthor == entry.doc.displayAuthor && $0.id != entry.id }
            .map(\.id))
    }

    // MARK: The sets

    /// Overlapping membership: a document sits in the set of its kind,
    /// and also — when addressed to you — in the attention set. The tag
    /// geometry: one dot may appear in several places.
    private var documentSets: [(name: String, entries: [IndexEntry])] {
        var sets = Dictionary(grouping: entries) { $0.doc.documentType ?? "letter" }
            .map { (name: $0.key, entries: $0.value) }
            .sorted { $0.name < $1.name }
        let attentionIDs = Set(model.attentionEntries.map(\.id))
        let attention = entries.filter { attentionIDs.contains($0.id) }
        if !attention.isEmpty {
            sets.append((name: "for your attention", entries: attention))
        }
        return sets
    }

    private var setsPane: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 8) {
                ForEach(documentSets, id: \.name) { set in
                    VStack(alignment: .leading, spacing: 4) {
                        Text(set.name)
                            .font(.caption.weight(.semibold))
                            .foregroundStyle(.secondary)
                        FlowDots(entries: set.entries) { entry in
                            dot(for: entry)
                        }
                    }
                    .padding(6)
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .background(.quaternary.opacity(0.4), in: RoundedRectangle(cornerRadius: 6))
                }
            }
            .padding(8)
        }
    }

    private func setNeighbours() -> Set<String> {
        guard let selectedID else { return [] }
        var related: Set<String> = []
        for set in documentSets where set.entries.contains(where: { $0.id == selectedID }) {
            related.formUnion(set.entries.map(\.id))
        }
        related.remove(selectedID)
        return related
    }

    // MARK: The graph

    /// Nodes on a circle, links as chords: relation made explicit — the
    /// wiki geometry, and this library's native one.
    private var graphPane: some View {
        GeometryReader { geometry in
            let positions = circlePositions(in: geometry.size)
            ZStack {
                Canvas { context, _ in
                    for entry in entries {
                        guard let from = positions[entry.id] else { continue }
                        for link in entry.doc.links {
                            let target = model.index.latestRevision(of: LiquidAddress.canonical(link.to))
                            guard target != entry.id, let to = positions[target] else { continue }
                            let touched = entry.id == selectedID || target == selectedID
                            var path = Path()
                            path.move(to: from)
                            path.addLine(to: to)
                            context.stroke(path,
                                           with: .color(touched ? .accentColor : .secondary.opacity(0.2)),
                                           lineWidth: touched ? 1.5 : 1)
                        }
                    }
                }
                ForEach(entries) { entry in
                    dot(for: entry)
                        .position(positions[entry.id] ?? .zero)
                }
            }
        }
        .padding(6)
    }

    private func circlePositions(in size: CGSize) -> [String: CGPoint] {
        let center = CGPoint(x: size.width / 2, y: size.height / 2)
        let radius = min(size.width, size.height) / 2 - 16
        var positions: [String: CGPoint] = [:]
        for (index, entry) in entries.enumerated() {
            let angle = Double(index) / Double(max(entries.count, 1)) * 2 * .pi - .pi / 2
            positions[entry.id] = CGPoint(x: center.x + cos(angle) * radius,
                                          y: center.y + sin(angle) * radius)
        }
        return positions
    }

    private func graphNeighbours() -> Set<String> {
        guard let selectedID else { return [] }
        var related: Set<String> = []
        let included = Set(entries.map(\.id))
        for entry in entries {
            for link in entry.doc.links {
                let target = model.index.latestRevision(of: LiquidAddress.canonical(link.to))
                guard included.contains(target) else { continue }
                if entry.id == selectedID, target != selectedID { related.insert(target) }
                if target == selectedID, entry.id != selectedID { related.insert(entry.id) }
            }
        }
        return related
    }

    // MARK: The canvas

    /// Spatial hypertext's geometry: things are near because someone put
    /// them there. Seeded from each address, then the reader's to drag.
    private var canvasPane: some View {
        GeometryReader { geometry in
            ZStack {
                ForEach(entries) { entry in
                    dot(for: entry)
                        .position(canvasPosition(entry.id, in: geometry.size))
                        .gesture(canvasDrag(for: entry.id, in: geometry.size))
                }
            }
        }
        .padding(6)
    }

    private func canvasPosition(_ id: String, in size: CGSize) -> CGPoint {
        if let placed = canvasPositions[id] { return placed }
        // A stable scatter: the address hashes to the same spot every
        // launch, so the field means something until it is rearranged.
        let hash = stableHash(id)
        let x = 20 + Double(hash % 1000) / 1000 * max(size.width - 40, 1)
        let y = 20 + Double((hash / 1000) % 1000) / 1000 * max(size.height - 40, 1)
        return CGPoint(x: x, y: y)
    }

    private func stableHash(_ text: String) -> UInt64 {
        var hash: UInt64 = 14_695_981_039_346_656_037
        for byte in text.utf8 {
            hash = (hash ^ UInt64(byte)) &* 1_099_511_628_211
        }
        return hash
    }

    private func canvasDrag(for id: String, in size: CGSize) -> some Gesture {
        DragGesture(minimumDistance: 2)
            .onChanged { value in
                let start = dragStart[id] ?? canvasPosition(id, in: size)
                if dragStart[id] == nil { dragStart[id] = start }
                canvasPositions[id] = CGPoint(x: start.x + value.translation.width,
                                              y: start.y + value.translation.height)
            }
            .onEnded { _ in dragStart[id] = nil }
    }

    private func canvasNeighbours() -> Set<String> {
        guard let selectedID else { return [] }
        // Whatever sits nearest in the field right now — the size used
        // for seeding only matters for unplaced dots, and only relative
        // distance is asked of it.
        let size = CGSize(width: 400, height: 200)
        let here = canvasPosition(selectedID, in: size)
        let nearest = entries
            .filter { $0.id != selectedID }
            .map { (id: $0.id, distance: hypot(canvasPosition($0.id, in: size).x - here.x,
                                               canvasPosition($0.id, in: size).y - here.y)) }
            .sorted { $0.distance < $1.distance }
            .prefix(2)
        return Set(nearest.map(\.id))
    }

    // MARK: The shared dot

    /// One document, wherever it appears: the same dot in every
    /// geometry, so the eye can follow it across the panes. Accent when
    /// selected, ringed when it is a neighbour in *this* pane's geometry.
    private func dot(for entry: IndexEntry) -> some View {
        GeometryDot(entry: entry,
                    isSelected: entry.id == selectedID,
                    onSelect: { selectedID = entry.id },
                    onOpen: { model.openInLibrary(entry.doc) })
    }
}

/// The related set for the pane a dot sits in, carried down the
/// environment so the one dot view serves all five geometries.
private struct GeometryRelatedIDsKey: EnvironmentKey {
    static let defaultValue: Set<String> = []
}

private extension EnvironmentValues {
    var geometryRelatedIDs: Set<String> {
        get { self[GeometryRelatedIDsKey.self] }
        set { self[GeometryRelatedIDsKey.self] = newValue }
    }
}

private struct GeometryDot: View {
    @Environment(\.geometryRelatedIDs) private var relatedIDs
    let entry: IndexEntry
    let isSelected: Bool
    let onSelect: () -> Void
    let onOpen: () -> Void

    var body: some View {
        let isRelated = relatedIDs.contains(entry.id)
        Circle()
            .fill(isSelected ? Color.accentColor
                  : isRelated ? Color.orange
                  : Color.secondary.opacity(0.55))
            .frame(width: isSelected ? 13 : 10, height: isSelected ? 13 : 10)
            .overlay(
                Circle()
                    .strokeBorder(isRelated ? Color.orange : .clear, lineWidth: 2)
                    .frame(width: 17, height: 17)
            )
            .frame(width: 18, height: 18)
            .contentShape(Circle())
            .onTapGesture(count: 2, perform: onOpen)
            .onTapGesture(perform: onSelect)
            .help("\(entry.doc.title) — \(entry.doc.displayAuthor)")
            .animation(.snappy, value: isSelected)
            .animation(.snappy, value: isRelated)
    }
}

/// Dots flowing left to right, wrapping as they run out of room — sets
/// need their members visible together, however many there are.
private struct FlowDots<Dot: View>: View {
    let entries: [IndexEntry]
    @ViewBuilder let dot: (IndexEntry) -> Dot

    var body: some View {
        let columns = [GridItem(.adaptive(minimum: 20), spacing: 2)]
        LazyVGrid(columns: columns, alignment: .leading, spacing: 2) {
            ForEach(entries) { entry in
                dot(entry)
            }
        }
    }
}

extension GeometriesView {
    /// The geometry demonstration as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "geometries",
        name: "Geometries",
        systemImage: "square.on.circle",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(GeometriesView()) },
        hidesDocumentList: true
    )
}

glossary.source:
import SwiftUI

// MARK: - The personal glossary

/// One term as the reader keeps it: the word or phrase, and the gloss —
/// its meaning in the reader's own words.
nonisolated struct GlossaryTerm: Identifiable, Sendable {
    let id: String
    var term: String
    var gloss: String
}

/// The reader's personal glossary — after Jamie Blustein's personal
/// glossaries and the HAIKU group's annotation work at Dalhousie:
/// glosses in the reader's own words are how meaning is made from an
/// unfamiliar realm of discourse, and the glossary is the reader's, not
/// the text's. It lives locally, private like muting and filing — until
/// the reader chooses to publish it, whereupon it becomes an ordinary
/// document in the community folder carrying its terms in the format's
/// `concepts` field.
nonisolated enum PersonalGlossary {
    static let key = "personalGlossary"

    static func load() -> [GlossaryTerm] {
        let raw = UserDefaults.standard.array(forKey: key) as? [[String: String]] ?? []
        return raw.compactMap { entry in
            guard let id = entry["id"], let term = entry["term"] else { return nil }
            return GlossaryTerm(id: id, term: term, gloss: entry["gloss"] ?? "")
        }
    }

    static func save(_ terms: [GlossaryTerm]) {
        UserDefaults.standard.set(
            terms.map { ["id": $0.id, "term": $0.term, "gloss": $0.gloss] },
            forKey: key)
    }

    /// The `documentType` a published glossary declares.
    static let documentType = "glossary"
}

// MARK: - The view

/// Glossary: the reader's own terms, glossed in their own words, and —
/// the point of the view — projected across the whole community: every
/// passage in the library that speaks the term stands under the gloss,
/// one click from being read in place. Nothing here is generated; the
/// reader makes the meaning. Terms found in documents' own concept
/// glossaries (an Author import, another reader's published glossary)
/// can be adopted rather than retyped.
struct GlossaryView: View {
    @Environment(AppModel.self) private var model
    @State private var terms: [GlossaryTerm] = []
    @State private var selectedTermID: String?
    @State private var newTerm = ""
    @State private var newGloss = ""

    private var selectedTerm: GlossaryTerm? {
        terms.first { $0.id == selectedTermID }
    }

    /// Where terms are looked for: every text document except bots,
    /// trails, and glossaries — a glossary matching itself is noise.
    private var searchableEntries: [IndexEntry] {
        model.filteredEntries
            .filter { $0.doc.body != nil }
            .filter { $0.doc.documentType != BotDocument.documentType }
            .filter { $0.doc.documentType != TrailDocument.documentType }
            .filter { $0.doc.documentType != PersonalGlossary.documentType }
    }

    var body: some View {
        // HSplitView is the Mac's; elsewhere the same two columns stand
        // side by side without the draggable divider.
        #if os(macOS)
        HSplitView {
            termColumn
                .frame(minWidth: 240, idealWidth: 280, maxWidth: 360)
            detail
                .frame(minWidth: 360, maxWidth: .infinity, maxHeight: .infinity)
        }
        .onAppear { terms = PersonalGlossary.load() }
        #else
        HStack(spacing: 0) {
            termColumn
                .frame(minWidth: 240, idealWidth: 280, maxWidth: 360)
            Divider()
            detail
                .frame(minWidth: 360, maxWidth: .infinity, maxHeight: .infinity)
        }
        .onAppear { terms = PersonalGlossary.load() }
        #endif
    }

    // MARK: The term list

    private var termColumn: some View {
        VStack(spacing: 0) {
            HStack {
                Text("Your Glossary")
                    .font(.headline)
                Spacer()
                adoptMenu
                Button {
                    publish()
                } label: {
                    Image(systemName: "signature")
                }
                .buttonStyle(.plain)
                .disabled(terms.isEmpty)
                .help("Publish your glossary into the community folder — an ordinary document carrying your terms, for anyone to read or adopt")
            }
            .padding(10)
            Divider()
            if terms.isEmpty {
                VStack(spacing: 8) {
                    Text("A glossary is yours: terms from the community's discourse, glossed in your own words — the gloss is how the meaning becomes your own. Every passage in the library that speaks a term will stand under your gloss.")
                        .font(.callout)
                        .foregroundStyle(.secondary)
                    Text("After Jamie Blustein's personal glossaries and the HAIKU group's annotation studies at Dalhousie.")
                        .font(.caption)
                        .foregroundStyle(.tertiary)
                }
                .padding(14)
                .frame(maxHeight: .infinity, alignment: .top)
            } else {
                List(selection: $selectedTermID) {
                    ForEach(terms) { term in
                        VStack(alignment: .leading, spacing: 1) {
                            HStack {
                                Text(term.term)
                                    .fontWeight(.medium)
                                Spacer()
                                Text("\(occurrenceCount(of: term.term))")
                                    .font(.caption.monospacedDigit())
                                    .foregroundStyle(.secondary)
                                    .padding(.horizontal, 6)
                                    .padding(.vertical, 1)
                                    .background(.quaternary, in: Capsule())
                            }
                            if !term.gloss.isEmpty {
                                Text(term.gloss)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                    .lineLimit(2)
                            }
                        }
                        .tag(term.id)
                        .contextMenu {
                            Button("Remove Term", role: .destructive) {
                                terms.removeAll { $0.id == term.id }
                                if selectedTermID == term.id { selectedTermID = nil }
                                PersonalGlossary.save(terms)
                            }
                        }
                    }
                }
                .listStyle(.sidebar)
            }
            Divider()
            addBar
        }
    }

    private var addBar: some View {
        VStack(spacing: 6) {
            TextField("Term or phrase", text: $newTerm)
                .textFieldStyle(.roundedBorder)
            TextField("Its meaning, in your own words", text: $newGloss)
                .textFieldStyle(.roundedBorder)
                .onSubmit(addTerm)
            HStack {
                Spacer()
                Button("Add to Glossary", action: addTerm)
                    .disabled(newTerm.trimmingCharacters(in: .whitespaces).isEmpty)
            }
        }
        .padding(10)
    }

    private func addTerm() {
        let term = newTerm.trimmingCharacters(in: .whitespaces)
        guard !term.isEmpty else { return }
        let gloss = newGloss.trimmingCharacters(in: .whitespaces)
        let new = GlossaryTerm(id: UUID().uuidString.lowercased(), term: term, gloss: gloss)
        terms.append(new)
        PersonalGlossary.save(terms)
        newTerm = ""
        newGloss = ""
        selectedTermID = new.id
    }

    /// Terms already defined elsewhere in the library — a document's own
    /// concept glossary, or another reader's published glossary — offered
    /// for adoption, their glosses becoming a starting point for the
    /// reader's own.
    private var adoptMenu: some View {
        let have = Set(terms.map { $0.term.lowercased() })
        var offered: [(concept: LiquidDoc.Concept, source: String)] = []
        var seen: Set<String> = []
        for entry in model.filteredEntries {
            for concept in entry.doc.concepts {
                let key = concept.name.lowercased()
                guard !have.contains(key), seen.insert(key).inserted else { continue }
                offered.append((concept, entry.doc.title))
            }
        }
        return Menu {
            if offered.isEmpty {
                Text("No concepts found in the library's documents")
            }
            ForEach(offered, id: \.concept.id) { offer in
                Button("\(offer.concept.name) — from “\(offer.source)”") {
                    let new = GlossaryTerm(id: UUID().uuidString.lowercased(),
                                           term: offer.concept.name,
                                           gloss: offer.concept.description)
                    terms.append(new)
                    PersonalGlossary.save(terms)
                    selectedTermID = new.id
                }
            }
        } label: {
            Image(systemName: "square.and.arrow.down.on.square")
        }
        .menuStyle(.borderlessButton)
        .fixedSize()
        .help("Adopt a term another document already defines — its gloss becomes the start of yours")
    }

    // MARK: The gloss and its occurrences

    @ViewBuilder
    private var detail: some View {
        if let term = selectedTerm {
            occurrencesView(for: term)
        } else {
            ContentUnavailableView(
                "Choose a Term",
                systemImage: "character.book.closed",
                description: Text("Select a term to see your gloss and every passage in the library that speaks it — or add a term below the list."))
        }
    }

    private func occurrencesView(for term: GlossaryTerm) -> some View {
        let found = occurrences(of: term.term)
        return ScrollView {
            VStack(alignment: .leading, spacing: 12) {
                Text(term.term)
                    .font(.system(size: 24, weight: .bold, design: .serif))
                TextField("Your gloss — the meaning in your own words",
                          text: glossBinding(for: term.id), axis: .vertical)
                    .textFieldStyle(.plain)
                    .font(.system(size: 14))
                    .padding(10)
                    .background(.quaternary.opacity(0.4), in: RoundedRectangle(cornerRadius: 8))
                Divider()
                if found.isEmpty {
                    Text("No passage in the library speaks this term yet.")
                        .font(.callout)
                        .foregroundStyle(.secondary)
                } else {
                    Text("Where the community speaks it")
                        .font(.system(size: 17, weight: .bold, design: .serif))
                    ForEach(found, id: \.entry.id) { occurrence in
                        occurrenceGroup(occurrence, term: term.term)
                    }
                }
            }
            .frame(maxWidth: 640, alignment: .leading)
            .frame(maxWidth: .infinity)
            .padding(20)
        }
    }

    private func glossBinding(for id: String) -> Binding<String> {
        Binding(
            get: { terms.first { $0.id == id }?.gloss ?? "" },
            set: { newValue in
                guard let index = terms.firstIndex(where: { $0.id == id }) else { return }
                terms[index].gloss = newValue
                PersonalGlossary.save(terms)
            })
    }

    private func occurrenceGroup(_ occurrence: (entry: IndexEntry, paragraphs: [LiquidDoc.Paragraph]),
                                 term: String) -> some View {
        VStack(alignment: .leading, spacing: 4) {
            Text("\(occurrence.entry.doc.title) — \(occurrence.entry.doc.displayAuthor), \(occurrence.entry.doc.listedDateText)")
                .font(.caption.weight(.semibold))
                .foregroundStyle(.secondary)
            ForEach(occurrence.paragraphs) { paragraph in
                Button {
                    model.open(occurrence.entry.doc, fragment: paragraph.id)
                } label: {
                    Text(highlighted(paragraph.displayText, term: term))
                        .font(.system(size: 13))
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .padding(8)
                        .background(.quaternary.opacity(0.3), in: RoundedRectangle(cornerRadius: 6))
                        .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
                .help("Read it in place — the citation lands on this paragraph")
            }
        }
        .padding(.bottom, 4)
    }

    // MARK: Finding the term

    /// Whole-word, case-insensitive: "link" finds Link and links' but
    /// not blinked. Glossary Space matches with the same rule, so the
    /// two views always agree on where a term is spoken.
    nonisolated static func matcher(for term: String) -> NSRegularExpression? {
        let escaped = NSRegularExpression.escapedPattern(for: term)
        return try? NSRegularExpression(pattern: "\\b\(escaped)", options: [.caseInsensitive])
    }

    private func occurrences(of term: String) -> [(entry: IndexEntry, paragraphs: [LiquidDoc.Paragraph])] {
        guard let regex = Self.matcher(for: term) else { return [] }
        var result: [(entry: IndexEntry, paragraphs: [LiquidDoc.Paragraph])] = []
        for entry in searchableEntries {
            let appendixIDs = entry.doc.visualMetaParagraphIDs
            let hits = (entry.doc.body ?? []).filter { paragraph in
                guard !appendixIDs.contains(paragraph.id) else { return false }
                let text = paragraph.displayText
                return regex.firstMatch(in: text, range: NSRange(text.startIndex..., in: text)) != nil
            }
            if !hits.isEmpty {
                result.append((entry, hits))
            }
        }
        return result.sorted { $0.entry.doc.listedDate < $1.entry.doc.listedDate }
    }

    private func occurrenceCount(of term: String) -> Int {
        guard let regex = Self.matcher(for: term) else { return 0 }
        var count = 0
        for entry in searchableEntries {
            let appendixIDs = entry.doc.visualMetaParagraphIDs
            for paragraph in (entry.doc.body ?? []) where !appendixIDs.contains(paragraph.id) {
                let text = paragraph.displayText
                count += regex.numberOfMatches(in: text, range: NSRange(text.startIndex..., in: text))
            }
        }
        return count
    }

    /// The paragraph with the term lit: the reader's word, found in the
    /// community's mouth.
    private func highlighted(_ text: String, term: String) -> AttributedString {
        var attributed = AttributedString(text)
        guard let regex = Self.matcher(for: term) else { return attributed }
        for match in regex.matches(in: text, range: NSRange(text.startIndex..., in: text)) {
            guard let range = Range(match.range, in: attributed) else { continue }
            attributed[range].font = .system(size: 13, weight: .bold)
            attributed[range].backgroundColor = .yellow.opacity(0.3)
        }
        return attributed
    }

    // MARK: Publishing

    /// The glossary, on the record: an ordinary document — the terms as
    /// readable paragraphs for any text editor, and as `concepts` for any
    /// Origami app, so another reader can adopt them term by term.
    private func publish() {
        guard let folder = model.index.folderURL else {
            model.showNote("Choose a community folder first — the glossary would live there.")
            return
        }
        let created = Date.now
        let author = model.authorName
        let id = LiquidAddress.makeID(author: author, created: created,
                                      isTaken: { model.index.isIDTaken($0) })
        var paragraphs: [LiquidDoc.Paragraph] = []
        var counter = 0
        func add(_ text: String, heading: Int? = nil) {
            counter += 1
            paragraphs.append(LiquidDoc.Paragraph(id: "p\(counter)", heading: heading, text: text))
        }
        add("A personal glossary: terms from this community's discourse, glossed in the author's own words. Published so others can read the glosses and adopt the terms into glossaries of their own; the meanings claim no authority beyond their usefulness.")
        add("Terms", heading: 2)
        let ordered = terms.sorted { $0.term.localizedCaseInsensitiveCompare($1.term) == .orderedAscending }
        for term in ordered {
            add(term.gloss.isEmpty ? term.term : "\(term.term) — \(term.gloss)")
        }
        let title = "\(author)'s Glossary"
        let slug = LiquidDoc.fileSlug(from: title)
        let ext = LiquidDoc.fileExtension
        let fileName = slug.isEmpty ? "\(id).\(ext)" : "\(slug)--\(id).\(ext)"
        var doc = LiquidDoc(format: LiquidDoc.knownFormat,
                            id: id,
                            title: title,
                            author: author,
                            created: created,
                            body: paragraphs,
                            links: [],
                            wraps: nil,
                            fileURL: folder.appendingPathComponent(fileName))
        doc.documentType = PersonalGlossary.documentType
        doc.concepts = ordered.map {
            LiquidDoc.Concept(id: $0.id, name: $0.term, description: $0.gloss)
        }
        let finished = VisualMeta.appendingAppendix(to: doc)
        do {
            try finished.jsonData().write(to: finished.fileURL, options: .atomic)
            model.showNote("“\(title)” is published — its terms can be adopted by anyone in the community.")
        } catch {
            model.showNote("Could not publish the glossary: \(error.localizedDescription)")
        }
    }
}

extension GlossaryView {
    /// The personal glossary as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "glossary",
        name: "Glossary",
        systemImage: "character.book.closed",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(GlossaryView()) },
        hidesDocumentList: true
    )
}

