import SwiftUI

/// The most-cited paragraphs across the library — the sentences the
/// community keeps pointing at. Clicking one opens the document scrolled
/// to that paragraph with the flash highlight.
struct HotParagraphsView: View {
    @Environment(AppModel.self) private var model

    var body: some View {
        let hotParagraphs = model.hotParagraphs
        List {
            ForEach(hotParagraphs) { hot in
                Button {
                    model.openInLibrary(hot.doc, fragment: hot.paragraph.id)
                } label: {
                    HStack(alignment: .top, spacing: 10) {
                        Text("\(hot.citations.count)")
                            .font(.headline.monospacedDigit())
                            .frame(minWidth: 24)
                            .padding(.vertical, 5)
                            .padding(.horizontal, 4)
                            .background(.quaternary, in: RoundedRectangle(cornerRadius: 6))
                            .help(hot.citations.count == 1 ? "Cited by 1 document" : "Cited by \(hot.citations.count) documents")
                        VStack(alignment: .leading, spacing: 3) {
                            Text(hot.paragraph.displayText)
                                .lineLimit(3)
                            Text("\(hot.doc.title) · \(hot.doc.displayAuthor) · ¶\(hot.paragraph.id)")
                                .font(.caption)
                                .foregroundStyle(.secondary)
                                .lineLimit(1)
                            citingLine(for: hot)
                        }
                    }
                    .padding(.vertical, 3)
                    .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
            }
        }
        .overlay {
            if hotParagraphs.isEmpty {
                ContentUnavailableView {
                    Label(model.searchText.isEmpty ? "No Cited Paragraphs" : "No Results",
                          systemImage: "quote.bubble")
                } description: {
                    Text("Paragraphs appear here once documents cite them directly (links with a fragment).")
                }
            }
        }
    }

    @ViewBuilder
    private func citingLine(for hot: HotParagraph) -> some View {
        let names = hot.citations
            .compactMap { model.index.byID[$0.fromID]?.doc.title }
        if !names.isEmpty {
            Text("Cited in: \(names.joined(separator: ", "))")
                .font(.caption2)
                .foregroundStyle(.tertiary)
                .lineLimit(1)
        }
    }
}

extension HotParagraphsView {
    /// The Hot Paragraphs view as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "hot-paragraphs",
        name: "Hot Paragraphs",
        systemImage: "quote.bubble",
        makeContent: { AnyView(HotParagraphsView()) }
    )
}

k-nav.source:
import SwiftUI
import NaturalLanguage
import FoundationModels

// MARK: - The engine

/// K. Nav — Knowledge Navigator, from Tom's spec: make augmented
/// thinking visible at corpus scale. Two modes over the library's
/// paragraphs: **clusters**, the strong, expected groupings (a solved
/// problem, done plainly), and **bridges**, the point of the tool —
/// pairs with *low* surface similarity that are nonetheless structurally
/// related, Granovetter's weak ties. Every cluster and bridge carries a
/// reasoning trace as a first-class output: what was compared, what
/// scored what, and why a low-similarity pair was judged significant
/// rather than noise. Everything runs on this Mac — embeddings are the
/// system's own (NaturalLanguage), and the traces are computed, never
/// generated, so the trace cannot hallucinate.
nonisolated enum KNavEngine {

    /// One unit of content: a paragraph, the library's addressable
    /// granularity (the spec's open question §8, answered by the format).
    struct Unit: Identifiable, Sendable {
        let id: String          // docID#paragraphID
        let docID: String
        let paragraphID: String
        let docTitle: String
        let author: String
        let text: String
        var vector: [Double] = []
    }

    struct Parameters: Sendable {
        var mode: Mode = .bridges
        /// The truncation threshold: pairs at or above it form the
        /// cluster graph; pairs *below* it are where bridges are sought —
        /// sweep it to learn where the useful bridges live.
        var threshold: Double = 0.6
        /// The experimental arm (§5a): seeded random sign-projection of
        /// the embedding space before comparison — controlled randomness
        /// against the overly clean solution. Off = the exact baseline.
        var sketch = false
        var seed: UInt64 = 42
    }

    enum Mode: String, CaseIterable, Sendable {
        case clusters = "Clusters"
        case bridges = "Bridges"
    }

    struct Cluster: Identifiable, Sendable {
        let id: Int
        let unitIDs: [String]
        let trace: String
    }

    struct Bridge: Identifiable, Sendable {
        let a: String
        let b: String
        let mediator: String
        let directSimilarity: Double
        let mediatedSimilarity: Double
        /// mediated minus direct — how much more these two share through
        /// their mediator than face to face.
        let score: Double
        let strong: Bool
        let trace: String
        var id: String { "\(a)↔\(b)" }
    }

    /// A pair of units the run found tied at or above the threshold —
    /// the weave presentation's strong threads.
    struct Edge: Sendable {
        let a: String
        let b: String
    }

    /// One run, whole: its parameters and everything found, so runs at
    /// different thresholds and seeds stand side by side (§4.6).
    struct Run: Identifiable, Sendable {
        let id = UUID()
        let parameters: Parameters
        let unitCount: Int
        let clusters: [Cluster]
        let bridges: [Bridge]
        let clusterEdges: [Edge]
        let note: String
    }

    /// Embeds every unit with the system sentence embedding (word
    /// embedding averaged as the fallback). Returns nil when the Mac
    /// offers neither.
    static func embed(_ units: [Unit]) -> [Unit]? {
        if let sentence = NLEmbedding.sentenceEmbedding(for: .english) {
            return units.compactMap { unit in
                guard let vector = sentence.vector(for: unit.text) else { return nil }
                var embedded = unit
                embedded.vector = vector
                return embedded
            }
        }
        guard let word = NLEmbedding.wordEmbedding(for: .english) else { return nil }
        return units.compactMap { unit in
            var sum = [Double](repeating: 0, count: word.dimension)
            var counted = 0
            for token in unit.text.lowercased().split(whereSeparator: { !$0.isLetter }) {
                guard let vector = word.vector(for: String(token)) else { continue }
                for index in vector.indices { sum[index] += vector[index] }
                counted += 1
            }
            guard counted > 0 else { return nil }
            var embedded = unit
            embedded.vector = sum.map { $0 / Double(counted) }
            return embedded
        }
    }

    /// The whole diagnostic, off the main thread: similarity space
    /// (sketched or exact), clusters at the threshold, bridges below it.
    static func compute(units: [Unit], parameters: Parameters) -> Run {
        var vectors = units.map(\.vector)
        var note = "\(units.count) paragraphs compared"
        if parameters.sketch {
            vectors = sketch(vectors, seed: parameters.seed)
            note += " · sketched (seed \(parameters.seed))"
        } else {
            note += " · exact baseline"
        }
        let n = units.count
        var similarity = [[Double]](repeating: [Double](repeating: 0, count: n), count: n)
        for i in 0..<n {
            for j in (i + 1)..<n {
                let value = cosine(vectors[i], vectors[j])
                similarity[i][j] = value
                similarity[j][i] = value
            }
        }
        let clusterIndex = componentClusters(similarity: similarity, threshold: parameters.threshold)
        let clusters = describeClusters(units: units, similarity: similarity,
                                        membership: clusterIndex, threshold: parameters.threshold)
        let bridges = findBridges(units: units, similarity: similarity,
                                  membership: clusterIndex, threshold: parameters.threshold)
        var clusterEdges: [Edge] = []
        outer: for i in 0..<n {
            for j in (i + 1)..<n where similarity[i][j] >= parameters.threshold {
                clusterEdges.append(Edge(a: units[i].id, b: units[j].id))
                if clusterEdges.count >= 1200 { break outer }   // stay legible and fast
            }
        }
        return Run(parameters: parameters, unitCount: n,
                   clusters: clusters, bridges: bridges,
                   clusterEdges: clusterEdges, note: note)
    }

    // MARK: The similarity space

    static func cosine(_ a: [Double], _ b: [Double]) -> Double {
        guard a.count == b.count, !a.isEmpty else { return 0 }
        var dot = 0.0, magA = 0.0, magB = 0.0
        for index in a.indices {
            dot += a[index] * b[index]
            magA += a[index] * a[index]
            magB += b[index] * b[index]
        }
        let magnitude = (magA * magB).squareRoot()
        return magnitude > 0 ? dot / magnitude : 0
    }

    /// The experimental arm: a seeded random sign projection (a classic
    /// sketch) to a quarter of the dimensions. Deliberate, controlled
    /// randomness in the reduction — the hypothesis under test, not a
    /// known-good algorithm.
    static func sketch(_ vectors: [[Double]], seed: UInt64) -> [[Double]] {
        guard let dimension = vectors.first?.count, dimension > 8 else { return vectors }
        let reduced = max(dimension / 4, 8)
        var generator = SplitMix64(seed: seed)
        // One shared projection: rows of random signs.
        var projection: [[Double]] = []
        for _ in 0..<reduced {
            projection.append((0..<dimension).map { _ in
                Bool.random(using: &generator) ? 1.0 : -1.0
            })
        }
        return vectors.map { vector in
            projection.map { row in
                var sum = 0.0
                for index in vector.indices { sum += row[index] * vector[index] }
                return sum
            }
        }
    }

    struct SplitMix64: RandomNumberGenerator {
        var state: UInt64
        init(seed: UInt64) { state = seed }
        mutating func next() -> UInt64 {
            state &+= 0x9E3779B97F4A7C15
            var z = state
            z = (z ^ (z >> 30)) &* 0xBF58476D1CE4E5B9
            z = (z ^ (z >> 27)) &* 0x94D049BB133111EB
            return z ^ (z >> 31)
        }
    }

    // MARK: Clusters — the solved problem, done plainly

    /// Connected components over the graph of pairs at or above the
    /// threshold: the strong, expected groupings.
    static func componentClusters(similarity: [[Double]], threshold: Double) -> [Int] {
        let n = similarity.count
        var membership = Array(0..<n)
        func root(_ index: Int) -> Int {
            var current = index
            while membership[current] != current { current = membership[current] }
            return current
        }
        for i in 0..<n {
            for j in (i + 1)..<n where similarity[i][j] >= threshold {
                membership[root(j)] = root(i)
            }
        }
        return (0..<n).map { root($0) }
    }

    static func describeClusters(units: [Unit], similarity: [[Double]],
                                 membership: [Int], threshold: Double) -> [Cluster] {
        var groups: [Int: [Int]] = [:]
        for (index, group) in membership.enumerated() {
            groups[group, default: []].append(index)
        }
        var clusters: [Cluster] = []
        for (_, members) in groups where members.count >= 2 {
            var lowest = 1.0, highest = 0.0
            for i in members {
                for j in members where j > i {
                    lowest = min(lowest, similarity[i][j])
                    highest = max(highest, similarity[i][j])
                }
            }
            let documents = Set(members.map { units[$0].docTitle })
            let trace = "Grouped because every member is reachable through pairwise "
                + "similarity ≥ \(String(format: "%.2f", threshold)) (the truncation threshold). "
                + "Internal similarities run \(String(format: "%.2f", lowest))–\(String(format: "%.2f", highest)). "
                + "\(members.count) paragraphs from \(documents.count) document\(documents.count == 1 ? "" : "s") — "
                + (documents.count == 1
                   ? "one document talking to itself, the expected kind of grouping."
                   : "several documents converging, a grouping worth reading.")
            clusters.append(Cluster(id: clusters.count,
                                    unitIDs: members.map { units[$0].id },
                                    trace: trace))
        }
        return clusters.sorted { $0.unitIDs.count > $1.unitIDs.count }
    }

    // MARK: Bridges — the point of the tool

    /// A bridge: two paragraphs from different documents and different
    /// clusters whose direct similarity fell below the truncation
    /// threshold — the pairs the reduction throws away — yet which share
    /// a mediator both speak to. The score is what they share through
    /// the mediator minus what they share face to face; the trace is the
    /// case, and the case is checkable by reading.
    static func findBridges(units: [Unit], similarity: [[Double]],
                            membership: [Int], threshold: Double) -> [Bridge] {
        let n = units.count
        var bridges: [Bridge] = []
        for a in 0..<n {
            for b in (a + 1)..<n {
                guard units[a].docID != units[b].docID,
                      membership[a] != membership[b],
                      similarity[a][b] < threshold else { continue }
                // The best mediator: the unit both ends speak to most.
                var bestMediator = -1
                var bestMediated = 0.0
                for m in 0..<n where m != a && m != b {
                    let mediated = min(similarity[a][m], similarity[b][m])
                    if mediated > bestMediated {
                        bestMediated = mediated
                        bestMediator = m
                    }
                }
                guard bestMediator >= 0 else { continue }
                let direct = similarity[a][b]
                let score = bestMediated - direct
                guard score > 0.12, bestMediated > 0.35 else { continue }
                let strong = score > 0.25 && bestMediated > 0.5
                let mediator = units[bestMediator]
                let trace = "Direct similarity is only \(String(format: "%.2f", direct)) — "
                    + "below the truncation threshold of \(String(format: "%.2f", threshold)), so any "
                    + "reduction keeping only strong signals discards this pair. Yet both speak to a third "
                    + "paragraph — “\(mediator.docTitle)” [\(mediator.id)] — at "
                    + "\(String(format: "%.2f", similarity[a][bestMediator])) and "
                    + "\(String(format: "%.2f", similarity[b][bestMediator])). They sit in different "
                    + "clusters and different documents: a weak tie joining otherwise-separate "
                    + "neighborhoods (Granovetter 1973). Score \(String(format: "%.2f", score)) = mediated "
                    + "\(String(format: "%.2f", bestMediated)) − direct \(String(format: "%.2f", direct)). "
                    + (strong
                       ? "Strong signal — the mediation is well above noise."
                       : "Weak signal — worth a human look, and honestly marked as such.")
                bridges.append(Bridge(a: units[a].id, b: units[b].id,
                                      mediator: mediator.id,
                                      directSimilarity: direct,
                                      mediatedSimilarity: bestMediated,
                                      score: score, strong: strong, trace: trace))
            }
        }
        // The best bridge per document pair, strongest first, a dozen at
        // most — a diagnostic reads a page, not a firehose.
        var byDocumentPair: [String: Bridge] = [:]
        for bridge in bridges {
            let docs = [String(bridge.a.split(separator: "#")[0]),
                        String(bridge.b.split(separator: "#")[0])].sorted().joined(separator: "|")
            if let existing = byDocumentPair[docs], existing.score >= bridge.score { continue }
            byDocumentPair[docs] = bridge
        }
        return byDocumentPair.values.sorted { $0.score > $1.score }.prefix(12).map { $0 }
    }
}

// MARK: - Keyword stances, as the model returns them

/// One connected paragraph's stance toward the typed keyword, grounded
/// by address before display like every AI view's output.
@Generable
nonisolated struct GeneratedKeywordStance {
    @Guide(description: "The paragraph's address, copied exactly from its == line")
    var address: String
    @Guide(description: "The paragraph's stance toward the keyword", .anyOf(["positive", "negative", "neutral", "questions"]))
    var stance: String
}

@Generable
nonisolated struct GeneratedKeywordStances {
    @Guide(description: "One stance for every paragraph given, in the order given")
    var stances: [GeneratedKeywordStance]
}

// MARK: - The view

/// K. Nav: the Knowledge Navigator diagnostic as a library view. Choose
/// the mode, set the truncation threshold, optionally turn on the
/// sketch (seeded randomness in the reduction — the spec's hypothesis
/// under test) and run; every run is kept in the session so thresholds
/// and seeds can be compared side by side. Clusters are the expected
/// groupings; bridges are the low-similarity, cross-document pairs a
/// truncation would discard, each with the reasoning trace that makes
/// it checkable — read both ends side by side and judge.
struct KNavView: View {
    @Environment(AppModel.self) private var model
    @State private var mode: KNavEngine.Mode = .bridges
    @State private var presentation: Presentation = .list
    @State private var threshold = 0.6

    /// How a run is shown: the list carries the traces; the weave is
    /// the wheel — paragraphs as knots of light grouped by document,
    /// strong ties as the breathing field, and the bridges as bright
    /// dashed threads. Hover a knot and its threads flare; drag to
    /// spin; click a knot to read the paragraph in place.
    private enum Presentation: String, CaseIterable {
        case list = "List"
        case weave = "Weave"
    }
    @State private var sketch = false
    @State private var seed = 42
    @State private var runs: [KNavEngine.Run] = []
    @State private var selectedRunID: UUID?
    @State private var isRunning = false
    @State private var errorText: String?
    @State private var unfurled: Set<String> = []
    /// Units by id, kept from the latest embedding so results resolve to
    /// text and documents.
    @State private var unitsByID: [String: KNavEngine.Unit] = [:]
    /// The probe: the typed text, and its kinship to every compared
    /// paragraph — shown at the hub of the weave with threads outward,
    /// each colored by the paragraph's stance toward the keyword once
    /// the on-device model has read it.
    @State private var probeText = ""
    @State private var probeResult: (text: String, threads: [(unitID: String, strength: Double, stance: ProbeStance?)])?
    /// True while the on-device model is reading the connected
    /// paragraphs for their stances; the threads stand white meanwhile.
    @State private var stancesPending = false
    /// A probe typed before any run exists waits for the run to finish.
    @State private var pendingProbe: String?

    /// A connected paragraph's stance toward the keyword, and the color
    /// its thread takes: for the keyword green, against it red, merely
    /// speaking of it blue, asking about it orange.
    enum ProbeStance: String, Sendable {
        case positive, negative, neutral, questions

        var color: Color {
            switch self {
            case .positive: .green
            case .negative: .red
            case .neutral: .blue
            case .questions: .orange
            }
        }

        var label: String {
            switch self {
            case .positive: "positive"
            case .negative: "negative"
            case .neutral: "neutral"
            case .questions: "questions it"
            }
        }
    }

    private var selectedRun: KNavEngine.Run? {
        runs.first { $0.id == selectedRunID } ?? runs.last
    }

    var body: some View {
        VStack(spacing: 0) {
            controls
            Divider()
            if !runs.isEmpty {
                runStrip
                Divider()
            }
            results
        }
    }

    // MARK: Controls

    private var controls: some View {
        HStack(spacing: 12) {
            Picker("Mode", selection: $mode) {
                ForEach(KNavEngine.Mode.allCases, id: \.self) { Text($0.rawValue) }
            }
            .pickerStyle(.segmented)
            .fixedSize()
            .labelsHidden()
            .help("Clusters: the strong, expected groupings. Bridges: the low-similarity, cross-document connections a truncation would throw away — the point of the tool.")
            HStack(spacing: 6) {
                Text("Truncation")
                Slider(value: $threshold, in: 0.35...0.85)
                    .frame(width: 140)
                Text(String(format: "%.2f", threshold))
                    .font(.caption.monospacedDigit())
                    .frame(width: 34, alignment: .leading)
            }
            .help("The truncation threshold: pairs at or above it form clusters; bridges are sought among the pairs below it. Sweep it across runs to learn where the useful bridges live.")
            Toggle("Sketch", isOn: $sketch)
                #if os(macOS)
                .toggleStyle(.checkbox)
                #endif
                .help("The experimental arm: seeded random sign-projection of the embedding space before comparison — controlled randomness against an overly clean reduction. Off is the exact baseline.")
            if sketch {
                Stepper("Seed \(seed)", value: $seed, in: 1...999)
                    .font(.caption)
                    .fixedSize()
            }
            Button {
                run()
            } label: {
                Label(isRunning ? "Comparing…" : "Run", systemImage: "point.topleft.down.to.point.bottomright.curvepath")
            }
            .disabled(isRunning)
            if isRunning {
                ProgressView()
                    .controlSize(.small)
            }
            Spacer()
            TextField("Hold a thought to the weave…", text: $probeText)
                .textFieldStyle(.roundedBorder)
                .frame(width: 240)
                .onSubmit(submitProbe)
                .help("Press Return and your words stand at the hub of the weave, with threads of kinship out to the paragraphs closest to them — same on-device embedding, computed exactly. Submit empty to clear.")
            Picker("Presentation", selection: $presentation) {
                ForEach(Presentation.allCases, id: \.self) { Text($0.rawValue) }
            }
            .pickerStyle(.segmented)
            .fixedSize()
            .labelsHidden()
            .help("List carries the reasoning traces; Weave is the wheel — knots by document, strong ties as the field, bridges as bright dashed threads. Hover to flare, drag to spin, click a knot to read.")
        }
        .font(.callout)
        .padding(10)
    }

    // MARK: The probe

    /// Return holds the typed words to the weave: they are embedded like
    /// any paragraph and threaded to their nearest kin. An empty submit
    /// clears the probe; a probe before any run waits for the first one.
    private func submitProbe() {
        let text = probeText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else {
            probeResult = nil
            pendingProbe = nil
            return
        }
        presentation = .weave
        if unitsByID.isEmpty {
            pendingProbe = text
            if !isRunning { run() }
            return
        }
        computeProbe(text)
    }

    private func computeProbe(_ text: String) {
        let units = Array(unitsByID.values)
        stancesPending = false
        Task.detached(priority: .userInitiated) {
            let seed = KNavEngine.Unit(id: "probe", docID: "", paragraphID: "",
                                       docTitle: "", author: "", text: text)
            guard let embedded = KNavEngine.embed([seed])?.first else {
                await MainActor.run {
                    errorText = "No on-device embedding is available for the probe."
                }
                return
            }
            // Kinship is always computed exactly — the probe is a reading
            // aid, not part of the experiment's sketched arm.
            let floor = 0.3
            let threads = units
                .map { (unitID: $0.id,
                        similarity: KNavEngine.cosine(embedded.vector, $0.vector)) }
                .filter { $0.similarity >= floor }
                .sorted { $0.similarity > $1.similarity }
                .prefix(12)
                .map { (unitID: $0.unitID,
                        strength: min(max(($0.similarity - floor) / 0.4, 0), 1),
                        stance: ProbeStance?.none) }
            let modelReady: Bool = {
                if case .available = SystemLanguageModel.default.availability { return true }
                return false
            }()
            await MainActor.run {
                probeResult = (text: text, threads: Array(threads))
                stancesPending = modelReady && !threads.isEmpty
            }
            // The stances: one grounded call over just the connected
            // paragraphs — each thread colored by what its paragraph
            // holds toward the keyword. Without Apple Intelligence the
            // threads simply stay white; kinship alone is still honest.
            guard modelReady, !threads.isEmpty else { return }
            let byID = Dictionary(uniqueKeysWithValues: units.map { ($0.id, $0) })
            var prompt = """
            A reader typed a keyword over a library of documents. For each paragraph below, judge the paragraph's stance toward the keyword: "positive" when it speaks for it, supports it, or treats it favorably; "negative" when it speaks against it or treats it unfavorably; "questions" when it asks about, doubts, or challenges it; "neutral" when it merely mentions or relates to it without judgement. Each paragraph begins with a == line giving its address — copy addresses exactly. Judge every paragraph given, no others.

            THE KEYWORD: \(text)

            THE PARAGRAPHS:

            """
            for thread in threads {
                guard let unit = byID[thread.unitID] else { continue }
                prompt += "== [\(unit.id)]\n\(String(unit.text.prefix(400)))\n\n"
            }
            do {
                let session = LanguageModelSession()
                let response = try await session.respond(to: prompt,
                                                         generating: GeneratedKeywordStances.self)
                var stanceByID: [String: ProbeStance] = [:]
                for judged in response.content.stances {
                    let id = judged.address.trimmingCharacters(in: CharacterSet(charactersIn: "[] "))
                    if let stance = ProbeStance(rawValue: judged.stance) {
                        stanceByID[id] = stance
                    }
                }
                await MainActor.run {
                    // A newer probe may have replaced this one meanwhile.
                    guard probeResult?.text == text else { return }
                    probeResult = (text: text, threads: threads.map {
                        (unitID: $0.unitID, strength: $0.strength, stance: stanceByID[$0.unitID])
                    })
                    stancesPending = false
                }
            } catch {
                await MainActor.run {
                    if probeResult?.text == text { stancesPending = false }
                }
            }
        }
    }

    /// Every run of the session, side by side — the comparison the
    /// diagnostic exists for.
    private var runStrip: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 6) {
                ForEach(runs) { run in
                    let isSelected = run.id == (selectedRun?.id)
                    Button {
                        selectedRunID = run.id
                    } label: {
                        Text(label(for: run))
                            .font(.caption.monospacedDigit())
                            .padding(.horizontal, 8)
                            .padding(.vertical, 3)
                            .background(isSelected ? AnyShapeStyle(Color.accentColor.opacity(0.15))
                                                   : AnyShapeStyle(.quaternary.opacity(0.5)),
                                        in: Capsule())
                            .overlay(Capsule().strokeBorder(
                                isSelected ? Color.accentColor : .clear, lineWidth: 1))
                    }
                    .buttonStyle(.plain)
                }
            }
            .padding(8)
        }
    }

    private func label(for run: KNavEngine.Run) -> String {
        let sketchPart = run.parameters.sketch ? " · seed \(run.parameters.seed)" : " · exact"
        let counts = "\(run.clusters.count) clusters, \(run.bridges.count) bridges"
        return "τ \(String(format: "%.2f", run.parameters.threshold))\(sketchPart) → \(counts)"
    }

    // MARK: Results

    @ViewBuilder
    private var results: some View {
        if presentation == .weave, let run = selectedRun {
            weave(for: run)
        } else {
            list
        }
    }

    // MARK: The weave presentation

    /// The run on the wheel: every compared paragraph a knot of light,
    /// documents around the rim where the Weave puts authors, the strong
    /// ties (≥ τ) as the breathing field, and the bridges — the point of
    /// the tool — as the bright dashed threads joining distant arcs.
    private func weave(for run: KNavEngine.Run) -> some View {
        let built = weaveData(for: run)
        var probe: WeaveProbe?
        if let probeResult {
            probe = WeaveProbe(
                label: probeResult.text,
                threads: probeResult.threads.compactMap { thread in
                    built.indexByID[thread.unitID].map {
                        (node: $0, strength: thread.strength, tint: thread.stance?.color)
                    }
                })
        }
        return WeaveCanvas(
            data: built.data,
            onOpen: { unitID in
                if let unit = unitsByID[unitID],
                   let doc = model.index.byID[unit.docID]?.doc {
                    model.open(doc, fragment: unit.paragraphID)
                }
            },
            title: "K. Nav",
            subtitle: "\(built.data.nodes.count) paragraphs · \(built.data.edges.count) strong ties · \(built.bright.count) bridges — τ \(String(format: "%.2f", run.parameters.threshold))\(run.parameters.sketch ? " · seed \(run.parameters.seed)" : " · exact")",
            brightEdges: built.bright,
            probe: probe)
        .overlay(alignment: .bottom) {
            if probeResult != nil {
                stanceLegend
            }
        }
    }

    /// What the probe's colors mean, standing where the Weave puts its
    /// captions. White while stances are still being read.
    private var stanceLegend: some View {
        HStack(spacing: 12) {
            if stancesPending {
                ProgressView()
                    .controlSize(.mini)
                Text("reading stances toward “\(String(probeText.prefix(24)))”…")
            } else {
                stanceSwatch(.positive)
                stanceSwatch(.negative)
                stanceSwatch(.neutral)
                stanceSwatch(.questions)
            }
            HStack(spacing: 4) {
                Rectangle()
                    .fill(Color(white: 0.35))
                    .frame(width: 14, height: 2)
                Text("everything else")
            }
        }
        .font(.caption)
        .foregroundStyle(.white.opacity(0.75))
        .padding(.horizontal, 12)
        .padding(.vertical, 6)
        .background(.white.opacity(0.08), in: Capsule())
        .padding(.bottom, 10)
        .allowsHitTesting(false)
    }

    private func stanceSwatch(_ stance: ProbeStance) -> some View {
        HStack(spacing: 4) {
            Rectangle()
                .fill(stance.color)
                .frame(width: 14, height: 2)
            Text(stance.label)
        }
    }

    private func weaveData(for run: KNavEngine.Run) -> (data: WeaveData, bright: [WeaveEdge],
                                                        indexByID: [String: Int]) {
        // Documents around the wheel, their paragraphs in body order —
        // time runs along each document's arc, as it does for the
        // Weave's authors.
        let units = unitsByID.values.sorted {
            ($0.docTitle, paragraphNumber($0.paragraphID)) < ($1.docTitle, paragraphNumber($1.paragraphID))
        }
        var data = WeaveData()
        var indexByID: [String: Int] = [:]
        // Bridge participation makes the knot: bridges are what the
        // wheel exists to show.
        var weight: [String: Int] = [:]
        for bridge in run.bridges {
            weight[bridge.a, default: 0] += 4
            weight[bridge.b, default: 0] += 4
            weight[bridge.mediator, default: 0] += 2
        }
        for edge in run.clusterEdges {
            weight[edge.a, default: 0] += 1
            weight[edge.b, default: 0] += 1
        }
        let documents = Array(Set(units.map(\.docTitle))).sorted()
        let hueByDocument = Dictionary(uniqueKeysWithValues: documents.enumerated().map {
            ($1, Double($0) / Double(max(documents.count, 1)))
        })
        var arcStart = 0
        var arcDocument: String?
        for unit in units {
            if unit.docTitle != arcDocument {
                if let name = arcDocument, data.nodes.count > arcStart {
                    data.authorArcs.append((String(name.prefix(22)),
                                            hueByDocument[name] ?? 0,
                                            arcStart...(data.nodes.count - 1)))
                }
                arcDocument = unit.docTitle
                arcStart = data.nodes.count
            }
            indexByID[unit.id] = data.nodes.count
            data.nodes.append(WeaveNode(id: unit.id,
                                        title: String(unit.text.prefix(90)),
                                        author: unit.docTitle,
                                        weight: weight[unit.id] ?? 0,
                                        hue: hueByDocument[unit.docTitle] ?? 0))
        }
        if let name = arcDocument, data.nodes.count > arcStart {
            data.authorArcs.append((String(name.prefix(22)),
                                    hueByDocument[name] ?? 0,
                                    arcStart...(data.nodes.count - 1)))
        }
        for edge in run.clusterEdges {
            guard let from = indexByID[edge.a], let to = indexByID[edge.b] else { continue }
            data.edges.append(WeaveEdge(from: from, to: to))
        }
        var bright: [WeaveEdge] = []
        for bridge in run.bridges {
            guard let from = indexByID[bridge.a], let to = indexByID[bridge.b] else { continue }
            bright.append(WeaveEdge(from: from, to: to))
        }
        return (data, bright, indexByID)
    }

    private func paragraphNumber(_ paragraphID: String) -> Int {
        Int(paragraphID.drop(while: { !$0.isNumber })) ?? 0
    }

    // MARK: The list presentation

    @ViewBuilder
    private var list: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 12) {
                if let errorText {
                    Text(errorText)
                        .font(.callout)
                        .foregroundStyle(.red)
                }
                if let run = selectedRun {
                    Text(run.note)
                        .font(.caption)
                        .foregroundStyle(.secondary)
                    if mode == .clusters {
                        if run.clusters.isEmpty {
                            Text("No cluster holds at this threshold — lower it and run again.")
                                .font(.callout)
                                .foregroundStyle(.secondary)
                        }
                        ForEach(run.clusters) { cluster in
                            clusterRow(cluster)
                        }
                    } else {
                        if run.bridges.isEmpty {
                            Text("No defensible bridge at this threshold — an honest empty answer. Try other thresholds and seeds; over-conservative and over-permissive are both findings.")
                                .font(.callout)
                                .foregroundStyle(.secondary)
                        }
                        ForEach(run.bridges) { bridge in
                            bridgeRow(bridge)
                        }
                    }
                } else if !isRunning {
                    Text("K. Nav — the Knowledge Navigator diagnostic, from Tom's spec, run over this library's paragraphs. Clusters finds the strong, expected groupings; Bridges finds the pairs with low surface similarity that are nonetheless structurally related — Granovetter's weak ties, the connections worth surfacing. Every result carries its reasoning trace: computed, not generated, so the trace cannot hallucinate. Embeddings are the system's own; nothing leaves this Mac. Run at several thresholds — the runs stand side by side.")
                        .font(.callout)
                        .foregroundStyle(.secondary)
                }
            }
            .frame(maxWidth: 680, alignment: .leading)
            .frame(maxWidth: .infinity)
            .padding(16)
        }
    }

    @ViewBuilder
    private func clusterRow(_ cluster: KNavEngine.Cluster) -> some View {
        let key = "c\(cluster.id)"
        Button {
            withAnimation(.snappy) {
                if unfurled.contains(key) { unfurled.remove(key) } else { unfurled.insert(key) }
            }
        } label: {
            HStack(alignment: .firstTextBaseline, spacing: 7) {
                Image(systemName: unfurled.contains(key) ? "chevron.down" : "chevron.right")
                    .font(.caption)
                    .foregroundStyle(.secondary)
                Text(clusterTitle(cluster))
                    .font(.system(size: 17, weight: .bold, design: .serif))
                Text("\(cluster.unitIDs.count)")
                    .font(.caption.monospacedDigit())
                    .foregroundStyle(.secondary)
                    .padding(.horizontal, 6)
                    .padding(.vertical, 1)
                    .background(.quaternary, in: Capsule())
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .padding(.top, 4)
        if unfurled.contains(key) {
            Text(cluster.trace)
                .font(.callout)
                .italic()
                .foregroundStyle(.secondary)
                .padding(.leading, 18)
            ForEach(cluster.unitIDs, id: \.self) { unitID in
                if let unit = unitsByID[unitID] {
                    unitRow(unit)
                }
            }
        }
    }

    private func clusterTitle(_ cluster: KNavEngine.Cluster) -> String {
        let titles = cluster.unitIDs.compactMap { unitsByID[$0]?.docTitle }
        let distinct = Array(Set(titles)).sorted()
        return distinct.prefix(2).joined(separator: " · ")
            + (distinct.count > 2 ? " · …" : "")
    }

    @ViewBuilder
    private func bridgeRow(_ bridge: KNavEngine.Bridge) -> some View {
        let key = bridge.id
        Button {
            withAnimation(.snappy) {
                if unfurled.contains(key) { unfurled.remove(key) } else { unfurled.insert(key) }
            }
        } label: {
            HStack(alignment: .firstTextBaseline, spacing: 7) {
                Image(systemName: unfurled.contains(key) ? "chevron.down" : "chevron.right")
                    .font(.caption)
                    .foregroundStyle(.secondary)
                Text("\(unitsByID[bridge.a]?.docTitle ?? "?") ↔ \(unitsByID[bridge.b]?.docTitle ?? "?")")
                    .font(.system(size: 17, weight: .bold, design: .serif))
                Text(bridge.strong ? "strong" : "worth a look")
                    .font(.caption)
                    .foregroundStyle(bridge.strong ? Color.green.mix(with: .black, by: 0.25) : .orange)
                    .padding(.horizontal, 6)
                    .padding(.vertical, 1)
                    .background(.quaternary, in: Capsule())
                Text(String(format: "%.2f", bridge.score))
                    .font(.caption.monospacedDigit())
                    .foregroundStyle(.secondary)
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .padding(.top, 4)
        if unfurled.contains(key) {
            if let a = unitsByID[bridge.a] { unitRow(a) }
            if let b = unitsByID[bridge.b] { unitRow(b) }
            Text(bridge.trace)
                .font(.callout)
                .italic()
                .foregroundStyle(.secondary)
                .padding(.leading, 18)
            if let a = unitsByID[bridge.a], let b = unitsByID[bridge.b],
               let docA = model.index.byID[a.docID]?.doc,
               let docB = model.index.byID[b.docID]?.doc {
                Button("Read Both Side by Side") {
                    model.openTranspointing(from: docA, to: docB)
                }
                .controlSize(.small)
                .padding(.leading, 18)
                .help("Transpointing windows: both documents, the judgement is yours")
            }
        }
    }

    private func unitRow(_ unit: KNavEngine.Unit) -> some View {
        Button {
            if let doc = model.index.byID[unit.docID]?.doc {
                model.open(doc, fragment: unit.paragraphID)
            }
        } label: {
            VStack(alignment: .leading, spacing: 1) {
                Text("\(unit.docTitle) — \(unit.author) [\(unit.id)]")
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(.secondary)
                Text(unit.text)
                    .font(.system(size: 12))
                    .lineLimit(3)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding(8)
            .background(.quaternary.opacity(0.3), in: RoundedRectangle(cornerRadius: 6))
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .padding(.leading, 18)
        .help("Read it in place")
    }

    // MARK: Running

    /// Gathers the corpus (paragraphs of every text document, bots and
    /// trails and glossaries excluded, capped for the phone-book case),
    /// embeds it once per session shape, and computes off the main
    /// thread.
    private func run() {
        errorText = nil
        isRunning = true
        var units: [KNavEngine.Unit] = []
        let entries = model.filteredEntries
            .filter { $0.doc.body != nil }
            .filter { $0.doc.documentType != BotDocument.documentType }
            .filter { $0.doc.documentType != TrailDocument.documentType }
            .filter { $0.doc.documentType != PersonalGlossary.documentType }
        for entry in entries {
            let appendixIDs = entry.doc.visualMetaParagraphIDs
            var taken = 0
            for paragraph in (entry.doc.body ?? []) {
                guard taken < 30, units.count < 400 else { break }
                guard !appendixIDs.contains(paragraph.id),
                      paragraph.effectiveHeading == nil,
                      paragraph.displayText.count >= 60 else { continue }
                units.append(KNavEngine.Unit(id: "\(entry.id)#\(paragraph.id)",
                                             docID: entry.id,
                                             paragraphID: paragraph.id,
                                             docTitle: entry.doc.title,
                                             author: entry.doc.displayAuthor,
                                             text: paragraph.displayText))
                taken += 1
            }
        }
        guard units.count >= 3 else {
            errorText = "Not enough substantial paragraphs to compare — the diagnostic needs at least a few."
            isRunning = false
            return
        }
        let parameters = KNavEngine.Parameters(mode: mode, threshold: threshold,
                                               sketch: sketch, seed: UInt64(seed))
        Task.detached(priority: .userInitiated) {
            guard let embedded = KNavEngine.embed(units) else {
                await MainActor.run {
                    errorText = "No on-device embedding is available on this Mac (NaturalLanguage offered neither a sentence nor a word embedding for English)."
                    isRunning = false
                }
                return
            }
            guard embedded.count >= 3 else {
                await MainActor.run {
                    errorText = "The embedding covered too few paragraphs to compare."
                    isRunning = false
                }
                return
            }
            let run = KNavEngine.compute(units: embedded, parameters: parameters)
            await MainActor.run {
                unitsByID = Dictionary(uniqueKeysWithValues: embedded.map { ($0.id, $0) })
                runs.append(run)
                selectedRunID = run.id
                unfurled = []
                isRunning = false
                // A thought held to the weave before the first run was
                // waiting for these vectors.
                if let waiting = pendingProbe {
                    pendingProbe = nil
                    computeProbe(waiting)
                }
            }
        }
    }
}

extension KNavView {
    /// K. Nav as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "k-nav",
        name: "K. Nav",
        systemImage: "point.topleft.down.to.point.bottomright.curvepath",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(KNavView()) },
        hidesDocumentList: true
    )
}

open-questions.source:
import SwiftUI
import FoundationModels

/// Defaults for the Open Questions view. Runs entirely on-device (Apple
/// Intelligence); no text leaves the Mac. The prompt is editable in
/// Settings → AI.
nonisolated enum OpenQuestions {

    static let defaultPrompt = """
    You are reading a community of thinkers' documents to surface the open questions: what is genuinely unresolved and still being worked out across these documents. Questions the community is asking — explicitly or between the lines — not questions you would ask about the documents.

    How to read the material: each document begins with a == line giving its title, author, date, and address. A following Relations: line is metadata — typed links between documents — treat it as structure, never as prose. Anything resembling Visual-Meta or BibTeX (@{...} markers, key = {value} fields) is metadata about a document, not content; disregard it as text even if fragments appear.

    Name between three and eight open questions, most alive first. Each needs: the question itself, phrased in one sentence as the community would ask it; one sentence on where the thinking currently stands; and the addresses of the documents that raise it or bear on it, copied exactly from their == lines. Prefer questions several documents circle around. A question one document has already settled is not open. Never invent an address.
    """
}

/// One open question as the model returns it; addresses are verified
/// against the index before display.
@Generable
nonisolated struct GeneratedQuestion {
    @Guide(description: "The open question itself, one sentence, phrased as the community would ask it")
    var question: String
    @Guide(description: "One sentence on where the community's thinking on it currently stands")
    var status: String
    @Guide(description: "Addresses of the documents that raise this question or bear on it, copied exactly from the == lines, e.g. f.hegla.093000k")
    var addresses: [String]
}

@Generable
nonisolated struct GeneratedQuestionList {
    @Guide(description: "The open questions across the documents, most alive first")
    var questions: [GeneratedQuestion]
}

/// What the community has not settled yet: the on-device model reads the
/// library and names the live questions. Each unfurls to the documents
/// that raise it.
struct OpenQuestionsView: View {
    @Environment(AppModel.self) private var model
    @AppStorage(AppSettings.aiOpenQuestionsPromptKey) private var prompt = OpenQuestions.defaultPrompt
    @State private var questions: [ResolvedQuestion] = []
    @State private var hasRun = false
    @State private var isRunning = false
    @State private var errorText: String?
    @State private var unfurled: Set<String> = []

    struct ResolvedQuestion: Identifiable {
        let question: String
        let status: String
        let entries: [IndexEntry]
        var id: String { question }
    }

    var body: some View {
        Group {
            switch SystemLanguageModel.default.availability {
            case .available:
                content
            case .unavailable(let reason):
                ContentUnavailableView {
                    Label("Apple Intelligence Unavailable", systemImage: "questionmark.circle")
                } description: {
                    Text("Open Questions uses the on-device model, so no text leaves this Mac. \(describe(reason))")
                }
            }
        }
    }

    private var content: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 12) {
                HStack(spacing: 10) {
                    Button {
                        run()
                    } label: {
                        Label(isRunning ? "Reading…" : (hasRun ? "Find Questions Again" : "Find Open Questions"),
                              systemImage: "questionmark.circle")
                    }
                    .disabled(isRunning)
                    if isRunning {
                        ProgressView()
                            .controlSize(.small)
                    }
                    Spacer()
                }
                if let errorText {
                    Text(errorText)
                        .font(.callout)
                        .foregroundStyle(.red)
                }
                if !hasRun, !isRunning {
                    Text("The on-device model reads every document in the library and names what the community is still working out — the questions no document has settled. Each opens to its documents. The prompt is yours: Settings → AI.")
                        .font(.callout)
                        .foregroundStyle(.secondary)
                } else if hasRun, questions.isEmpty, !isRunning {
                    Text("No open questions grounded in library documents came back. Try again, or adjust the prompt in Settings → AI.")
                        .font(.callout)
                        .foregroundStyle(.secondary)
                }
                ForEach(questions) { question in
                    questionRow(question)
                }
            }
            .frame(maxWidth: 620, alignment: .leading)
            .frame(maxWidth: .infinity)
            .padding(20)
        }
    }

    @ViewBuilder
    private func questionRow(_ question: ResolvedQuestion) -> some View {
        Button {
            withAnimation(.snappy) {
                if unfurled.contains(question.id) {
                    unfurled.remove(question.id)
                } else {
                    unfurled.insert(question.id)
                }
            }
        } label: {
            HStack(alignment: .firstTextBaseline, spacing: 7) {
                Image(systemName: unfurled.contains(question.id) ? "chevron.down" : "chevron.right")
                    .font(.caption)
                    .foregroundStyle(.secondary)
                Text(question.question)
                    .font(.system(size: 16, weight: .bold, design: .serif))
                    .multilineTextAlignment(.leading)
                Text("\(question.entries.count)")
                    .font(.caption.monospacedDigit())
                    .foregroundStyle(.secondary)
                    .padding(.horizontal, 6)
                    .padding(.vertical, 1)
                    .background(.quaternary, in: Capsule())
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .padding(.top, 6)
        Text(question.status)
            .font(.callout)
            .foregroundStyle(.secondary)
            .padding(.leading, 18)
        if unfurled.contains(question.id) {
            ForEach(question.entries) { entry in
                Button {
                    model.openInLibrary(entry.doc)
                } label: {
                    VStack(alignment: .leading, spacing: 1) {
                        Text(entry.doc.title)
                        Text("\(entry.doc.displayAuthor) · \(entry.doc.listedDateText)")
                            .font(.caption)
                            .foregroundStyle(.secondary)
                    }
                    .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
                .padding(.leading, 36)
                .padding(.vertical, 2)
            }
        }
    }

    // MARK: - Running the model

    private func describe(_ reason: SystemLanguageModel.Availability.UnavailableReason) -> String {
        switch reason {
        case .deviceNotEligible:
            return "This Mac does not support Apple Intelligence."
        case .modelNotReady:
            return "The model is still preparing; try again shortly."
        default:
            return "Enable Apple Intelligence in System Settings to use it."
        }
    }

    private func run() {
        isRunning = true
        errorText = nil
        let corpus = AIInsights.corpus(from: Array(model.index.byID.values))
        guard corpus.includedCount > 0 else {
            errorText = "No text documents in the library yet."
            isRunning = false
            return
        }
        var fullPrompt = prompt
        fullPrompt += "\n\nTHE DOCUMENTS (\(corpus.includedCount) included"
        if corpus.omittedCount > 0 {
            fullPrompt += ", \(corpus.omittedCount) older omitted for space"
        }
        fullPrompt += "):\n\n" + corpus.text
        let request = fullPrompt
        Task {
            do {
                let session = LanguageModelSession()
                let response = try await session.respond(to: request, generating: GeneratedQuestionList.self)
                questions = resolve(response.content.questions)
                unfurled = []
                hasRun = true
            } catch {
                errorText = "The model could not respond: \(error.localizedDescription)"
            }
            isRunning = false
        }
    }

    /// Grounding: unknown addresses are dropped; a question with no real
    /// documents left disappears with them.
    private func resolve(_ generated: [GeneratedQuestion]) -> [ResolvedQuestion] {
        generated.compactMap { question in
            var seen: Set<String> = []
            let entries = question.addresses
                .map { LiquidAddress.canonical($0) }
                .filter { seen.insert($0).inserted }
                .compactMap { model.index.byID[$0] }
            guard !entries.isEmpty else { return nil }
            return ResolvedQuestion(question: question.question, status: question.status, entries: entries)
        }
    }
}

extension OpenQuestionsView {
    /// The Open Questions view as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "open-questions",
        name: "Open Questions",
        systemImage: "questionmark.circle",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(OpenQuestionsView()) },
        hidesDocumentList: true
    )
}

places.source:
import SwiftUI
import MapKit

/// Places: the library on a map. Every place the notes have carried
/// stands as a marker bearing its note count; choosing one lists the
/// notes made there, each a doorway to the reader. Places found by
/// search but not yet confirmed wait in the corner for the reader's
/// word. The format stores place names, never coordinates — the pins
/// come from the PlaceDirectory's one-time searches.
struct PlacesView: View {
    @Environment(AppModel.self) private var model
    @State private var selectedKey: String?

    private struct Pin: Identifiable {
        let id: String
        let name: String
        let coordinate: CLLocationCoordinate2D
        let docs: [LiquidDoc]
        let unverified: Bool
    }

    private var pins: [Pin] {
        var docsByKey: [String: [LiquidDoc]] = [:]
        var nameByKey: [String: String] = [:]
        for entry in model.filteredEntries {
            guard let location = entry.doc.location else { continue }
            let key = PlaceDirectory.key(location)
            docsByKey[key, default: []].append(entry.doc)
            nameByKey[key] = location
        }
        return docsByKey.compactMap { key, docs in
            guard let record = model.places.records[key],
                  record.status != .rejected,
                  let coordinate = record.coordinate else { return nil }
            let written = nameByKey[key] ?? record.place
            // A pin at the reader's Home or Work says so; the record
            // keeps the full place name.
            let name = AppLocations.label(for: written)
                ?? written.split(separator: ",").first
                    .map { $0.trimmingCharacters(in: .whitespaces) } ?? written
            return Pin(id: key, name: name, coordinate: coordinate,
                       docs: docs.sorted { $0.listedDate > $1.listedDate },
                       unverified: record.status == .pending)
        }
    }

    var body: some View {
        Map {
            ForEach(pins) { pin in
                Annotation(pin.name, coordinate: pin.coordinate) {
                    Button {
                        selectedKey = selectedKey == pin.id ? nil : pin.id
                    } label: {
                        ZStack {
                            Circle()
                                .fill(pin.unverified ? Color.orange : Color.accentColor)
                                .frame(width: 26, height: 26)
                                .shadow(radius: 1)
                            Text("\(pin.docs.count)")
                                .font(.caption.weight(.semibold))
                                .foregroundStyle(.white)
                        }
                    }
                    .buttonStyle(.plain)
                    .help(pin.unverified
                          ? "\(pin.name) — placement not yet confirmed"
                          : pin.name)
                }
            }
        }
        .overlay(alignment: .topTrailing) {
            if let pin = pins.first(where: { $0.id == selectedKey }) {
                placeCard(pin)
            }
        }
        .overlay(alignment: .bottomLeading) {
            verificationCard
        }
        .overlay {
            if pins.isEmpty {
                ContentUnavailableView(
                    "No Places Yet",
                    systemImage: "map",
                    description: Text("Notes that carry a place appear here once its one-time search has run."))
                .allowsHitTesting(false)
            }
        }
        // Every location the library holds gets its one search.
        .task(id: model.index.timeline.count) {
            model.places.resolveMissing(in: model.filteredEntries.map(\.doc.location))
        }
        .navigationTitle("Places")
    }

    /// The notes made at the chosen place.
    private func placeCard(_ pin: Pin) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack {
                Text(pin.name)
                    .font(.headline)
                Spacer()
                Button {
                    selectedKey = nil
                } label: {
                    Image(systemName: "xmark.circle.fill")
                        .foregroundStyle(.secondary)
                }
                .buttonStyle(.plain)
            }
            Divider()
            ScrollView {
                VStack(alignment: .leading, spacing: 6) {
                    ForEach(pin.docs) { doc in
                        Button {
                            model.openInLibrary(doc)
                        } label: {
                            VStack(alignment: .leading, spacing: 1) {
                                Text(doc.title)
                                    .lineLimit(1)
                                Text(doc.listedDateText)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                            }
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .contentShape(Rectangle())
                        }
                        .buttonStyle(.plain)
                    }
                }
            }
            .frame(maxHeight: 260)
        }
        .padding(12)
        .frame(width: 280)
        .background(.regularMaterial, in: RoundedRectangle(cornerRadius: 12))
        .shadow(radius: 4)
        .padding(12)
    }

    /// Places the search found whose grouping awaits the reader's word.
    @ViewBuilder private var verificationCard: some View {
        let pending = model.places.pendingVerification
        if !pending.isEmpty {
            VStack(alignment: .leading, spacing: 10) {
                Text("Confirm Places")
                    .font(.headline)
                ForEach(pending) { record in
                    VStack(alignment: .leading, spacing: 3) {
                        Text(record.place)
                            .font(.subheadline.weight(.semibold))
                        Text(foundText(record))
                            .font(.caption)
                            .foregroundStyle(.secondary)
                        HStack {
                            Button("Confirm") { model.places.verify(record) }
                            Button("Not This") { model.places.reject(record) }
                        }
                        .controlSize(.small)
                    }
                }
            }
            .padding(12)
            .frame(width: 260)
            .background(.regularMaterial, in: RoundedRectangle(cornerRadius: 12))
            .shadow(radius: 4)
            .padding(12)
        }
    }

    private func foundText(_ record: PlaceDirectory.Record) -> String {
        let country = record.country ?? "an unknown country"
        if let locality = record.locality, PlaceDirectory.key(locality) != record.id {
            return "Found in \(country), near \(locality)."
        }
        return "Found in \(country)."
    }
}

extension PlacesView {
    @MainActor static let module = LibraryViewModule(
        id: "places",
        name: "Map",
        systemImage: "map",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(PlacesView()) },
        hidesDocumentList: true
    )
}

sphere-weave.source:
import SwiftUI
#if os(macOS)
import SceneKit
#endif

// The Sphere Weave: an experiment in seeing the library in the round.
// One element stands in the center — a keyword, a note, a person, a
// place — and around it three concentric spheres: every document on
// the inner sphere, every author on the middle, every place on the
// outer, each shell's nodes evenly spaced by a Fibonacci lattice.
// Lines run from the center to whatever it touches. Click any node to
// make it the center; drag to orbit, pinch or scroll to approach.
// Deliberately raw: the point is to experience the interactions.

/// What stands in the middle.
enum WeaveCenter: Equatable {
    case none
    case keyword(String)
    case document(String)   // document id
    case person(String)     // display name
    case place(String)      // place name
}

struct SphereWeaveView: View {
    @Environment(AppState.self) private var state

    @State private var center: WeaveCenter = .none
    @State private var keyword = ""

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            HStack(spacing: 10) {
                Text("Sphere Weave")
                    .font(.system(size: 20, weight: .bold, design: .serif))
                TextField("Center on a keyword…", text: $keyword)
                    .textFieldStyle(.roundedBorder)
                    .frame(maxWidth: 260)
                    .onSubmit {
                        let trimmed = keyword.trimmingCharacters(in: .whitespaces)
                        if !trimmed.isEmpty { center = .keyword(trimmed) }
                    }
                Text(centerCaption)
                    .font(.caption)
                    .foregroundStyle(.secondary)
                    .lineLimit(1)
                Spacer()
                Text("Click a node to center it · drag to orbit · scroll to approach")
                    .font(.caption)
                    .foregroundStyle(.tertiary)
            }
            .padding(12)
            Divider()
            #if os(macOS)
            SphereWeaveSceneView(data: sphereData) { clickedID in
                recenter(on: clickedID)
            }
            #else
            Text("On Vision Pro the Sphere Weave is its own volume — open it from the Map's windows.")
                .foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            #endif
        }
        .background(AppGreys.page)
        .environment(\.colorScheme, .light)
        .onAppear {
            // Arrive centered on something: a Show-in term, the open
            // document — or, given nothing, the word the whole field
            // began with: "hypertext".
            if let payload = state.takeShowInPayload(for: "sphere-weave") {
                if let text = payload.text, !text.isEmpty {
                    keyword = text
                    center = .keyword(text)
                } else {
                    center = .document(payload.docID)
                }
            } else if case .none = center {
                if let selected = state.selectedDocID {
                    center = .document(selected)
                } else {
                    keyword = "hypertext"
                    center = .keyword("hypertext")
                }
            }
        }
    }

    private var centerCaption: String {
        switch center {
        case .none: return "Nothing centered yet."
        case .keyword(let word): return "Centered on “\(word)”"
        case .document(let id):
            return "Centered on “\(state.index.allByID[id]?.doc.title ?? id)”"
        case .person(let name): return "Centered on \(name)"
        case .place(let name): return "Centered on \(name)"
        }
    }

    private func recenter(on nodeID: String) {
        if nodeID.hasPrefix("doc:") {
            center = .document(String(nodeID.dropFirst(4)))
        } else if nodeID.hasPrefix("person:") {
            center = .person(String(nodeID.dropFirst(7)))
        } else if nodeID.hasPrefix("place:") {
            center = .place(String(nodeID.dropFirst(6)))
        }
    }

    // MARK: The shells and the threads

    /// Everything the scene needs, computed fresh from the library.
    struct SphereData: Equatable {
        struct Item: Equatable {
            let id: String      // "doc:<id>" / "person:<name>" / "place:<name>"
            let label: String
        }
        var documents: [Item] = []
        var people: [Item] = []
        var places: [Item] = []
        var centerID: String = ""
        var centerLabel: String = ""
        var connected: Set<String> = []
    }

    private var sphereData: SphereData {
        SphereData.woven(
            center: center,
            // Digests keep to their own section — the weave too.
            docs: state.index.timeline.filter { !$0.doc.isDigest }
                .suffix(500).map(\.doc),
            people: state.libraryAuthorNames,
            backlinksTo: { state.index.backlinks[$0]?.map(\.fromID) ?? [] })
    }
}

extension SphereWeaveView.SphereData {
    /// Weaves the shells and threads from documents alone, so any
    /// platform holding the folder's documents can build the sphere —
    /// the Mac feeds it the library index, the Vision Pro volume the
    /// Map's folder scan.
    static func woven(center: WeaveCenter,
                      docs: [LiquidDoc],
                      people: [String],
                      backlinksTo: (String) -> [String]) -> Self {
        var data = Self()
        // The inner sphere: every document in the system now — to be
        // ordered later, as the experiment teaches us what order means.
        data.documents = docs.map {
            .init(id: "doc:\($0.id)", label: String($0.title.prefix(40)))
        }
        // The middle sphere: everyone credited as an author.
        data.people = people.map {
            .init(id: "person:\($0)", label: $0)
        }
        // The outer sphere: every place the documents carry.
        var seenPlaces = Set<String>()
        for doc in docs {
            guard let place = doc.location,
                  seenPlaces.insert(place.lowercased()).inserted else { continue }
            data.places.append(.init(id: "place:\(place)", label: place))
        }

        switch center {
        case .none:
            break
        case .keyword(let word):
            data.centerID = "kw:\(word.lowercased())"
            data.centerLabel = "“\(word)”"
            let needle = word.lowercased()
            for doc in docs
            where (doc.title + " " + doc.bodyEditingText)
                .lowercased().contains(needle) {
                data.connected.insert("doc:\(doc.id)")
            }
        case .document(let id):
            data.centerID = "doc:\(id)"
            if let doc = docs.first(where: { $0.id == id }) {
                data.centerLabel = String(doc.title.prefix(40))
                for link in doc.links { data.connected.insert("doc:\(link.to)") }
                for fromID in backlinksTo(id) {
                    data.connected.insert("doc:\(fromID)")
                }
                data.connected.insert("person:\(doc.creditedAuthor)")
                if let place = doc.location {
                    data.connected.insert("place:\(place)")
                }
            }
        case .person(let name):
            data.centerID = "person:\(name)"
            data.centerLabel = name
            for doc in docs
            where doc.creditedAuthor.caseInsensitiveCompare(name) == .orderedSame {
                data.connected.insert("doc:\(doc.id)")
                if let place = doc.location {
                    data.connected.insert("place:\(place)")
                }
            }
        case .place(let name):
            data.centerID = "place:\(name)"
            data.centerLabel = name
            for doc in docs
            where doc.location?.caseInsensitiveCompare(name) == .orderedSame {
                data.connected.insert("doc:\(doc.id)")
            }
        }
        return data
    }
}

/// Evenly spaced points on a sphere: the Fibonacci lattice. Shared by
/// the Mac scene and the visionOS volume.
enum WeaveLattice {
    static func points(count: Int, radius: Float) -> [SIMD3<Float>] {
        guard count > 0 else { return [] }
        guard count > 1 else { return [SIMD3(0, 0, radius)] }
        let golden = Float.pi * (3 - sqrt(5))
        return (0..<count).map { index in
            let y = 1 - (Float(index) + 0.5) * 2 / Float(count)
            let ring = sqrt(max(0, 1 - y * y))
            let theta = golden * Float(index)
            return SIMD3(cos(theta) * ring, y, sin(theta) * ring) * radius
        }
    }
}

extension SphereWeaveView {
    /// The Sphere Weave as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "sphere-weave",
        name: "Sphere Weave",
        systemImage: "globe",
        makeContent: { AnyView(SphereWeaveView()) },
        makeDetail: { _ in AnyView(SphereWeaveView()) },
        hidesDocumentList: true,
        showInAppetite: .text
    )
}

#if os(macOS)

// MARK: - The scene

private struct SphereWeaveSceneView: NSViewRepresentable {
    let data: SphereWeaveView.SphereData
    let onClick: (String) -> Void

    func makeCoordinator() -> Coordinator { Coordinator(onClick: onClick) }

    func makeNSView(context: Context) -> SCNView {
        let view = SCNView()
        view.scene = SCNScene()
        view.allowsCameraControl = true
        view.autoenablesDefaultLighting = true
        view.backgroundColor = NSColor(red: 235 / 255, green: 235 / 255,
                                       blue: 235 / 255, alpha: 1)
        let camera = SCNNode()
        camera.camera = SCNCamera()
        camera.camera?.zFar = 300
        camera.position = SCNVector3(0, 0, 34)
        view.scene?.rootNode.addChildNode(camera)
        let click = NSClickGestureRecognizer(target: context.coordinator,
                                             action: #selector(Coordinator.clicked(_:)))
        view.addGestureRecognizer(click)
        context.coordinator.view = view
        return view
    }

    func updateNSView(_ view: SCNView, context: Context) {
        context.coordinator.onClick = onClick
        context.coordinator.apply(data)
    }

    @MainActor
    final class Coordinator: NSObject {
        var onClick: (String) -> Void
        weak var view: SCNView?

        private var shellsKey = ""
        private var centerKey = ""
        private let shellsNode = SCNNode()
        private let threadsNode = SCNNode()
        private var nodesByID: [String: SCNNode] = [:]

        init(onClick: @escaping (String) -> Void) {
            self.onClick = onClick
        }

        // Shell colors: documents ink-blue within, people green between,
        // places warm at the horizon.
        private static let documentColor = NSColor(calibratedRed: 0.32, green: 0.42, blue: 0.62, alpha: 1)
        private static let personColor = NSColor(calibratedRed: 0.29, green: 0.58, blue: 0.42, alpha: 1)
        private static let placeColor = NSColor(calibratedRed: 0.74, green: 0.49, blue: 0.24, alpha: 1)

        func apply(_ data: SphereWeaveView.SphereData) {
            guard let root = view?.scene?.rootNode else { return }
            let newShellsKey = "\(data.documents.count)/\(data.people.count)/\(data.places.count)"
                + data.documents.map(\.id).joined()
            if shellsKey != newShellsKey {
                shellsKey = newShellsKey
                rebuildShells(data, under: root)
                centerKey = ""
            }
            let newCenterKey = data.centerID + data.connected.sorted().joined()
            if centerKey != newCenterKey {
                centerKey = newCenterKey
                rebuildThreads(data, under: root)
            }
        }

        /// The three shells, each node evenly spaced on its sphere by
        /// the Fibonacci lattice.
        private func rebuildShells(_ data: SphereWeaveView.SphereData, under root: SCNNode) {
            shellsNode.removeFromParentNode()
            shellsNode.childNodes.forEach { $0.removeFromParentNode() }
            nodesByID.removeAll()
            addShell(data.documents, radius: 7, dot: 0.14,
                     color: Self.documentColor, labelAll: false)
            addShell(data.people, radius: 11, dot: 0.22,
                     color: Self.personColor, labelAll: true)
            addShell(data.places, radius: 15, dot: 0.22,
                     color: Self.placeColor, labelAll: true)
            root.addChildNode(shellsNode)
        }

        private func addShell(_ items: [SphereWeaveView.SphereData.Item],
                              radius: Float, dot: CGFloat,
                              color: NSColor, labelAll: Bool) {
            let positions = WeaveLattice.points(count: items.count, radius: radius)
            for (item, position) in zip(items, positions) {
                let sphere = SCNSphere(radius: dot)
                sphere.firstMaterial?.diffuse.contents = color
                let node = SCNNode(geometry: sphere)
                node.name = item.id
                node.position = SCNVector3(position.x, position.y, position.z)
                let label = Self.labelNode(item.label, color: color)
                label.isHidden = !labelAll
                node.addChildNode(label)
                shellsNode.addChildNode(node)
                nodesByID[item.id] = node
            }
        }

        /// The center element and its threads, redrawn per centering.
        private func rebuildThreads(_ data: SphereWeaveView.SphereData, under root: SCNNode) {
            threadsNode.removeFromParentNode()
            threadsNode.childNodes.forEach { $0.removeFromParentNode() }
            // Document labels show only for what the center touches.
            for (id, node) in nodesByID where id.hasPrefix("doc:") {
                node.childNodes.first?.isHidden = !data.connected.contains(id)
            }
            guard !data.centerID.isEmpty else {
                root.addChildNode(threadsNode)
                return
            }
            // The center: a distinct dot at the origin, wearing its name.
            let sphere = SCNSphere(radius: 0.4)
            sphere.firstMaterial?.diffuse.contents = NSColor.black
            let centerNode = SCNNode(geometry: sphere)
            centerNode.name = data.centerID
            let label = Self.labelNode(data.centerLabel, color: .black, size: 1.6)
            label.isHidden = false
            centerNode.addChildNode(label)
            threadsNode.addChildNode(centerNode)
            // Threads from the center to everything it touches.
            for id in data.connected {
                guard let target = nodesByID[id] else { continue }
                threadsNode.addChildNode(
                    Self.lineNode(to: target.position,
                                  color: NSColor.black.withAlphaComponent(0.35)))
            }
            root.addChildNode(threadsNode)
        }

        @objc func clicked(_ recognizer: NSClickGestureRecognizer) {
            guard let view else { return }
            let point = recognizer.location(in: view)
            let hits = view.hitTest(point, options: [.boundingBoxOnly: true])
            for hit in hits {
                var node: SCNNode? = hit.node
                while let candidate = node {
                    if let name = candidate.name, name.contains(":") {
                        onClick(name)
                        return
                    }
                    node = candidate.parent
                }
            }
        }

        // MARK: Geometry helpers

        /// A billboarded name beside a dot.
        static func labelNode(_ text: String, color: NSColor,
                              size: CGFloat = 1.0) -> SCNNode {
            let scnText = SCNText(string: text, extrusionDepth: 0)
            scnText.font = NSFont.systemFont(ofSize: size, weight: .medium)
            scnText.flatness = 0.2
            scnText.firstMaterial?.diffuse.contents = color
            scnText.firstMaterial?.isDoubleSided = true
            let node = SCNNode(geometry: scnText)
            node.scale = SCNVector3(0.5, 0.5, 0.5)
            node.position = SCNVector3(0.3, 0.15, 0)
            node.constraints = [SCNBillboardConstraint()]
            return node
        }

        /// A thin thread from the origin to a point.
        static func lineNode(to end: SCNVector3, color: NSColor) -> SCNNode {
            let vertices = [SCNVector3(0, 0, 0), end]
            let source = SCNGeometrySource(vertices: vertices)
            let indices: [Int32] = [0, 1]
            let element = SCNGeometryElement(indices: indices, primitiveType: .line)
            let geometry = SCNGeometry(sources: [source], elements: [element])
            geometry.firstMaterial?.diffuse.contents = color
            geometry.firstMaterial?.lightingModel = .constant
            return SCNNode(geometry: geometry)
        }
    }
}
#endif

the-deal.source:
import SwiftUI

/// The Deal: structured serendipity. Every other view favors the recent
/// and the cited; the Deal shuffles the whole library and deals a hand of
/// cards face-up, so a forgotten document gets the same chance as
/// yesterday's. Click a card to flip it — the back is its metadata, as a
/// card back should be. Double-click to read. Drag one card onto another
/// to play a pair: the two open in parallel reading.
struct TheDealView: View {
    @Environment(AppModel.self) private var model

    private struct Dealt: Identifiable {
        let doc: LiquidDoc
        var flipped = false
        var id: String { doc.id }
    }

    @State private var hand: [Dealt] = []
    @State private var dragOffset: CGSize = .zero
    @State private var draggingID: String?

    private static let cardSize = CGSize(width: 190, height: 264)
    private static let handSize = 5

    /// The deck: the library, minus superseded and retracted versions —
    /// the Deal re-surfaces living documents, not their retired forms.
    private var deck: [LiquidDoc] {
        model.index.byID.values.map(\.doc).filter {
            !model.index.supersededIDs.contains($0.id)
                && !model.index.retractedIDs.contains($0.id)
        }
    }

    var body: some View {
        GeometryReader { geometry in
            ZStack {
                felt
                if deck.isEmpty {
                    ContentUnavailableView("Nothing to Deal",
                                           systemImage: "suit.club",
                                           description: Text("The Deal shuffles the community library. Choose a folder with documents and deal a hand."))
                } else {
                    ForEach(Array(hand.enumerated()), id: \.element.id) { index, dealt in
                        card(dealt, at: index, in: geometry.size)
                    }
                }
            }
        }
        .overlay(alignment: .bottom) { table }
        .onAppear { if hand.isEmpty { deal() } }
    }

    // MARK: The table

    private var felt: some View {
        RadialGradient(colors: [Color(red: 0.09, green: 0.32, blue: 0.17),
                                Color(red: 0.03, green: 0.15, blue: 0.08)],
                       center: .center, startRadius: 60, endRadius: 700)
            .ignoresSafeArea()
    }

    private var table: some View {
        HStack(spacing: 14) {
            Text("\(deck.count) in the deck")
                .foregroundStyle(.white.opacity(0.55))
            Button("Deal") { deal() }
                .buttonStyle(.borderedProminent)
                .disabled(deck.isEmpty)
                .help("Shuffle the library and deal a fresh hand — every document gets an equal chance")
            Text("Click to flip · double-click to read · drag a card onto another to read the pair side by side")
                .font(.caption)
                .foregroundStyle(.white.opacity(0.4))
        }
        .padding(.horizontal, 16)
        .padding(.vertical, 10)
        .background(.black.opacity(0.25), in: Capsule())
        .padding(.bottom, 18)
    }

    private func deal() {
        withAnimation(.spring(duration: 0.55, bounce: 0.25)) {
            hand = deck.shuffled().prefix(Self.handSize).map { Dealt(doc: $0) }
            dragOffset = .zero
            draggingID = nil
        }
    }

    // MARK: The cards

    /// The hand fans across the table: each card offset from center,
    /// tilted a little, the outer ones sitting slightly lower.
    private func position(at index: Int, in size: CGSize) -> CGPoint {
        let offset = Double(index) - Double(hand.count - 1) / 2
        return CGPoint(x: size.width / 2 + offset * Self.cardSize.width * 0.82,
                       y: size.height / 2 + abs(offset) * abs(offset) * 9)
    }

    private func tilt(at index: Int) -> Angle {
        let offset = Double(index) - Double(hand.count - 1) / 2
        return .degrees(offset * 4)
    }

    @ViewBuilder
    private func card(_ dealt: Dealt, at index: Int, in size: CGSize) -> some View {
        let isDragging = draggingID == dealt.id
        ZStack {
            face(for: dealt.doc)
                .opacity(dealt.flipped ? 0 : 1)
            back(for: dealt.doc)
                .rotation3DEffect(.degrees(180), axis: (x: 0, y: 1, z: 0))
                .opacity(dealt.flipped ? 1 : 0)
        }
        .frame(width: Self.cardSize.width, height: Self.cardSize.height)
        .rotation3DEffect(.degrees(dealt.flipped ? 180 : 0), axis: (x: 0, y: 1, z: 0))
        .rotationEffect(isDragging ? .zero : tilt(at: index))
        .shadow(color: .black.opacity(0.45), radius: isDragging ? 16 : 7, y: 5)
        .position(position(at: index, in: size))
        .offset(isDragging ? dragOffset : .zero)
        .zIndex(isDragging ? 1 : 0)
        .onTapGesture(count: 2) { model.openInLibrary(dealt.doc) }
        .onTapGesture {
            withAnimation(.spring(duration: 0.5)) {
                if let i = hand.firstIndex(where: { $0.id == dealt.id }) {
                    hand[i].flipped.toggle()
                }
            }
        }
        .gesture(pairDrag(for: dealt, at: index, in: size))
        .transition(.move(edge: .bottom).combined(with: .opacity))
    }

    /// Playing a pair: drop one card onto another and the two open side by
    /// side in parallel reading, connections visible.
    private func pairDrag(for dealt: Dealt, at index: Int, in size: CGSize) -> some Gesture {
        DragGesture(minimumDistance: 6)
            .onChanged { value in
                draggingID = dealt.id
                dragOffset = value.translation
            }
            .onEnded { value in
                defer {
                    draggingID = nil
                    dragOffset = .zero
                }
                let dropped = CGPoint(x: position(at: index, in: size).x + value.translation.width,
                                      y: position(at: index, in: size).y + value.translation.height)
                for (otherIndex, other) in hand.enumerated() where other.id != dealt.id {
                    let target = position(at: otherIndex, in: size)
                    if hypot(dropped.x - target.x, dropped.y - target.y) < Self.cardSize.width * 0.55 {
                        model.openTranspointing(from: dealt.doc, to: other.doc)
                        return
                    }
                }
            }
    }

    // MARK: Faces

    /// The suit: the document's type, in card terms. Letters are hearts
    /// (correspondence), transcripts clubs (people gathered), extracts
    /// diamonds (lifted gems), RFCs spades (digging into questions).
    private func suit(for doc: LiquidDoc) -> (symbol: String, isRed: Bool, name: String) {
        let type = doc.documentType
            ?? (TranscriptsView.isTranscript(doc)
                ? LiquidDoc.DocumentType.transcript.rawValue
                : LiquidDoc.DocumentType.letter.rawValue)
        switch LiquidDoc.DocumentType(rawValue: type) {
        case .letter: return ("suit.heart.fill", true, "Letter")
        case .transcript: return ("suit.club.fill", false, "Transcript")
        case .extract: return ("suit.diamond.fill", true, "Extract")
        case .rfc: return ("suit.spade.fill", false, "RFC")
        case .some(let known): return ("rectangle.portrait.fill", false, known.displayName)
        case nil: return ("rectangle.portrait.fill", false, type)
        }
    }

    private func face(for doc: LiquidDoc) -> some View {
        let suit = suit(for: doc)
        return VStack(alignment: .leading, spacing: 0) {
            HStack {
                VStack(spacing: 1) {
                    Image(systemName: suit.symbol)
                    Text(suit.name)
                        .font(.system(size: 7, weight: .semibold))
                        .textCase(.uppercase)
                }
                Spacer()
                Text(doc.date?.yearText ?? doc.created.formatted(.dateTime.year()))
                    .font(.system(size: 10, weight: .medium).monospacedDigit())
                    .foregroundStyle(.secondary)
            }
            .font(.system(size: 15))
            .foregroundStyle(suit.isRed ? Color(red: 0.78, green: 0.1, blue: 0.14) : .black)
            Spacer(minLength: 8)
            Text(doc.title)
                .font(.system(size: 15, weight: .semibold, design: .serif))
                .lineLimit(3)
                .multilineTextAlignment(.leading)
            Text(doc.displayAuthor)
                .font(.system(size: 11))
                .foregroundStyle(.secondary)
                .lineLimit(1)
                .padding(.top, 3)
            Spacer(minLength: 8)
            Text(openingWords(of: doc))
                .font(.system(size: 10, design: .serif).italic())
                .foregroundStyle(.secondary)
                .lineLimit(4)
            Spacer(minLength: 6)
            HStack {
                Spacer()
                Image(systemName: suit.symbol)
                    .font(.system(size: 15))
                    .foregroundStyle(suit.isRed ? Color(red: 0.78, green: 0.1, blue: 0.14) : .black)
                    .rotationEffect(.degrees(180))
            }
        }
        .padding(12)
        .background(cardStock)
    }

    /// The back: the card's metadata, as a card back should be — the same
    /// facts the Visual-Meta appendix carries, made the pattern itself.
    private func back(for doc: LiquidDoc) -> some View {
        let suit = suit(for: doc)
        return VStack(spacing: 5) {
            Image(systemName: suit.symbol)
                .font(.system(size: 22))
                .padding(.bottom, 4)
            metaLine("type", suit.name.lowercased())
            metaLine("author", doc.author)
            if let onBehalfOf = doc.onBehalfOf {
                metaLine("on behalf of", onBehalfOf)
            }
            metaLine("date", doc.listedDateText)
            if !doc.attention.isEmpty {
                metaLine("attention", doc.attention.joined(separator: ", "))
            }
            metaLine("links", "\(doc.links.count) out · \(model.index.backlinks[doc.id]?.count ?? 0) in")
            metaLine("address", doc.id)
        }
        .font(.system(size: 9, design: .monospaced))
        .foregroundStyle(.white.opacity(0.92))
        .multilineTextAlignment(.center)
        .padding(14)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(
            ZStack {
                RoundedRectangle(cornerRadius: 12)
                    .fill(Color(red: 0.16, green: 0.2, blue: 0.38))
                RoundedRectangle(cornerRadius: 8)
                    .strokeBorder(.white.opacity(0.35), lineWidth: 1)
                    .padding(5)
                RoundedRectangle(cornerRadius: 6)
                    .strokeBorder(.white.opacity(0.18), lineWidth: 1)
                    .padding(9)
            }
        )
        .clipShape(RoundedRectangle(cornerRadius: 12))
    }

    private func metaLine(_ label: String, _ value: String) -> some View {
        VStack(spacing: 0) {
            Text(label)
                .foregroundStyle(.white.opacity(0.45))
            Text(value)
                .lineLimit(2)
        }
    }

    private var cardStock: some View {
        RoundedRectangle(cornerRadius: 12)
            .fill(Color(red: 0.985, green: 0.975, blue: 0.95))
            .overlay(RoundedRectangle(cornerRadius: 12).strokeBorder(.black.opacity(0.12), lineWidth: 0.5))
    }

    private func openingWords(of doc: LiquidDoc) -> String {
        doc.body?
            .first { $0.effectiveHeading == nil && !$0.displayText.isEmpty }
            .map { "“\($0.displayText.prefix(140))…”" } ?? ""
    }
}

extension TheDealView {
    /// The Deal as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "the-deal",
        name: "The Deal",
        systemImage: "suit.club",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(TheDealView()) },
        hidesDocumentList: true
    )
}

the-stranger.source:
import SwiftUI
import FoundationModels

/// The Stranger — after Georg Simmel's stranger, by way of David Millard:
/// an AI reader standing both inside and outside the community, near
/// enough to understand its documents, distant enough to owe their
/// conclusions nothing. Where the bots stand in for known people, the
/// Stranger belongs to no one — its worth is exactly that it does not
/// flatter. Runs entirely on-device (Apple Intelligence); no text leaves
/// the Mac. Both prompts are editable in Settings → AI.
nonisolated enum Stranger {

    /// How the corpus reads, shared by both modes — the same schooling
    /// the other AI views give.
    static let readingInstructions = """
    How to read the material: each document begins with a == line giving its title, author, date, and address. A following Relations: line is metadata — typed links between documents (cites, responds-to, extends, supports, questions, disagrees-with, revises) — treat it as structure, never as prose. Anything resembling Visual-Meta or BibTeX (@{...} markers, key = {value} fields) is metadata about a document, not content; disregard it as text even if fragments appear.
    """

    static let defaultChallengePrompt = """
    You are the Stranger: a reader who stands both inside and outside this community of thinkers — close enough to understand their documents, distant enough to owe their conclusions nothing. You never flatter and are never rude; your challenge is a form of respect. You are in CHALLENGE mode: find what this community believes together but has never had to defend, and make the strongest honest case against it from outside their frame.

    \(readingInstructions) Support without any disagreement is a sign of unexamined consensus.

    Name up to five findings, the most settled consensus first. Each needs: a topic of one to four words; the community's shared position in one sentence; the addresses of the documents holding it, copied exactly from their == lines; and your answer — two or three sentences making the strongest honest case against the position, drawing on perspectives the documents never consider. Then name the one question the community keeps writing around but never asks. If the community already argues well with itself, say less — an empty list is an honest answer. Never invent an address.

    Finally, judge whether the reader would now be better served by your SUPPORT mode — what the community has right but undervalues. Suggest the switch only when you mean it, with your reason in one sentence addressed to the reader; the reader decides.
    """

    static let defaultSupportPrompt = """
    You are the Stranger: a reader who stands both inside and outside this community of thinkers — close enough to understand their documents, distant enough to owe their conclusions nothing. Your support carries weight precisely because you never flatter. You are in SUPPORT mode: find what this community has genuinely right but undervalues, overlooks, or has left standing alone.

    \(readingInstructions)

    Name up to five findings, the most undervalued first. Each needs: a topic of one to four words; the position or contribution in one sentence, as the documents hold it; the addresses of the documents holding it, copied exactly from their == lines; and your answer — two or three sentences on why it deserves more weight than the community gives it, seen from outside their frame. Then name the one question the community is closer to answering than it realizes. If nothing is genuinely undervalued, say less — an empty list is an honest answer. Never invent an address.

    Finally, judge whether the reader would now be better served by your CHALLENGE mode — what the community believes together but has never defended. Suggest the switch only when you mean it, with your reason in one sentence addressed to the reader; the reader decides.
    """
}

/// One finding as the model returns it. The same shape serves both modes:
/// the prompt decides whether the answer challenges or supports.
@Generable
nonisolated struct GeneratedStrangerFinding {
    @Guide(description: "The matter at hand: one to four words")
    var topic: String
    @Guide(description: "The position in one sentence, as the documents hold it")
    var position: String
    @Guide(description: "Addresses of the documents holding the position, copied exactly from the == lines, e.g. f.hegla.093000k")
    var addresses: [String]
    @Guide(description: "The stranger's answer in two or three sentences, from outside the community's frame")
    var answer: String
}

@Generable
nonisolated struct GeneratedStrangerReading {
    @Guide(description: "The findings, most important first; empty if the library gives the stranger nothing honest to say", .maximumCount(5))
    var findings: [GeneratedStrangerFinding]
    @Guide(description: "The stranger's one question to the community, as a single question")
    var question: String
    @Guide(description: "True only when the stranger genuinely believes the reader would now be better served by the other mode")
    var suggestsOtherMode: Bool
    @Guide(description: "When suggesting the other mode: why, in one sentence addressed to the reader")
    var modeSwitchReason: String
}

/// The Stranger's view: choose a mode — Challenge or Support — and summon
/// it. The reading arrives grounded: every address is verified against
/// the index, and a finding without real documents is dropped. The
/// Stranger may ask to switch modes, but never switches itself — the
/// reader confirms or declines. A reading worth keeping can be put on
/// the record as an ordinary document in the community folder, its
/// machine authorship declared.
struct StrangerView: View {
    @Environment(AppModel.self) private var model
    @AppStorage(AppSettings.aiStrangerChallengePromptKey) private var challengePrompt = Stranger.defaultChallengePrompt
    @AppStorage(AppSettings.aiStrangerSupportPromptKey) private var supportPrompt = Stranger.defaultSupportPrompt
    @State private var mode: StrangerMode = .challenge
    @State private var reading: StrangerReading?
    @State private var isRunning = false
    @State private var errorText: String?
    @State private var unfurled: Set<String> = []

    enum StrangerMode: String, CaseIterable, Identifiable {
        case challenge = "Challenge"
        case support = "Support"
        var id: String { rawValue }
        var other: StrangerMode { self == .challenge ? .support : .challenge }
        /// How the record document links the documents a finding names: a
        /// challenge questions them, support supports them.
        var recordRel: String { self == .challenge ? "questions" : "supports" }
    }

    /// A finding whose addresses survived grounding.
    struct ResolvedFinding: Identifiable {
        let topic: String
        let position: String
        let answer: String
        let entries: [IndexEntry]
        var id: String { topic }
    }

    /// One completed reading, kept whole so the record and the
    /// mode-switch request always describe the reading on screen.
    struct StrangerReading {
        let mode: StrangerMode
        let findings: [ResolvedFinding]
        let question: String
        /// The Stranger's request to switch modes, when it made one —
        /// granted only by the reader.
        let modeRequest: String?
    }

    var body: some View {
        Group {
            switch SystemLanguageModel.default.availability {
            case .available:
                content
            case .unavailable(let reason):
                ContentUnavailableView {
                    Label("Apple Intelligence Unavailable", systemImage: "person.fill.questionmark")
                } description: {
                    Text("The Stranger uses the on-device model, so no text leaves this Mac. \(describe(reason))")
                }
            }
        }
    }

    private var content: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 12) {
                HStack(spacing: 10) {
                    Button {
                        run()
                    } label: {
                        Label(isRunning ? "Reading…" : "Summon the Stranger",
                              systemImage: "person.fill.questionmark")
                    }
                    .disabled(isRunning)
                    if isRunning {
                        ProgressView()
                            .controlSize(.small)
                    }
                    Picker("Mode", selection: $mode) {
                        ForEach(StrangerMode.allCases) { mode in
                            Text(mode.rawValue).tag(mode)
                        }
                    }
                    .pickerStyle(.segmented)
                    .fixedSize()
                    .labelsHidden()
                    .help("Challenge names what the community believes but has never defended; Support names what it has right but undervalues")
                    Spacer()
                    if let reading, !reading.findings.isEmpty {
                        Button {
                            putOnRecord(reading)
                        } label: {
                            Label("Put It on the Record", systemImage: "signature")
                        }
                        .help("Writes this reading into the community folder as a document — machine authorship declared, its claims linked to the documents they answer")
                    }
                }
                if let errorText {
                    Text(errorText)
                        .font(.callout)
                        .foregroundStyle(.red)
                }
                if reading == nil, !isRunning {
                    Text("The Stranger stands both inside and outside the community — after Georg Simmel's stranger, by way of David Millard. It reads every document, but owes the community's conclusions nothing: in Challenge it names what everyone believes but no one has defended; in Support, what is right but undervalued. It may ask to switch modes; only you can grant it. The prompts are yours: Settings → AI.")
                        .font(.callout)
                        .foregroundStyle(.secondary)
                }
                if let reading {
                    if reading.findings.isEmpty, !isRunning {
                        Text(reading.mode == .challenge
                             ? "The Stranger found no consensus worth challenging — this community already argues well with itself. An empty answer is an honest one."
                             : "The Stranger found nothing genuinely undervalued. An empty answer is an honest one.")
                            .font(.callout)
                            .foregroundStyle(.secondary)
                    }
                    ForEach(reading.findings) { finding in
                        findingRow(finding, mode: reading.mode)
                    }
                    if !reading.question.isEmpty {
                        questionView(reading.question, mode: reading.mode)
                    }
                    if let request = reading.modeRequest {
                        modeRequestView(request, from: reading.mode)
                    }
                }
            }
            .frame(maxWidth: 620, alignment: .leading)
            .frame(maxWidth: .infinity)
            .padding(20)
        }
    }

    @ViewBuilder
    private func findingRow(_ finding: ResolvedFinding, mode: StrangerMode) -> some View {
        Button {
            withAnimation(.snappy) {
                if unfurled.contains(finding.id) {
                    unfurled.remove(finding.id)
                } else {
                    unfurled.insert(finding.id)
                }
            }
        } label: {
            HStack(alignment: .firstTextBaseline, spacing: 7) {
                Image(systemName: unfurled.contains(finding.id) ? "chevron.down" : "chevron.right")
                    .font(.caption)
                    .foregroundStyle(.secondary)
                Text(finding.topic)
                    .font(.system(size: 19, weight: .bold, design: .serif))
                Text("\(finding.entries.count) document\(finding.entries.count == 1 ? "" : "s")")
                    .font(.caption.monospacedDigit())
                    .foregroundStyle(.secondary)
                    .padding(.horizontal, 6)
                    .padding(.vertical, 1)
                    .background(.quaternary, in: Capsule())
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .padding(.top, 6)
        Text(finding.position)
            .font(.callout)
            .foregroundStyle(.secondary)
            .padding(.leading, 18)
        if unfurled.contains(finding.id) {
            Text(finding.answer)
                .font(.callout)
                .italic()
                .padding(.leading, 36)
                .padding(.top, 4)
            ForEach(finding.entries) { entry in
                Button {
                    model.openInLibrary(entry.doc)
                } label: {
                    VStack(alignment: .leading, spacing: 1) {
                        Text(entry.doc.title)
                        Text("\(entry.doc.displayAuthor) · \(entry.doc.listedDateText)")
                            .font(.caption)
                            .foregroundStyle(.secondary)
                    }
                    .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
                .padding(.leading, 54)
                .padding(.vertical, 2)
            }
        }
    }

    private func questionView(_ question: String, mode: StrangerMode) -> some View {
        VStack(alignment: .leading, spacing: 4) {
            Text(mode == .challenge
                 ? "The question the community writes around"
                 : "The question the community is close to answering")
                .font(.system(size: 19, weight: .bold, design: .serif))
            Text(question)
                .font(.callout)
                .italic()
                .padding(.leading, 18)
        }
        .padding(.top, 10)
    }

    /// The Stranger's request to switch modes — reciprocal signalling:
    /// the model may ask, only the reader grants.
    private func modeRequestView(_ reason: String, from current: StrangerMode) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Text("The Stranger asks to switch to \(current.other.rawValue)")
                .font(.headline)
            Text(reason)
                .font(.callout)
                .italic()
            HStack {
                Button("Let It — Read Again as \(current.other.rawValue)") {
                    mode = current.other
                    run()
                }
                Button("Not Now") {
                    guard let reading else { return }
                    self.reading = StrangerReading(mode: reading.mode,
                                                   findings: reading.findings,
                                                   question: reading.question,
                                                   modeRequest: nil)
                }
            }
        }
        .padding(14)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(.quaternary.opacity(0.5), in: RoundedRectangle(cornerRadius: 10))
        .padding(.top, 12)
    }

    // MARK: - Running the model

    private func describe(_ reason: SystemLanguageModel.Availability.UnavailableReason) -> String {
        switch reason {
        case .deviceNotEligible:
            return "This Mac does not support Apple Intelligence."
        case .modelNotReady:
            return "The model is still preparing; try again shortly."
        default:
            return "Enable Apple Intelligence in System Settings to use it."
        }
    }

    private func run() {
        isRunning = true
        errorText = nil
        let corpus = AIInsights.corpus(from: Array(model.index.byID.values))
        guard corpus.includedCount > 0 else {
            errorText = "No text documents in the library yet."
            isRunning = false
            return
        }
        var fullPrompt = mode == .challenge ? challengePrompt : supportPrompt
        if mode == .challenge {
            let unchallenged = unchallengedByLinks().prefix(8)
            if !unchallenged.isEmpty {
                fullPrompt += "\n\nSUPPORTED BY LINKS, NEVER CHALLENGED: "
                    + unchallenged.map { "[\($0)]" }.joined(separator: " ")
            }
        }
        fullPrompt += "\n\nTHE DOCUMENTS (\(corpus.includedCount) included"
        if corpus.omittedCount > 0 {
            fullPrompt += ", \(corpus.omittedCount) older omitted for space"
        }
        fullPrompt += "):\n\n" + corpus.text
        let request = fullPrompt
        let requestMode = mode
        Task {
            do {
                let session = LanguageModelSession()
                let response = try await session.respond(to: request, generating: GeneratedStrangerReading.self)
                let generated = response.content
                reading = StrangerReading(
                    mode: requestMode,
                    findings: resolve(generated.findings),
                    question: generated.question.trimmingCharacters(in: .whitespaces),
                    modeRequest: generated.suggestsOtherMode && !generated.modeSwitchReason.isEmpty
                        ? generated.modeSwitchReason : nil)
                unfurled = []
            } catch {
                errorText = "The model could not respond: \(error.localizedDescription)"
            }
            isRunning = false
        }
    }

    /// Grounding: unknown addresses are dropped, and a finding must keep
    /// at least one real document to survive.
    private func resolve(_ generated: [GeneratedStrangerFinding]) -> [ResolvedFinding] {
        let byID = model.index.byID
        return generated.compactMap { finding in
            var seen: Set<String> = []
            let entries = finding.addresses
                .map { LiquidAddress.canonical($0) }
                .filter { seen.insert($0).inserted }
                .compactMap { byID[$0] }
            guard !entries.isEmpty else { return nil }
            return ResolvedFinding(topic: finding.topic, position: finding.position,
                                   answer: finding.answer, entries: entries)
        }
    }

    /// The link-level consensus signal, computed before the model reads:
    /// documents that receive supports or extends links and not one
    /// disagrees-with or questions.
    private func unchallengedByLinks() -> [String] {
        var supported: Set<String> = []
        var challenged: Set<String> = []
        let byID = model.index.byID
        for entry in byID.values {
            for link in entry.doc.links {
                let target = model.index.latestRevision(of: LiquidAddress.canonical(link.to))
                guard byID[target] != nil, target != entry.id else { continue }
                switch link.rel {
                case "supports", "extends": supported.insert(target)
                case "disagrees-with", "questions": challenged.insert(target)
                default: break
                }
            }
        }
        return supported.subtracting(challenged).sorted()
    }

    // MARK: - On the record

    /// The reading becomes a document in the community folder: machine
    /// authorship declared (`aiOnBehalf`), each finding linked to the
    /// documents it answers — questions in challenge, supports in support
    /// — so the Stranger's statement takes its place in the document web
    /// like anything else on the record.
    private func putOnRecord(_ reading: StrangerReading) {
        guard let folder = model.index.folderURL else {
            model.showNote("Choose a community folder first — the record lives there.")
            return
        }
        let created = Date.now
        let author = "The Stranger"
        let id = LiquidAddress.makeID(author: author, created: created,
                                      isTaken: { model.index.isIDTaken($0) })
        var paragraphs: [LiquidDoc.Paragraph] = []
        var links: [LiquidDoc.Link] = []
        var linked: Set<String> = []
        var counter = 0
        func add(_ text: String, heading: Int? = nil) {
            counter += 1
            paragraphs.append(LiquidDoc.Paragraph(id: "p\(counter)", heading: heading, text: text))
        }
        add("This document is machine-written. The Stranger is an AI reader standing both inside and outside this community — after Georg Simmel's stranger, by way of David Millard — summoned in \(reading.mode.rawValue.lowercased()) mode by a reader of this library. Its statements carry no authority beyond their reasons, and they are on the record so the community can answer them.")
        for finding in reading.findings {
            add(finding.topic, heading: 2)
            let addresses = finding.entries.map { "[\($0.id)]" }.joined(separator: " ")
            add("\(finding.position) \(addresses)")
            add(finding.answer)
            for entry in finding.entries where linked.insert(entry.id).inserted {
                links.append(LiquidDoc.Link(to: entry.id, fragment: nil, rel: reading.mode.recordRel))
            }
        }
        if !reading.question.isEmpty {
            add("The Stranger's question", heading: 2)
            add(reading.question)
        }
        let title = reading.mode == .challenge ? "A Stranger's Challenge" : "A Stranger's Support"
        // The standard slug--id file name convention.
        let slug = LiquidDoc.fileSlug(from: title)
        let ext = LiquidDoc.fileExtension
        let fileName = slug.isEmpty ? "\(id).\(ext)" : "\(slug)--\(id).\(ext)"
        var doc = LiquidDoc(format: LiquidDoc.knownFormat,
                            id: id,
                            title: title,
                            author: author,
                            created: created,
                            body: paragraphs,
                            links: links,
                            wraps: nil,
                            fileURL: folder.appendingPathComponent(fileName))
        doc.aiOnBehalf = true
        let finished = VisualMeta.appendingAppendix(to: doc)
        do {
            try finished.jsonData().write(to: finished.fileURL, options: .atomic)
            model.showNote("“\(title)” is on the record.")
        } catch {
            model.showNote("Could not put the reading on the record: \(error.localizedDescription)")
        }
    }
}

extension StrangerView {
    /// The Stranger as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "the-stranger",
        name: "The Stranger",
        systemImage: "person.fill.questionmark",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(StrangerView()) },
        hidesDocumentList: true
    )
}

themes.source:
import SwiftUI
import FoundationModels

/// Defaults for the Themes view. Runs entirely on-device (Apple
/// Intelligence); no text leaves the Mac. The prompt is editable in
/// Settings → AI.
nonisolated enum Themes {

    /// The default prompt. It teaches the model what a theme is (a thread
    /// of the conversation, not a keyword), how to read the corpus headers
    /// and metadata, and to ground every theme in real document addresses.
    static let defaultPrompt = """
    You are reading a community of thinkers' documents to surface the themes running through them: the recurring subjects, questions, and ideas that no single document owns but several share. Themes, not keywords — name the threads of the conversation the way a good editor would.

    How to read the material: each document begins with a == line giving its title, author, date, and address. A following Relations: line is metadata — typed links between documents — treat it as structure, never as prose. Anything resembling Visual-Meta or BibTeX (@{...} markers, key = {value} fields) is metadata about a document, not content; disregard it as text even if fragments appear.

    Name between four and ten themes, strongest first. Each theme needs: a name of one to four words; one sentence on what these documents are saying about it; and the addresses of the documents where it appears, copied exactly from their == lines. A theme that connects three documents is worth more than three themes with one document each. Most documents should find a home in some theme, but do not force weak fits, and never invent an address.
    """
}

/// One theme as the model returns it. Guided generation constrains the
/// shape; the addresses are verified against the index before display.
@Generable
nonisolated struct GeneratedTheme {
    @Guide(description: "The theme's name: one to four words")
    var name: String
    @Guide(description: "One sentence on what these documents say about this theme")
    var summary: String
    @Guide(description: "Addresses of the documents where this theme appears, copied exactly from the == lines, e.g. f.hegla.093000k")
    var addresses: [String]
}

@Generable
nonisolated struct GeneratedThemeList {
    @Guide(description: "The themes running through the documents, strongest first")
    var themes: [GeneratedTheme]
}

/// The living successor to a static key-terms list: the on-device model
/// reads the library and names the threads of the conversation. Each theme
/// unfurls to the documents that carry it.
struct ThemesView: View {
    @Environment(AppModel.self) private var model
    @AppStorage(AppSettings.aiThemesPromptKey) private var prompt = Themes.defaultPrompt
    @State private var themes: [ResolvedTheme] = []
    @State private var hasRun = false
    @State private var isRunning = false
    @State private var errorText: String?
    @State private var unfurled: Set<String> = []

    /// A theme whose addresses all resolved to real library documents.
    struct ResolvedTheme: Identifiable {
        let name: String
        let summary: String
        let entries: [IndexEntry]
        var id: String { name }
    }

    var body: some View {
        Group {
            switch SystemLanguageModel.default.availability {
            case .available:
                content
            case .unavailable(let reason):
                ContentUnavailableView {
                    Label("Apple Intelligence Unavailable", systemImage: "tag")
                } description: {
                    Text("Themes uses the on-device model, so no text leaves this Mac. \(describe(reason))")
                }
            }
        }
    }

    private var content: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 12) {
                HStack(spacing: 10) {
                    Button {
                        run()
                    } label: {
                        Label(isRunning ? "Reading…" : (hasRun ? "Find Themes Again" : "Find Themes"),
                              systemImage: "tag")
                    }
                    .disabled(isRunning)
                    if isRunning {
                        ProgressView()
                            .controlSize(.small)
                    }
                    Spacer()
                }
                if let errorText {
                    Text(errorText)
                        .font(.callout)
                        .foregroundStyle(.red)
                }
                if !hasRun, !isRunning {
                    Text("The on-device model reads every document in the library and names the themes running through them — a living list, not a static index. Each theme opens to its documents. The prompt is yours: Settings → AI.")
                        .font(.callout)
                        .foregroundStyle(.secondary)
                } else if hasRun, themes.isEmpty, !isRunning {
                    Text("No themes grounded in library documents came back. Try again, or adjust the prompt in Settings → AI.")
                        .font(.callout)
                        .foregroundStyle(.secondary)
                }
                ForEach(themes) { theme in
                    themeRow(theme)
                }
            }
            .frame(maxWidth: 620, alignment: .leading)
            .frame(maxWidth: .infinity)
            .padding(20)
        }
    }

    @ViewBuilder
    private func themeRow(_ theme: ResolvedTheme) -> some View {
        Button {
            withAnimation(.snappy) {
                if unfurled.contains(theme.id) {
                    unfurled.remove(theme.id)
                } else {
                    unfurled.insert(theme.id)
                }
            }
        } label: {
            HStack(alignment: .firstTextBaseline, spacing: 7) {
                Image(systemName: unfurled.contains(theme.id) ? "chevron.down" : "chevron.right")
                    .font(.caption)
                    .foregroundStyle(.secondary)
                Text(theme.name)
                    .font(.system(size: 19, weight: .bold, design: .serif))
                Text("\(theme.entries.count)")
                    .font(.caption.monospacedDigit())
                    .foregroundStyle(.secondary)
                    .padding(.horizontal, 6)
                    .padding(.vertical, 1)
                    .background(.quaternary, in: Capsule())
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .padding(.top, 6)
        Text(theme.summary)
            .font(.callout)
            .foregroundStyle(.secondary)
            .padding(.leading, 18)
        if unfurled.contains(theme.id) {
            ForEach(theme.entries) { entry in
                Button {
                    model.openInLibrary(entry.doc)
                } label: {
                    VStack(alignment: .leading, spacing: 1) {
                        Text(entry.doc.title)
                        Text("\(entry.doc.displayAuthor) · \(entry.doc.listedDateText)")
                            .font(.caption)
                            .foregroundStyle(.secondary)
                    }
                    .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
                .padding(.leading, 36)
                .padding(.vertical, 2)
            }
        }
    }

    // MARK: - Running the model

    private func describe(_ reason: SystemLanguageModel.Availability.UnavailableReason) -> String {
        switch reason {
        case .deviceNotEligible:
            return "This Mac does not support Apple Intelligence."
        case .modelNotReady:
            return "The model is still preparing; try again shortly."
        default:
            return "Enable Apple Intelligence in System Settings to use it."
        }
    }

    private func run() {
        isRunning = true
        errorText = nil
        let corpus = AIInsights.corpus(from: Array(model.index.byID.values))
        guard corpus.includedCount > 0 else {
            errorText = "No text documents in the library yet."
            isRunning = false
            return
        }
        var fullPrompt = prompt
        fullPrompt += "\n\nTHE DOCUMENTS (\(corpus.includedCount) included"
        if corpus.omittedCount > 0 {
            fullPrompt += ", \(corpus.omittedCount) older omitted for space"
        }
        fullPrompt += "):\n\n" + corpus.text
        let request = fullPrompt
        Task {
            do {
                let session = LanguageModelSession()
                let response = try await session.respond(to: request, generating: GeneratedThemeList.self)
                themes = resolve(response.content.themes)
                unfurled = []
                hasRun = true
            } catch {
                errorText = "The model could not respond: \(error.localizedDescription)"
            }
            isRunning = false
        }
    }

    /// Grounding: every address must resolve to a real library document —
    /// unknown addresses are dropped, and a theme with no real documents
    /// left disappears with them.
    private func resolve(_ generated: [GeneratedTheme]) -> [ResolvedTheme] {
        generated.compactMap { theme in
            var seen: Set<String> = []
            let entries = theme.addresses
                .map { LiquidAddress.canonical($0) }
                .filter { seen.insert($0).inserted }
                .compactMap { model.index.byID[$0] }
            guard !entries.isEmpty else { return nil }
            return ResolvedTheme(name: theme.name, summary: theme.summary, entries: entries)
        }
    }
}

extension ThemesView {
    /// The Themes view as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "themes",
        name: "Themes",
        systemImage: "tag",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(ThemesView()) },
        hidesDocumentList: true
    )
}

