import SwiftUI

/// The Weave: the library with the figure and ground reversed — the
/// connections are the vital thing, the documents just knots on the
/// thread (6 July 2026 meeting: "the string, the connector is the vital
/// thing; the knot is just the thing on it"). Every document is a knot of
/// light on a slowly turning wheel, ordered by author and time; every
/// link is a thread across it, shading between its two authors' colors.
/// Hover a knot and its threads flare while the rest fall dark; drag to
/// spin; click a knot to read it. A provocation, not an instrument.
struct WeaveView: View {
    @Environment(AppModel.self) private var model

    var body: some View {
        let data = WeaveData.build(from: Array(model.index.byID.values),
                                   backlinks: model.index.backlinks)
        if data.nodes.isEmpty {
            ContentUnavailableView("Nothing to Weave",
                                   systemImage: "asterisk",
                                   description: Text("The Weave appears once the library holds documents."))
        } else {
            WeaveCanvas(data: data) { docID in
                if let entry = model.index.byID[docID] {
                    model.openInLibrary(entry.doc)
                }
            }
        }
    }
}

// MARK: - Data

struct WeaveNode: Identifiable {
    let id: String        // document id
    let title: String
    let author: String
    let weight: Int       // citations received — the knot's size
    let hue: Double       // the author's color
}

struct WeaveEdge {
    let from: Int
    let to: Int
}

/// A text held to the wheel: its words at the hub, and threads to the
/// knots it is kin to, each with a strength the drawing scales by and
/// an optional tint — K. Nav colors them by stance toward the typed
/// keyword. While a probe stands, every other thread falls dark grey:
/// the wheel answers the keyword and nothing else.
struct WeaveProbe {
    let label: String
    let threads: [(node: Int, strength: Double, tint: Color?)]
}

struct WeaveData {
    var nodes: [WeaveNode] = []
    var edges: [WeaveEdge] = []
    /// Author label arcs: name, hue, and the node-index range they span.
    var authorArcs: [(name: String, hue: Double, range: ClosedRange<Int>)] = []

    static func build(from entries: [IndexEntry], backlinks: [String: [BacklinkRef]]) -> WeaveData {
        // Authors around the wheel, most prolific first; their documents
        // in creation order, so time runs along each author's arc.
        let byAuthor = Dictionary(grouping: entries, by: { $0.doc.creditedAuthor })
        let authors = byAuthor.keys.sorted {
            (byAuthor[$0]?.count ?? 0, $1) > (byAuthor[$1]?.count ?? 0, $0)
        }
        var data = WeaveData()
        var indexByID: [String: Int] = [:]
        for (authorIndex, author) in authors.enumerated() {
            let hue = Double(authorIndex) / Double(max(authors.count, 1))
            let docs = (byAuthor[author] ?? []).sorted { $0.doc.created < $1.doc.created }
            let start = data.nodes.count
            for entry in docs {
                indexByID[entry.doc.id] = data.nodes.count
                data.nodes.append(WeaveNode(id: entry.doc.id,
                                            title: entry.doc.title,
                                            author: author,
                                            weight: backlinks[entry.doc.id]?.count ?? 0,
                                            hue: hue))
            }
            if data.nodes.count > start {
                data.authorArcs.append((author, hue, start...(data.nodes.count - 1)))
            }
        }
        for entry in entries {
            guard let from = indexByID[entry.doc.id] else { continue }
            for link in entry.doc.links {
                guard let to = indexByID[LiquidAddress.canonical(link.to)], to != from else { continue }
                data.edges.append(WeaveEdge(from: from, to: to))
            }
        }
        data.edges = Array(data.edges.prefix(1200))   // stay legible and fast
        return data
    }
}

// MARK: - The wheel

struct WeaveCanvas: View {
    let data: WeaveData
    var onOpen: (String) -> Void = { _ in }
    /// The wheel's name, and what its resting center counts. The Lift
    /// Weave reuses the whole canvas under its own name.
    var title = "The Weave"
    var subtitle: String? = nil
    /// A second family of threads, drawn brighter and dashed — K. Nav
    /// lays its bridges over the wheel this way. The classic weaves
    /// leave it empty and are unchanged.
    var brightEdges: [WeaveEdge] = []
    /// A probe at the hub: a text standing at the wheel's center with
    /// threads of kinship out to the knots. K. Nav sets it on Enter; the
    /// classic weaves leave it nil and are unchanged.
    var probe: WeaveProbe? = nil

    /// Ambient turn: one revolution every four minutes.
    private static let ambientSpeed = (2 * Double.pi) / 240
    private let born = Date.now

    @State private var hovered: Int?
    @State private var spun: Double = 0          // accumulated drag, radians
    @State private var dragDelta: Double = 0     // live drag, radians
    @State private var frameSize: CGSize = .zero

    var body: some View {
        GeometryReader { geometry in
            TimelineView(.animation(minimumInterval: 1.0 / 30.0)) { timeline in
                Canvas { context, size in
                    draw(in: &context, size: size, at: timeline.date)
                }
            }
            .background(
                RadialGradient(colors: [Color(white: 0.09), .black],
                               center: .center, startRadius: 0,
                               endRadius: max(geometry.size.width, geometry.size.height) / 1.2)
            )
            .onContinuousHover { phase in
                switch phase {
                case .active(let point):
                    hovered = nearestNode(to: point, in: geometry.size, at: .now)
                case .ended:
                    hovered = nil
                }
            }
            .gesture(spinGesture(in: geometry.size))
            .gesture(SpatialTapGesture().onEnded { value in
                if let index = nearestNode(to: value.location, in: geometry.size, at: .now) {
                    onOpen(data.nodes[index].id)
                }
            })
            .onAppear { frameSize = geometry.size }
            .onChange(of: geometry.size) { frameSize = geometry.size }
            .overlay(alignment: .center) { centerLabel }
        }
    }

    /// The wheel's center speaks: the hovered knot, the probe held to
    /// the wheel, or the weave itself.
    private var centerLabel: some View {
        VStack(spacing: 4) {
            if let hovered, data.nodes.indices.contains(hovered) {
                let node = data.nodes[hovered]
                Text(node.title)
                    .font(.system(size: 17, design: .serif))
                    .foregroundStyle(.white)
                Text(node.author)
                    .font(.caption)
                    .foregroundStyle(color(hue: node.hue, brightness: 0.95))
            } else if let probe {
                Text("“\(String(probe.label.prefix(90)))”")
                    .font(.system(size: 15, design: .serif))
                    .italic()
                    .foregroundStyle(.white)
                Text(probe.threads.isEmpty
                     ? "no kinship found"
                     : "\(probe.threads.count) kinship\(probe.threads.count == 1 ? "" : "s") in the weave")
                    .font(.caption2)
                    .foregroundStyle(.white.opacity(0.4))
            } else {
                Text(title.uppercased())
                    .font(.system(size: 11, weight: .semibold))
                    .kerning(3)
                    .foregroundStyle(.white.opacity(0.35))
                Text(subtitle ?? "\(data.nodes.count) knots · \(data.edges.count) threads")
                    .font(.caption2)
                    .foregroundStyle(.white.opacity(0.25))
            }
        }
        .multilineTextAlignment(.center)
        .frame(maxWidth: 220)
        .allowsHitTesting(false)
    }

    // MARK: Geometry

    private func rotation(at date: Date) -> Double {
        Self.ambientSpeed * date.timeIntervalSince(born) + spun + dragDelta
    }

    private func ringRadius(in size: CGSize) -> Double {
        min(size.width, size.height) / 2 - 64
    }

    private func position(of index: Int, in size: CGSize, at date: Date) -> CGPoint {
        let angle = angleOf(index, at: date)
        let radius = ringRadius(in: size)
        return CGPoint(x: size.width / 2 + radius * cos(angle),
                       y: size.height / 2 + radius * sin(angle))
    }

    private func angleOf(_ index: Int, at date: Date) -> Double {
        rotation(at: date) + 2 * .pi * Double(index) / Double(max(data.nodes.count, 1))
    }

    private func nearestNode(to point: CGPoint, in size: CGSize, at date: Date) -> Int? {
        var best: (index: Int, distance: Double)?
        for index in data.nodes.indices {
            let p = position(of: index, in: size, at: date)
            let d = hypot(p.x - point.x, p.y - point.y)
            if d < 18, d < (best?.distance ?? .infinity) { best = (index, d) }
        }
        return best?.index
    }

    private func spinGesture(in size: CGSize) -> some Gesture {
        DragGesture()
            .onChanged { value in
                let center = CGPoint(x: size.width / 2, y: size.height / 2)
                let start = atan2(value.startLocation.y - center.y, value.startLocation.x - center.x)
                let now = atan2(value.location.y - center.y, value.location.x - center.x)
                dragDelta = now - start
            }
            .onEnded { _ in
                spun += dragDelta
                dragDelta = 0
            }
    }

    private func color(hue: Double, brightness: Double, opacity: Double = 1) -> Color {
        Color(hue: hue, saturation: 0.62, brightness: brightness, opacity: opacity)
    }

    // MARK: Drawing

    private func draw(in context: inout GraphicsContext, size: CGSize, at date: Date) {
        guard !data.nodes.isEmpty else { return }
        let t = date.timeIntervalSince(born)
        let connected = connectedSet()
        // While a probe stands at the hub, every thread that is not the
        // probe's falls dark grey — the wheel answers the keyword and
        // nothing else.
        let greyed = probe != nil

        // Threads first — they are the vital thing. Unhovered: a breathing
        // field; hovered: everything else falls dark and its threads flare
        // through a blurred glow pass plus a crisp pass.
        for (i, edge) in data.edges.enumerated() {
            let isLit = hovered.map { edge.from == $0 || edge.to == $0 } ?? false
            if hovered != nil, !isLit {
                strokeThread(edge, in: &context, size: size, at: date, opacity: 0.05, width: 0.6,
                             greyed: greyed)
            } else if !isLit {
                let breath = greyed ? 0.16 : 0.30 + 0.14 * sin(t * 0.7 + Double(i) * 1.3)
                strokeThread(edge, in: &context, size: size, at: date, opacity: breath, width: 1.1,
                             greyed: greyed)
            }
        }
        if hovered != nil {
            context.drawLayer { layer in
                layer.addFilter(.blur(radius: 5))
                for edge in data.edges where edge.from == hovered || edge.to == hovered {
                    strokeThread(edge, in: &layer, size: size, at: date, opacity: 0.9, width: 3.5,
                                 greyed: greyed)
                }
            }
            for edge in data.edges where edge.from == hovered || edge.to == hovered {
                strokeThread(edge, in: &context, size: size, at: date, opacity: 1, width: 1.4,
                             greyed: greyed)
            }
        }

        // The bright family — bridges: dashed, wider, resting brighter
        // than the field, and flaring like any thread when an end is
        // hovered. Under a probe they fall grey like everything else.
        for (i, edge) in brightEdges.enumerated() {
            let isLit = hovered.map { edge.from == $0 || edge.to == $0 } ?? false
            if hovered != nil, !isLit {
                strokeThread(edge, in: &context, size: size, at: date,
                             opacity: 0.08, width: 0.8, dashed: true, greyed: greyed)
            } else if !isLit {
                let breath = greyed ? 0.2 : 0.5 + 0.18 * sin(t * 0.9 + Double(i) * 1.7)
                strokeThread(edge, in: &context, size: size, at: date,
                             opacity: breath, width: 1.7, dashed: true, greyed: greyed)
            }
        }
        if hovered != nil {
            context.drawLayer { layer in
                layer.addFilter(.blur(radius: 6))
                for edge in brightEdges where edge.from == hovered || edge.to == hovered {
                    strokeThread(edge, in: &layer, size: size, at: date, opacity: 1, width: 4.5,
                                 greyed: greyed)
                }
            }
            for edge in brightEdges where edge.from == hovered || edge.to == hovered {
                strokeThread(edge, in: &context, size: size, at: date,
                             opacity: 1, width: 2, dashed: true, greyed: greyed)
            }
        }

        // The probe's threads: from the hub out to its kin,
        // strength-scaled, tinted by stance when one is known, flaring
        // when their knot is hovered.
        if let probe {
            let center = CGPoint(x: size.width / 2, y: size.height / 2)
            for thread in probe.threads {
                guard data.nodes.indices.contains(thread.node) else { continue }
                let p = position(of: thread.node, in: size, at: date)
                let isLit = hovered == thread.node
                let dimmedByHover = hovered != nil && !isLit
                var path = Path()
                path.move(to: center)
                let mid = CGPoint(x: (center.x + p.x) / 2, y: (center.y + p.y) / 2)
                path.addQuadCurve(to: p, control: CGPoint(x: mid.x, y: mid.y))
                let tint = thread.tint ?? .white
                let opacity = dimmedByHover ? 0.08 : 0.35 + 0.55 * thread.strength
                let width = isLit ? 2.6 : 1.0 + 2.0 * thread.strength
                if isLit {
                    context.drawLayer { layer in
                        layer.addFilter(.blur(radius: 5))
                        layer.stroke(path, with: .color(tint.opacity(0.9)), lineWidth: 4)
                    }
                }
                context.stroke(path, with: .color(tint.opacity(opacity)), lineWidth: width)
            }
            // The hub itself: a small breathing star where the words stand.
            let pulse = 3.5 + 0.8 * sin(t * 1.4)
            context.drawLayer { layer in
                layer.addFilter(.blur(radius: 4))
                layer.fill(Path(ellipseIn: CGRect(x: center.x - pulse - 2, y: center.y - pulse - 2,
                                                  width: (pulse + 2) * 2, height: (pulse + 2) * 2)),
                           with: .color(.white.opacity(0.7)))
            }
            context.fill(Path(ellipseIn: CGRect(x: center.x - pulse, y: center.y - pulse,
                                                width: pulse * 2, height: pulse * 2)),
                         with: .color(.white))
        }

        // The knots.
        for index in data.nodes.indices {
            let node = data.nodes[index]
            let p = position(of: index, in: size, at: date)
            let isHovered = index == hovered
            let isNeighbor = hovered.map { connected[$0]?.contains(index) ?? false } ?? false
            let dimmed = hovered != nil && !isHovered && !isNeighbor
            let radius = (2.0 + min(6, Double(node.weight).squareRoot() * 2)) * (isHovered ? 1.6 : 1)
            let rect = CGRect(x: p.x - radius, y: p.y - radius, width: radius * 2, height: radius * 2)
            if isHovered || isNeighbor {
                context.drawLayer { layer in
                    layer.addFilter(.blur(radius: 6))
                    layer.fill(Path(ellipseIn: rect.insetBy(dx: -3, dy: -3)),
                               with: .color(color(hue: node.hue, brightness: 1)))
                }
            }
            context.fill(Path(ellipseIn: rect),
                         with: .color(color(hue: node.hue,
                                            brightness: dimmed ? 0.35 : 0.95,
                                            opacity: dimmed ? 0.5 : 1)))
        }

        // Author names riding their arc of the ring, kept upright.
        let labelRadius = ringRadius(in: size) + 30
        for arc in data.authorArcs {
            let mid = (angleOf(arc.range.lowerBound, at: date) + angleOf(arc.range.upperBound, at: date)) / 2
            let p = CGPoint(x: size.width / 2 + labelRadius * cos(mid),
                            y: size.height / 2 + labelRadius * sin(mid))
            var rotated = context
            rotated.translateBy(x: p.x, y: p.y)
            var textAngle = mid + .pi / 2
            if sin(mid) > 0 { textAngle += .pi }
            rotated.rotate(by: .radians(textAngle))
            let dimmed = hovered != nil && data.nodes[hovered ?? 0].author != arc.name
            rotated.draw(Text(arc.name)
                            .font(.system(size: 9, weight: .semibold))
                            .foregroundStyle(color(hue: arc.hue,
                                                   brightness: dimmed ? 0.4 : 0.9)),
                         at: .zero, anchor: .center)
        }
    }

    private func strokeThread(_ edge: WeaveEdge, in context: inout GraphicsContext,
                              size: CGSize, at date: Date, opacity: Double, width: Double,
                              dashed: Bool = false, greyed: Bool = false) {
        let a = position(of: edge.from, in: size, at: date)
        let b = position(of: edge.to, in: size, at: date)
        let center = CGPoint(x: size.width / 2, y: size.height / 2)
        let mid = CGPoint(x: (a.x + b.x) / 2, y: (a.y + b.y) / 2)
        // Chords bow toward the hub: far ends dive deep, near ends stay shallow.
        let control = CGPoint(x: center.x + (mid.x - center.x) * 0.35,
                              y: center.y + (mid.y - center.y) * 0.35)
        var path = Path()
        path.move(to: a)
        path.addQuadCurve(to: b, control: control)
        let style = StrokeStyle(lineWidth: width, dash: dashed ? [6, 4] : [])
        if greyed {
            context.stroke(path, with: .color(Color(white: 0.3).opacity(opacity)), style: style)
            return
        }
        let fromColor = color(hue: data.nodes[edge.from].hue, brightness: 0.9, opacity: opacity)
        let toColor = color(hue: data.nodes[edge.to].hue, brightness: 0.9, opacity: opacity)
        context.stroke(path,
                       with: .linearGradient(Gradient(colors: [fromColor, toColor]),
                                             startPoint: a, endPoint: b),
                       style: style)
    }

    /// Which knots each knot touches, for neighbor lighting — the bright
    /// family counts too.
    private func connectedSet() -> [Int: Set<Int>] {
        var map: [Int: Set<Int>] = [:]
        for edge in data.edges + brightEdges {
            map[edge.from, default: []].insert(edge.to)
            map[edge.to, default: []].insert(edge.from)
        }
        return map
    }
}

extension WeaveView {
    /// The Weave as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "weave",
        name: "The Weave",
        systemImage: "asterisk",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(WeaveView()) },
        hidesDocumentList: true
    )
}

// MARK: - Preview with a synthetic community

#Preview("The Weave") {
    // Deterministic pseudo-community: six authors, forty knots, a weave
    // of threads — no library required.
    var data = WeaveData()
    let authors = ["Frode Hegland", "Mark Anderson", "Fabien Benetou",
                   "Peter Wasilko", "Tom Haymes", "Mohit"]
    var seed: UInt64 = 9
    func random(_ bound: Int) -> Int {
        seed = seed &* 6364136223846793005 &+ 1442695040888963407
        return Int(seed >> 33) % bound
    }
    var start = 0
    for (i, author) in authors.enumerated() {
        let count = 4 + random(6)
        let hue = Double(i) / Double(authors.count)
        for d in 0..<count {
            data.nodes.append(WeaveNode(id: "\(i)-\(d)", title: "Document \(d + 1)",
                                        author: author, weight: random(9), hue: hue))
        }
        data.authorArcs.append((author, hue, start...(data.nodes.count - 1)))
        start = data.nodes.count
    }
    for _ in 0..<70 {
        let from = random(data.nodes.count)
        let to = random(data.nodes.count)
        if from != to { data.edges.append(WeaveEdge(from: from, to: to)) }
    }
    return WeaveCanvas(data: data)
        .frame(width: 720, height: 640)
}

z.source:
import SwiftUI

/// Z: the library as a Zettelkasten. One slip at a time — the current
/// document as an index card, with its neighbors filed around it: what it
/// cites, what cites it, and its Folgezettel (the same author's slips
/// just before and after it in time). Click a neighbor to step to it; the
/// trail of slips you have walked stays visible across the top, and any
/// slip on it takes you back. Double-click any slip to read it in full.
/// The box converses by adjacency: each step shows you what the last one
/// was filed next to.
struct ZView: View {
    @Environment(AppModel.self) private var model
    /// The walk so far, as document ids; the last is the current slip.
    @State private var trail: [String] = []

    private var currentDoc: LiquidDoc? {
        trail.last.flatMap { model.index.byID[$0]?.doc }
    }

    var body: some View {
        Group {
            if model.index.byID.isEmpty {
                ContentUnavailableView("The Box Is Empty",
                                       systemImage: "z.square",
                                       description: Text("Z walks the community library slip by slip. Choose a folder with documents to begin."))
            } else if let doc = currentDoc {
                VStack(spacing: 0) {
                    trailBar
                    Divider()
                    ScrollView {
                        VStack(spacing: 22) {
                            currentSlip(doc)
                            neighborShelves(around: doc)
                        }
                        .padding(24)
                        .frame(maxWidth: .infinity)
                    }
                }
                .background(desk)
            } else {
                startState
            }
        }
        .toolbar {
            ToolbarItem {
                Button {
                    pullRandomSlip()
                } label: {
                    Label("Pull a Slip", systemImage: "die.face.3")
                }
                .help("Pull a random slip from the box and start a new trail there")
            }
        }
        .onAppear {
            // Enter the box where you already are, if you are anywhere.
            if trail.isEmpty, let current = model.current?.doc,
               model.index.byID[current.id] != nil {
                trail = [current.id]
            }
        }
    }

    private var desk: some View {
        Color(red: 0.93, green: 0.91, blue: 0.87).ignoresSafeArea()
    }

    private var startState: some View {
        ContentUnavailableView {
            Label("Z", systemImage: "z.square")
        } description: {
            Text("Pull a slip and follow its neighbors — what it cites, what cites it, what its author filed beside it. The box answers one slip at a time.")
        } actions: {
            Button("Pull a Slip") { pullRandomSlip() }
                .buttonStyle(.borderedProminent)
        }
    }

    private func pullRandomSlip() {
        guard let doc = model.index.byID.values.map(\.doc)
            .filter({ !model.index.supersededIDs.contains($0.id) })
            .randomElement() else { return }
        withAnimation { trail = [doc.id] }
    }

    private func step(to id: String) {
        let resolved = model.index.latestRevision(of: id)
        guard model.index.byID[resolved] != nil else { return }
        withAnimation {
            if let existing = trail.firstIndex(of: resolved) {
                trail = Array(trail.prefix(through: existing))
            } else {
                trail.append(resolved)
            }
        }
    }

    // MARK: The trail

    private var trailBar: some View {
        ScrollViewReader { proxy in
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 6) {
                    ForEach(Array(trail.enumerated()), id: \.offset) { index, id in
                        if index > 0 {
                            Image(systemName: "arrow.right")
                                .font(.system(size: 9))
                                .foregroundStyle(.tertiary)
                        }
                        Button {
                            step(to: id)
                        } label: {
                            Text(model.index.byID[id]?.doc.title ?? id)
                                .font(.system(size: 11))
                                .lineLimit(1)
                                .padding(.horizontal, 8)
                                .padding(.vertical, 3)
                                .background(index == trail.count - 1 ? AnyShapeStyle(.quaternary) : AnyShapeStyle(.clear),
                                            in: Capsule())
                        }
                        .buttonStyle(.plain)
                        .id(index)
                    }
                }
                .padding(.horizontal, 16)
                .padding(.vertical, 8)
            }
            .onChange(of: trail.count) {
                proxy.scrollTo(trail.count - 1, anchor: .trailing)
            }
        }
    }

    // MARK: The current slip

    private func currentSlip(_ doc: LiquidDoc) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack(alignment: .firstTextBaseline) {
                Text(doc.title)
                    .font(.system(size: 21, weight: .semibold, design: .serif))
                Spacer()
                Text(doc.id)
                    .font(.system(size: 10, design: .monospaced))
                    .foregroundStyle(.secondary)
            }
            Text("\(doc.displayAuthor) · \(doc.listedDateText)")
                .font(.callout)
                .foregroundStyle(.secondary)
            Divider()
            ForEach((doc.body ?? [])
                .filter { $0.effectiveHeading == nil && !$0.displayText.isEmpty }
                .prefix(3)) { paragraph in
                Text(paragraph.displayText)
                    .font(.system(size: 13, design: .serif))
                    .lineLimit(4)
            }
            Button("Read in full") { model.openInLibrary(doc) }
                #if os(macOS)
                .buttonStyle(.link)
                #endif
                .font(.caption)
        }
        .padding(18)
        .frame(maxWidth: 560, alignment: .leading)
        .background(slipPaper)
        .onTapGesture(count: 2) { model.openInLibrary(doc) }
    }

    // MARK: The neighbors

    private func neighborShelves(around doc: LiquidDoc) -> some View {
        let cites = doc.links
            .map { model.index.latestRevision(of: LiquidAddress.canonical($0.to)) }
            .filter { $0 != doc.id }
            .compactMap { model.index.byID[$0]?.doc }
        let citedBy = (model.index.backlinks[doc.id] ?? [])
            .compactMap { model.index.byID[$0.fromID]?.doc }
        let folge = folgezettel(of: doc)
        return HStack(alignment: .top, spacing: 18) {
            shelf("← Cited by", citedBy,
                  empty: "No slip points here yet.")
            shelf("Folgezettel", folge,
                  empty: "No neighboring slips by this author.")
            shelf("Cites →", cites,
                  empty: "This slip points at no other.")
        }
        .frame(maxWidth: 900)
    }

    /// The slips the same author filed just before and after this one —
    /// the sequence a Zettelkasten keeps by physical order.
    private func folgezettel(of doc: LiquidDoc) -> [LiquidDoc] {
        let theirs = model.index.byID.values.map(\.doc)
            .filter { $0.author == doc.author }
            .sorted { $0.created < $1.created }
        guard let index = theirs.firstIndex(where: { $0.id == doc.id }) else { return [] }
        var neighbors: [LiquidDoc] = []
        if index > 0 { neighbors.append(theirs[index - 1]) }
        if index < theirs.count - 1 { neighbors.append(theirs[index + 1]) }
        return neighbors
    }

    private func shelf(_ title: String, _ docs: [LiquidDoc], empty: String) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(title)
                .font(.system(size: 11, weight: .semibold))
                .foregroundStyle(.secondary)
                .textCase(.uppercase)
                .kerning(0.6)
            if docs.isEmpty {
                Text(empty)
                    .font(.caption)
                    .foregroundStyle(.tertiary)
                    .frame(maxWidth: .infinity, alignment: .leading)
            }
            ForEach(docs.prefix(6)) { neighbor in
                slip(neighbor)
            }
        }
        .frame(maxWidth: .infinity, alignment: .top)
    }

    private func slip(_ doc: LiquidDoc) -> some View {
        Button {
            step(to: doc.id)
        } label: {
            VStack(alignment: .leading, spacing: 3) {
                Text(doc.title)
                    .font(.system(size: 12, weight: .medium, design: .serif))
                    .lineLimit(2)
                    .multilineTextAlignment(.leading)
                Text("\(doc.displayAuthor) · \(doc.date?.yearText ?? doc.created.formatted(.dateTime.year()))")
                    .font(.system(size: 10))
                    .foregroundStyle(.secondary)
                    .lineLimit(1)
            }
            .padding(10)
            .frame(maxWidth: .infinity, alignment: .leading)
            .background(slipPaper)
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .onTapGesture(count: 2) { model.openInLibrary(doc) }
        .help("Step to “\(doc.title)” — double-click to read it in full")
    }

    private var slipPaper: some View {
        RoundedRectangle(cornerRadius: 5)
            .fill(.white)
            .overlay(RoundedRectangle(cornerRadius: 5).strokeBorder(.black.opacity(0.10), lineWidth: 0.5))
            .shadow(color: .black.opacity(0.10), radius: 2, y: 1)
    }
}

extension ZView {
    /// Z as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "z",
        name: "Z",
        systemImage: "z.square",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(ZView()) },
        hidesDocumentList: true
    )
}

zigzag.source:
import SwiftUI

/// ZigZag, after Ted Nelson: every document is a cell that sits on several
/// ranks at once — its place in time, in its author's sequence, among its
/// kind, and in the conversation it belongs to. The view shows two
/// dimensions at a time, crossing at the focused cell: one running across,
/// one running down. Arrow keys (or clicks) move the focus along either
/// rank; rotating swaps in another dimension, and the same cell reveals
/// different neighborhoods. Double-click a cell to read it.
struct ZigZagView: View {
    @Environment(AppModel.self) private var model
    @State private var focusedID: String?
    @State private var dimAcross: Dimension = .time
    @State private var dimDown: Dimension = .author

    /// The ranks a document lies on. Each dimension answers one question:
    /// who are this cell's previous and next along me?
    enum Dimension: String, CaseIterable, Identifiable {
        case time = "d.time"
        case author = "d.author"
        case type = "d.type"
        case discourse = "d.discourse"
        var id: String { rawValue }

        var color: Color {
            switch self {
            case .time: .cyan
            case .author: .orange
            case .type: .green
            case .discourse: .purple
            }
        }
    }

    private var focusedDoc: LiquidDoc? {
        focusedID.flatMap { model.index.byID[$0]?.doc }
    }

    var body: some View {
        Group {
            if let doc = focusedDoc {
                cross(around: doc)
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .background(Color(white: 0.08).ignoresSafeArea())
                    .focusable()
                    .focusEffectDisabled()
                    .onKeyPress(.leftArrow) { move(along: dimAcross, forward: false); return .handled }
                    .onKeyPress(.rightArrow) { move(along: dimAcross, forward: true); return .handled }
                    .onKeyPress(.upArrow) { move(along: dimDown, forward: false); return .handled }
                    .onKeyPress(.downArrow) { move(along: dimDown, forward: true); return .handled }
            } else {
                ContentUnavailableView("Nothing to ZigZag",
                                       systemImage: "arrow.triangle.swap",
                                       description: Text("ZigZag crosses two dimensions of the library at a focused document. Choose a community folder with documents to begin."))
            }
        }
        .toolbar {
            ToolbarItemGroup {
                Picker("Across", selection: $dimAcross) {
                    ForEach(Dimension.allCases) { Text($0.rawValue).tag($0) }
                }
                .help("The dimension running across")
                Picker("Down", selection: $dimDown) {
                    ForEach(Dimension.allCases) { Text($0.rawValue).tag($0) }
                }
                .help("The dimension running down")
                Button {
                    swap(&dimAcross, &dimDown)
                } label: {
                    Label("Rotate", systemImage: "arrow.triangle.swap")
                }
                .help("Swap the two visible dimensions — the same cell, different neighborhoods")
            }
        }
        .onChange(of: dimAcross) { keepDimensionsDistinct(changed: \.dimAcross) }
        .onChange(of: dimDown) { keepDimensionsDistinct(changed: \.dimDown) }
        .onAppear {
            if focusedID == nil {
                if let current = model.current?.doc, model.index.byID[current.id] != nil {
                    focusedID = current.id
                } else {
                    focusedID = model.index.timeline.last?.id
                }
            }
        }
    }

    /// Two dimensions showing the same rank teach nothing; when the user
    /// picks a duplicate, the other axis steps to the next dimension.
    private func keepDimensionsDistinct(changed: KeyPath<ZigZagView, Dimension>) {
        guard dimAcross == dimDown else { return }
        let others = Dimension.allCases.filter { $0 != dimAcross }
        if changed == \.dimAcross {
            dimDown = others.first ?? dimDown
        } else {
            dimAcross = others.first ?? dimAcross
        }
    }

    private func move(along dimension: Dimension, forward: Bool) {
        guard let doc = focusedDoc else { return }
        let neighbors = neighbors(of: doc, along: dimension)
        if let next = forward ? neighbors.next : neighbors.previous {
            withAnimation(.spring(duration: 0.3)) { focusedID = next.id }
        }
    }

    // MARK: The cross

    private func cross(around doc: LiquidDoc) -> some View {
        GeometryReader { geometry in
            // The arms only grow as far as the pane allows: each across
            // step needs a cell and connector (~180 points), each down
            // step ~88, and the focused cell holds the exact center.
            let acrossReach = max(1, min(3, Int((geometry.size.width - 280) / 2 / 180)))
            let downReach = max(1, min(2, Int((geometry.size.height - 170) / 2 / 88)))
            let across = rank(around: doc, along: dimAcross, reach: acrossReach)
            let down = rank(around: doc, along: dimDown, reach: downReach)
            VStack(spacing: 8) {
                ForEach(down.before) { neighbor in
                    cell(neighbor, on: dimDown)
                    connector(dimDown, vertical: true)
                }
                HStack(spacing: 8) {
                    ForEach(across.before) { neighbor in
                        cell(neighbor, on: dimAcross)
                        connector(dimAcross, vertical: false)
                    }
                    focusedCell(doc)
                    ForEach(across.after) { neighbor in
                        connector(dimAcross, vertical: false)
                        cell(neighbor, on: dimAcross)
                    }
                }
                ForEach(down.after) { neighbor in
                    connector(dimDown, vertical: true)
                    cell(neighbor, on: dimDown)
                }
            }
            .frame(width: geometry.size.width, height: geometry.size.height)
        }
        .overlay(alignment: .topLeading) { legend }
    }

    /// The two live dimensions, named in the corner rather than riding the
    /// arms — the cross stays symmetric around the focused cell.
    private var legend: some View {
        VStack(alignment: .leading, spacing: 3) {
            dimensionLabel(dimAcross, arrow: "→")
            dimensionLabel(dimDown, arrow: "↓")
        }
        .padding(12)
    }

    private func dimensionLabel(_ dimension: Dimension, arrow: String) -> some View {
        Text("\(dimension.rawValue) \(arrow)")
            .font(.system(size: 10, weight: .semibold, design: .monospaced))
            .foregroundStyle(dimension.color.opacity(0.85))
    }

    private func connector(_ dimension: Dimension, vertical: Bool) -> some View {
        Rectangle()
            .fill(dimension.color.opacity(0.6))
            .frame(width: vertical ? 2 : 14, height: vertical ? 14 : 2)
    }

    private func focusedCell(_ doc: LiquidDoc) -> some View {
        VStack(alignment: .leading, spacing: 4) {
            Text(doc.title)
                .font(.system(size: 14, weight: .semibold, design: .serif))
                .foregroundStyle(.black)
                .lineLimit(3)
            Text("\(doc.displayAuthor) · \(doc.listedDateText)")
                .font(.system(size: 10))
                .foregroundStyle(.black.opacity(0.6))
            Text(doc.id)
                .font(.system(size: 8, design: .monospaced))
                .foregroundStyle(.black.opacity(0.4))
        }
        .padding(10)
        .frame(width: 200, alignment: .leading)
        .background(
            // The focused cell is the lit one: light card, dark ink.
            RoundedRectangle(cornerRadius: 8)
                .fill(Color(red: 0.99, green: 0.97, blue: 0.92))
                .overlay(RoundedRectangle(cornerRadius: 8).strokeBorder(.yellow.opacity(0.9), lineWidth: 1.5))
        )
        .onTapGesture(count: 2) { model.openInLibrary(doc) }
        .help("The focused cell — double-click to read")
    }

    private func cell(_ doc: LiquidDoc, on dimension: Dimension) -> some View {
        Button {
            withAnimation(.spring(duration: 0.3)) { focusedID = doc.id }
        } label: {
            VStack(alignment: .leading, spacing: 2) {
                Text(doc.title)
                    .font(.system(size: 11, design: .serif))
                    .lineLimit(2)
                    .multilineTextAlignment(.leading)
                Text("\(doc.author) · \(doc.date?.yearText ?? doc.created.formatted(.dateTime.year()))")
                    .font(.system(size: 9))
                    .foregroundStyle(.secondary)
                    .lineLimit(1)
            }
            .padding(8)
            .frame(width: 150, alignment: .leading)
            .background(
                RoundedRectangle(cornerRadius: 6)
                    .fill(Color(white: 0.13))
                    .overlay(RoundedRectangle(cornerRadius: 6)
                        .strokeBorder(dimension.color.opacity(0.5), lineWidth: 1))
            )
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .foregroundStyle(.white)
        .onTapGesture(count: 2) { model.openInLibrary(doc) }
        .help("Step to “\(doc.title)” — double-click to read")
    }

    // MARK: Ranks

    /// Walks a dimension outward from the focused cell, a few steps each
    /// way, guarding against cycles.
    private func rank(around doc: LiquidDoc, along dimension: Dimension,
                      reach: Int) -> (before: [LiquidDoc], after: [LiquidDoc]) {
        var before: [LiquidDoc] = []
        var after: [LiquidDoc] = []
        var visited: Set<String> = [doc.id]
        var cursor = doc
        for _ in 0..<reach {
            guard let previous = neighbors(of: cursor, along: dimension).previous,
                  visited.insert(previous.id).inserted else { break }
            before.insert(previous, at: 0)
            cursor = previous
        }
        cursor = doc
        for _ in 0..<reach {
            guard let next = neighbors(of: cursor, along: dimension).next,
                  visited.insert(next.id).inserted else { break }
            after.append(next)
            cursor = next
        }
        return (before, after)
    }

    /// One cell's previous and next along a dimension.
    private func neighbors(of doc: LiquidDoc,
                           along dimension: Dimension) -> (previous: LiquidDoc?, next: LiquidDoc?) {
        switch dimension {
        case .time:
            return adjacent(in: model.index.timeline.map(\.doc), around: doc)
        case .author:
            let rank = model.index.byID.values.map(\.doc)
                .filter { $0.author == doc.author }
                .sorted { ($0.listedDate, $0.id) < ($1.listedDate, $1.id) }
            return adjacent(in: rank, around: doc)
        case .type:
            let type = effectiveType(of: doc)
            let rank = model.index.byID.values.map(\.doc)
                .filter { effectiveType(of: $0) == type }
                .sorted { ($0.listedDate, $0.id) < ($1.listedDate, $1.id) }
            return adjacent(in: rank, around: doc)
        case .discourse:
            // Backwards: the document this one speaks to. Forwards: the
            // first document that speaks to this one.
            let discourse = Set(DocumentRelation.discourseActions.map(\.rawValue))
            let previous = doc.links
                .first { $0.rel.map(discourse.contains) ?? false }
                .map { model.index.latestRevision(of: LiquidAddress.canonical($0.to)) }
                .flatMap { model.index.byID[$0]?.doc }
            let next = (model.index.backlinks[doc.id] ?? [])
                .first { $0.rel.map(discourse.contains) ?? false }
                .flatMap { model.index.byID[$0.fromID]?.doc }
            return (previous, next)
        }
    }

    private func effectiveType(of doc: LiquidDoc) -> String {
        doc.documentType
            ?? (TranscriptsView.isTranscript(doc)
                ? LiquidDoc.DocumentType.transcript.rawValue
                : LiquidDoc.DocumentType.letter.rawValue)
    }

    private func adjacent(in rank: [LiquidDoc], around doc: LiquidDoc) -> (previous: LiquidDoc?, next: LiquidDoc?) {
        guard let index = rank.firstIndex(where: { $0.id == doc.id }) else { return (nil, nil) }
        return (index > 0 ? rank[index - 1] : nil,
                index < rank.count - 1 ? rank[index + 1] : nil)
    }
}

extension ZigZagView {
    /// ZigZag as an exchangeable module.
    @MainActor static let module = LibraryViewModule(
        id: "zigzag",
        name: "ZigZag",
        systemImage: "arrow.triangle.swap",
        makeContent: { AnyView(DocumentListView()) },
        makeDetail: { _ in AnyView(ZigZagView()) },
        hidesDocumentList: true
    )
}

